"use client";

import React, { useState, useEffect, useRef } from "react";
import {
  FileCode,
  FileCode2,
  CheckCircle2,
  AlertTriangle,
  AlertCircle,
  History,
  RotateCcw,
  Sparkles,
  Save,
  Check,
  Shield,
  Layers,
  Info,
  Clock,
  ArrowRight,
  ArrowLeft,
  Table,
  Search,
  Filter,
  RefreshCw,
  Plus,
  Download,
  ChevronDown,
  Activity,
  Cpu,
  XCircle,
  X,
  Eye,
  Copy,
  ExternalLink,
  Sliders,
  Award,
  Database,
  GitBranch,
  Terminal,
  Inbox,
  TrendingUp,
  FlaskConical,
  Trash2,
  Archive,
} from "lucide-react";
import { ActualPromptInspectorModal } from "@/components/prompt-inspector/ActualPromptInspectorModal";
import {
  api,
  formatApiErrorMessage,
  User,
  RuleItem,
  RulePrompt,
  PromptVersion,
  RulePromptSummaryItem,
  RuleIntelligenceData,
  PolicyQualityAssessmentResponse,
  QualityGateResult,
  QualitySummaryItem,
  PolicyDriftEventItem,
  PolicySimulationResult,
} from "@/lib/api";
import {
  buildQualityGatesExportFile,
  getQualityExportFormatLabel,
  triggerBlobDownload,
  type QualityExportFormat,
} from "@/lib/qualityExport";
import { RuleLearningDashboard } from "@/components/learning/RuleLearningDashboard";
import { AgentIntelligenceStudioOverview } from "@/components/compact/AgentIntelligenceStudioOverview";
import { CompactPageHeader } from "@/components/compact/CompactDesignSystem";
import { ReviewIncidentsWorkbench } from "@/components/compact/ReviewIncidentsWorkbench";
import { AiTestWorkbench } from "@/components/compact/AiTestWorkbench";
import { AccuracyLearningSummary } from "@/components/compact/AccuracyLearningSummary";
import { ManageVersionHistory } from "@/components/compact/ManageVersionHistory";
import { deriveOperationalStatus, deriveSiemRuleStatus } from "@/lib/diagnostics";
import { copyToClipboard as copyTextToClipboard } from "@/lib/clipboard";

function AgentIntelligenceStudioContent() {
  // Navigation / View mode
  const [viewMode, setViewMode] = useState<"table" | "studio">("table");
  const [studioTab, setStudioTab] = useState<"editor" | "intelligence" | "contract" | "quality" | "simulation" | "drift" | "learning" | "history">("editor");

  // Compact 3-Tab Architecture State
  const [primaryTab, setPrimaryTab] = useState<"incidents" | "ai_evaluation" | "accuracy" | "settings" | "overview" | "test_ai" | "learning" | "advanced">("incidents");
  const [reviewSubView, setReviewSubView] = useState<"incidents" | "overview">("incidents");
  const [advancedSection, setAdvancedSection] = useState<"overview" | "editor" | "intelligence" | "contract" | "quality" | "simulation" | "drift" | "history" | "manage_versions" | "xml" | "diagnostics" | "prompt_inspector" | "governance">("editor");
  const [compactUi, setCompactUi] = useState(true);
  const [learningProfile, setLearningProfile] = useState<any | null>(null);
  const [llmOnline, setLlmOnline] = useState<boolean | null>(null);
  const [evaluatingAccuracy, setEvaluatingAccuracy] = useState(false);

  // Rules & Summaries State
  const [rules, setRules] = useState<RuleItem[]>([]);
  const [summaries, setSummaries] = useState<RulePromptSummaryItem[]>([]);
  const [qualitySummary, setQualitySummary] = useState<QualitySummaryItem | null>(null);
  const [loadingRules, setLoadingRules] = useState(true);
  const [loadingSummaries, setLoadingSummaries] = useState(true);

  // Table Filters State
  const [searchFilter, setSearchFilter] = useState("");
  const [severityFilter, setSeverityFilter] = useState("");
  const [baselineFilter, setBaselineFilter] = useState("");
  const [archetypeFilter, setArchetypeFilter] = useState("");
  const [completenessFilter, setCompletenessFilter] = useState("");
  const [readinessFilter, setReadinessFilter] = useState("");
  const [page, setPage] = useState(1);
  const pageSize = 15;

  // Studio / Editor State
  const [selectedRuleId, setSelectedRuleId] = useState<string>("");
  const [rulePrompt, setRulePrompt] = useState<RulePrompt | null>(null);
  const [selectedVersionId, setSelectedVersionId] = useState<string>("");
  const [loadingPrompt, setLoadingPrompt] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [feedback, setFeedback] = useState<{ type: "success" | "error" | "warning"; text: string } | null>(null);
  const [ruleError, setRuleError] = useState<{ code: number; title: string; message: string } | null>(null);
  const [versionError, setVersionError] = useState<{ code: number; title: string; message: string; requestedVersionId: string } | null>(null);
  const [showRuleDetails, setShowRuleDetails] = useState(false);
  const promptRequestIdRef = useRef<number>(0);

  // Rule Intelligence & Semantics State
  const [intelligenceData, setIntelligenceData] = useState<RuleIntelligenceData | null>(null);
  const [loadingIntelligence, setLoadingIntelligence] = useState(false);

  // Policy Quality Validation State
  const [qualityAssessment, setQualityAssessment] = useState<PolicyQualityAssessmentResponse | null>(null);
  const [loadingQuality, setLoadingQuality] = useState(false);
  const [expandedGateIds, setExpandedGateIds] = useState<Record<string, boolean>>({});
  const toggleGateExpand = (gateId: string) => setExpandedGateIds((prev) => ({ ...prev, [gateId]: !prev[gateId] }));
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const isViewer = currentUser?.role === "Read-Only Viewer";
  const isAdmin = currentUser?.role === "Administrator";

  // Policy Simulation State
  const [simulationResult, setSimulationResult] = useState<PolicySimulationResult | null>(null);
  const [loadingSimulation, setLoadingSimulation] = useState(false);
  const [simulationProvider, setSimulationProvider] = useState<"OPENAI_COMPATIBLE" | "SIMULATED">("OPENAI_COMPATIBLE");
  const [showExclusions, setShowExclusions] = useState(false);

  // Funnel & Card Drilldown Pop-up Modal State
  const [drilldownModal, setDrilldownModal] = useState<{
    isOpen: boolean;
    cardType: "scanned" | "rule_matched" | "analyst_labeled" | "eligible" | "excluded" | "evaluated" | "confusion_tp" | "confusion_tn" | "confusion_fp" | "confusion_fn" | "confusion_abstained" | null;
    title: string;
    description: string;
    badgeCount: number;
    items: Array<any>;
  } | null>(null);
  const [drilldownSearch, setDrilldownSearch] = useState("");
  const [drilldownReasonFilter, setDrilldownReasonFilter] = useState<string>("ALL");
  const [drilldownCopied, setDrilldownCopied] = useState(false);

  // Drift Events State
  const [driftEvents, setDriftEvents] = useState<PolicyDriftEventItem[]>([]);
  const [loadingDrift, setLoadingDrift] = useState(false);

  // Bulk Audit Modal State
  const [showBulkAuditModal, setShowBulkAuditModal] = useState(false);
  const [bulkAuditJob, setBulkAuditJob] = useState<any | null>(null);
  const [bulkAuditLoading, setBulkAuditLoading] = useState(false);

  // Edit / Form state
  const [isEditing, setIsEditing] = useState(false);
  const [editCommon, setEditCommon] = useState("");
  const [editRuleSpecific, setEditRuleSpecific] = useState("");
  const [editConditions, setEditConditions] = useState("");
  const [editEvidence, setEditEvidence] = useState("");
  const [editTpIndicators, setEditTpIndicators] = useState("");
  const [editFpIndicators, setEditFpIndicators] = useState("");
  const [editMissingInfo, setEditMissingInfo] = useState("");
  const [editEscalation, setEditEscalation] = useState("");
  const [editQuestions, setEditQuestions] = useState<string[]>([]);
  const [newQuestionInput, setNewQuestionInput] = useState("");
  const [changeSummary, setChangeSummary] = useState("");

  // Approval modal state
  const [showApprovalModal, setShowApprovalModal] = useState(false);
  const [approvalSummary, setApprovalSummary] = useState("Approved by SOC Lead");

  // Revocation modal state
  const [showRevokeModal, setShowRevokeModal] = useState(false);
  const [revokeTargetVersion, setRevokeTargetVersion] = useState<PromptVersion | null>(null);
  const [revocationReason, setRevocationReason] = useState("");
  const [revoking, setRevoking] = useState(false);

  // Actual Prompt Inspector Modal state
  const [promptInspectorOpen, setPromptInspectorOpen] = useState(false);
  const [promptInspectorIncidentId, setPromptInspectorIncidentId] = useState<string | null>(null);
  const [promptInspectorRuleId, setPromptInspectorRuleId] = useState<string | null>(null);
  const [promptInspectorVersionId, setPromptInspectorVersionId] = useState<string | null>(null);
  const [promptInspectorInitialMode, setPromptInspectorInitialMode] = useState<"capture" | "preview">("capture");

  // Download / Export state
  const [downloadingExport, setDownloadingExport] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);
  const [showStudioExportMenu, setShowStudioExportMenu] = useState(false);
  const [showQualityExportMenu, setShowQualityExportMenu] = useState(false);
  const qualityExportMenuRef = useRef<HTMLDivElement | null>(null);

  const handleExportAll = async (format: "json" | "markdown" = "json") => {
    setDownloadingExport(true);
    setFeedback(null);
    setShowExportMenu(false);
    try {
      const { blob, filename } = await api.exportRulePrompts(format);
      triggerBlobDownload(blob, filename);
      setFeedback({
        type: "success",
        text: `Successfully exported rule-wise prompts and configuration (${format.toUpperCase()}).`,
      });
    } catch (err: any) {
      setFeedback({ type: "error", text: `Export failed: ${err.message}` });
    } finally {
      setDownloadingExport(false);
    }
  };

  const handleExportSingleRule = async (ruleId: string, format: "json" | "markdown" = "json") => {
    if (!ruleId) return;
    setDownloadingExport(true);
    setFeedback(null);
    setShowStudioExportMenu(false);
    try {
      const { blob, filename } = await api.exportSingleRulePrompt(ruleId, format);
      triggerBlobDownload(blob, filename);
      setFeedback({
        type: "success",
        text: `Downloaded rule prompt configuration (${format.toUpperCase()}).`,
      });
    } catch (err: any) {
      setFeedback({ type: "error", text: `Download failed: ${err.message}` });
    } finally {
      setDownloadingExport(false);
    }
  };

  const handleExportQualityGates = (format: QualityExportFormat = "json") => {
    if (!qualityAssessment) return;
    setShowQualityExportMenu(false);
    setFeedback(null);
    try {
      const activeRule = rules.find((r) => r.id === selectedRuleId || r.rule_id === selectedRuleId);
      const activeVersion = rulePrompt?.versions.find((v) => v.id === selectedVersionId);
      const { content, mimeType, filename } = buildQualityGatesExportFile(
        qualityAssessment,
        format,
        {
          ruleName: rulePrompt?.rule_name || activeRule?.name,
          ruleIdentifier:
            activeRule?.rule_id || qualityAssessment.rule_identifier || selectedRuleId,
          severity: activeRule?.severity,
          eventType: rulePrompt?.rule_event_type || activeRule?.event_type,
          versionNumber:
            activeVersion?.version_number ?? qualityAssessment.policy_version_number,
          versionStatus: activeVersion?.status,
        }
      );
      const blob = new Blob([content], { type: mimeType });
      triggerBlobDownload(blob, filename);
      setFeedback({
        type: "success",
        text: `Downloaded Quality Gates (G1–G8) output (${getQualityExportFormatLabel(format)}).`,
      });
    } catch (err: any) {
      setFeedback({
        type: "error",
        text: `Quality Gates export failed: ${err?.message || "Unknown error"}`,
      });
    }
  };

  const loadSummaries = async () => {
    setLoadingSummaries(true);
    try {
      const data = await api.getRulePromptsSummary();
      setSummaries(data);
      const qSummary = await api.getPolicyQualitySummary();
      setQualitySummary(qSummary);
    } catch (err: any) {
      console.error("Failed to load prompt summaries:", err);
    } finally {
      setLoadingSummaries(false);
    }
  };

  const loadRules = async () => {
    setLoadingRules(true);
    try {
      const res = await api.getRules({ page_size: 100 });
      setRules(res.items);
      return res.items;
    } catch (err: any) {
      console.error("Failed to load rules:", err);
      return [];
    } finally {
      setLoadingRules(false);
    }
  };

  const fetchLearningProfile = async (ruleId: string) => {
    if (!ruleId) {
      setLearningProfile(null);
      return;
    }
    try {
      const data = await api.getRuleLearningProfileDetail(ruleId);
      setLearningProfile(data);
    } catch (err) {
      console.error("Failed to load rule learning profile:", err);
    }
  };

  const handleEvaluateAccuracy = async () => {
    if (!selectedRuleId) return;
    setEvaluatingAccuracy(true);
    setPrimaryTab("learning");
    try {
      const res = await api.evaluateRuleAccuracy(selectedRuleId, undefined, selectedVersionId);
      const freshProfile = await api.getRuleLearningProfileDetail(selectedRuleId);
      setLearningProfile(freshProfile);
      setFeedback({
        type: res.empirical_accuracy !== null ? "success" : "warning",
        text: res.message || "Accuracy evaluation completed.",
      });
    } catch (err: any) {
      setFeedback({
        type: "error",
        text: formatApiErrorMessage(err, "Failed to evaluate rule accuracy"),
      });
    } finally {
      setEvaluatingAccuracy(false);
    }
  };

  const handleNavigateTab = (tab: "incidents" | "ai_evaluation" | "accuracy" | "settings" | "overview" | "test_ai" | "learning" | "advanced", section?: string) => {
    let normalizedTab: typeof primaryTab = tab;
    if (tab === "overview" || tab === "incidents") normalizedTab = "incidents";
    else if (tab === "test_ai" || tab === "ai_evaluation") normalizedTab = "ai_evaluation";
    else if (tab === "learning" || tab === "accuracy") normalizedTab = "accuracy";
    else if (tab === "advanced" || tab === "settings") normalizedTab = "settings";

    setPrimaryTab(normalizedTab);
    if (normalizedTab === "settings" && section) {
      setAdvancedSection(section as any);
      setStudioTab(section as any);
    } else if (normalizedTab === "accuracy") {
      setStudioTab("learning");
    }
    if (typeof window !== "undefined") {
      const url = new URL(window.location.href);
      url.searchParams.set("tab", section || normalizedTab);
      window.history.pushState({}, "", url.toString());
    }
  };

  // Initial data loading & URL query parameter check
  useEffect(() => {
    async function init() {
      api.getMe().then(setCurrentUser).catch(() => null);
      api.getLlmStatus().then((s) => setLlmOnline(Boolean(s?.is_healthy))).catch(() => setLlmOnline(false));

      if (typeof window !== "undefined") {
        const saved = localStorage.getItem("VERDICTUM_COMPACT_UI_ENABLED");
        if (saved !== null) {
          setCompactUi(saved === "true");
        }
      }

      const [fetchedRules] = await Promise.all([loadRules(), loadSummaries()]);

      if (typeof window !== "undefined") {
        const params = new URLSearchParams(window.location.search);
        const ruleParam = params.get("rule_id") || params.get("ruleId");
        const tabParam = params.get("tab");

        if (ruleParam) {
          const matched = (fetchedRules || []).find((r: RuleItem) => r.id === ruleParam || r.rule_id === ruleParam);
          setSelectedRuleId(matched ? matched.id : ruleParam);
          setViewMode("studio");
        }

        if (tabParam) {
          if (tabParam === "overview" || tabParam === "review" || tabParam === "incidents") {
            setPrimaryTab("incidents");
          } else if (tabParam === "test_ai" || tabParam === "test" || tabParam === "ai_evaluation") {
            setPrimaryTab("ai_evaluation");
          } else if (tabParam === "learning" || tabParam === "accuracy") {
            setPrimaryTab("accuracy");
            setStudioTab("learning");
          } else if (["overview_admin", "editor", "intelligence", "contract", "quality", "simulation", "drift", "history", "manage_versions", "xml", "diagnostics", "prompt_inspector", "governance", "advanced", "settings"].includes(tabParam)) {
            setPrimaryTab("settings");
            if (tabParam !== "advanced" && tabParam !== "settings") {
              setAdvancedSection(tabParam as any);
              setStudioTab(tabParam as any);
            }
          }
        }
      }
    }
    init();
  }, []);

  const clearForm = () => {
    setSelectedVersionId("");
    setEditCommon("");
    setEditRuleSpecific("");
    setEditConditions("");
    setEditEvidence("");
    setEditTpIndicators("");
    setEditFpIndicators("");
    setEditMissingInfo("");
    setEditEscalation("");
    setEditQuestions([]);
    setIsEditing(false);
    setIntelligenceData(null);
    setQualityAssessment(null);
    setSimulationResult(null);
    setDriftEvents([]);
    setLearningProfile(null);
  };

  const fetchPrompt = async (ruleId: string, explicitVersionId?: string) => {
    if (!ruleId) return;
    const reqId = ++promptRequestIdRef.current;
    setLoadingPrompt(true);
    setFeedback(null);
    setRuleError(null);
    setVersionError(null);

    try {
      const rp = await api.getRulePrompt(ruleId);
      if (reqId !== promptRequestIdRef.current) return;
      setRulePrompt(rp);
      setRuleError(null);

      if (rp.versions && rp.versions.length > 0) {
        let requestedVer = explicitVersionId;
        if (!requestedVer && typeof window !== "undefined") {
          const params = new URLSearchParams(window.location.search);
          requestedVer = params.get("version_id") || params.get("versionId") || undefined;
        }

        if (requestedVer) {
          const matchingVer = rp.versions.find((v) => v.id === requestedVer);
          if (matchingVer) {
            setSelectedVersionId(matchingVer.id);
            loadVersionIntoForm(matchingVer);
            setVersionError(null);
          } else {
            // Explicitly requested version does not exist! Do NOT silently fall back to historical v1!
            setVersionError({
              code: 404,
              title: "Version Unavailable",
              requestedVersionId: requestedVer,
              message: `The requested prompt policy version '${requestedVer}' does not exist for this rule.`,
            });
            setSelectedVersionId("");
            clearForm();
            setQualityAssessment(null);
            setSimulationResult(null);
          }
        } else {
          const targetId = rp.active_version_id || rp.versions[0].id;
          const targetVer = rp.versions.find((v) => v.id === targetId) || rp.versions[0];
          setSelectedVersionId(targetId);
          loadVersionIntoForm(targetVer);
          setVersionError(null);
        }
      } else {
        clearForm();
      }
    } catch (err: any) {
      if (reqId !== promptRequestIdRef.current) return;
      console.error("fetchPrompt error:", err);
      clearForm();
      setRulePrompt(null);
      setIntelligenceData(null);
      setLearningProfile(null);
      setQualityAssessment(null);
      setDriftEvents([]);
      setSimulationResult(null);
      setSelectedVersionId("");
      const is404 =
        err?.status === 404 ||
        err?.response?.status === 404 ||
        (err?.message && (err.message.includes("404") || err.message.toLowerCase().includes("not found")));
      setRuleError({
        code: is404 ? 404 : 500,
        title: is404 ? "Rule Not Found" : "Failed to Load Rule",
        message: is404
          ? `The requested detection rule could not be found or has been deleted (rule ID: '${ruleId}').`
          : (err.message || "An unexpected error occurred while loading this detection rule."),
      });
      setFeedback({ type: "error", text: err.message || "Rule not found" });
    } finally {
      if (reqId === promptRequestIdRef.current) {
        setLoadingPrompt(false);
      }
    }
  };

  const fetchIntelligence = async (ruleId: string) => {
    if (!ruleId) return;
    const reqId = promptRequestIdRef.current;
    setLoadingIntelligence(true);
    try {
      const intel = await api.getRuleIntelligence(ruleId);
      if (reqId !== promptRequestIdRef.current) return;
      setIntelligenceData(intel);
    } catch (err: any) {
      if (reqId !== promptRequestIdRef.current) return;
      console.error("Failed to load rule intelligence:", err);
      setIntelligenceData(null);
    } finally {
      if (reqId === promptRequestIdRef.current) {
        setLoadingIntelligence(false);
      }
    }
  };

  const fetchQualityPreview = async (ruleId: string, versionId?: string) => {
    if (!ruleId) return;
    const reqId = promptRequestIdRef.current;
    setLoadingQuality(true);
    try {
      const qRes = await api.previewPolicyQuality(ruleId, versionId);
      if (reqId !== promptRequestIdRef.current) return;
      setQualityAssessment(qRes);
    } catch (err: any) {
      if (reqId !== promptRequestIdRef.current) return;
      console.error("Failed to preview policy quality:", err);
      setQualityAssessment(null);
    } finally {
      if (reqId === promptRequestIdRef.current) {
        setLoadingQuality(false);
      }
    }
  };

  const fetchQualityValidation = async (ruleId: string, versionId?: string) => {
    if (!ruleId) return;
    const reqId = promptRequestIdRef.current;
    setLoadingQuality(true);
    try {
      const qRes = await api.validatePolicyQuality(ruleId, versionId);
      if (reqId !== promptRequestIdRef.current) return;
      setQualityAssessment(qRes);
    } catch (err: any) {
      if (reqId !== promptRequestIdRef.current) return;
      console.error("Failed to validate policy quality:", err);
      setFeedback({ type: "error", text: err.message || "Failed to validate policy quality" });
    } finally {
      if (reqId === promptRequestIdRef.current) {
        setLoadingQuality(false);
      }
    }
  };

  const fetchDriftEvents = async (ruleId: string) => {
    if (!ruleId) return;
    const reqId = promptRequestIdRef.current;
    setLoadingDrift(true);
    try {
      const evs = await api.getRuleDriftEvents(ruleId);
      if (reqId !== promptRequestIdRef.current) return;
      setDriftEvents(evs);
    } catch (err: any) {
      if (reqId !== promptRequestIdRef.current) return;
      console.error("Failed to load drift events:", err);
      setDriftEvents([]);
    } finally {
      if (reqId === promptRequestIdRef.current) {
        setLoadingDrift(false);
      }
    }
  };

  useEffect(() => {
    if (viewMode === "studio" && selectedRuleId) {
      fetchPrompt(selectedRuleId);
      fetchIntelligence(selectedRuleId);
      fetchDriftEvents(selectedRuleId);
      fetchLearningProfile(selectedRuleId);
    }
  }, [viewMode, selectedRuleId]);

  useEffect(() => {
    if (selectedRuleId && selectedVersionId) {
      fetchQualityPreview(selectedRuleId, selectedVersionId);
    }
  }, [selectedRuleId, selectedVersionId]);

  // Close drilldown modal on Escape
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        if (drilldownModal?.isOpen) {
          setDrilldownModal(null);
        }
        if (showQualityExportMenu) {
          setShowQualityExportMenu(false);
        }
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [drilldownModal, showQualityExportMenu]);

  // Close Quality Gates export dropdown when clicking outside
  useEffect(() => {
    if (!showQualityExportMenu) return;
    const handleMouseDown = (e: MouseEvent) => {
      if (
        qualityExportMenuRef.current &&
        !qualityExportMenuRef.current.contains(e.target as Node)
      ) {
        setShowQualityExportMenu(false);
      }
    };
    document.addEventListener("mousedown", handleMouseDown);
    return () => document.removeEventListener("mousedown", handleMouseDown);
  }, [showQualityExportMenu]);

  // Open modal for Funnel Cards (1. Scanned, 2. Rule-Matched, 3. Analyst-Labeled, 4. Eligible, 5. Excluded, 6. Evaluated)
  const openFunnelCardModal = (cardType: "scanned" | "rule_matched" | "analyst_labeled" | "eligible" | "excluded" | "evaluated") => {
    if (!simulationResult) return;
    setDrilldownSearch("");
    setDrilldownReasonFilter("ALL");

    if (cardType === "excluded") {
      const excludedItems = simulationResult.exclusions_detail || simulationResult.stage_details?.excluded || [];
      setDrilldownModal({
        isOpen: true,
        cardType: "excluded",
        title: "5. Excluded Incidents",
        description: "Historical incidents excluded from empirical ground-truth validation with documented exclusion justifications.",
        badgeCount: simulationResult.excluded_count ?? excludedItems.length,
        items: excludedItems,
      });
    } else if (cardType === "scanned") {
      const scannedItems = simulationResult.stage_details?.scanned || [
        ...(simulationResult.exclusions_detail || []).map((ex) => ({
          incident_id: ex.incident_id,
          rule_id: (ex as any).rule_id || "Unassigned / Mismatched",
          status: "EXCLUDED",
          reason: ex.reason,
          detail: ex.detail,
        })),
        ...(simulationResult.per_incident_results || []).map((res) => ({
          incident_id: res.incident_id,
          rule_id: res.rule_id,
          status: "RULE_MATCHED",
          reason: res.ground_truth || "EVALUATED",
          detail: `Effective verdict: ${res.effective_verdict} (Trust: ${res.trust_score}/10)`,
        })),
      ];
      setDrilldownModal({
        isOpen: true,
        cardType: "scanned",
        title: "1. Scanned Incidents",
        description: "All historical incidents retrieved and inspected from the historical dataset during simulation.",
        badgeCount: simulationResult.total_scanned ?? scannedItems.length,
        items: scannedItems,
      });
    } else if (cardType === "rule_matched") {
      const matchedItems = simulationResult.stage_details?.rule_matched || [
        ...(simulationResult.per_incident_results || []).map((res) => ({
          incident_id: res.incident_id,
          rule_id: res.rule_id,
          has_analyst_label: Boolean(res.ground_truth),
          resolution: res.ground_truth || "Unlabeled / Pending",
          detail: `Effective verdict: ${res.effective_verdict} (Trust: ${res.trust_score}/10)`,
        })),
      ];
      setDrilldownModal({
        isOpen: true,
        cardType: "rule_matched",
        title: "2. Rule-Matched Incidents",
        description: "Incidents whose alert rule association strictly matches the target rule under evaluation.",
        badgeCount: simulationResult.rule_matched ?? matchedItems.length,
        items: matchedItems,
      });
    } else if (cardType === "analyst_labeled") {
      const labeledItems = simulationResult.stage_details?.analyst_labeled || [
        ...(simulationResult.per_incident_results || [])
          .filter((res) => Boolean(res.ground_truth))
          .map((res) => ({
            incident_id: res.incident_id,
            rule_id: res.rule_id,
            resolution: res.ground_truth,
            comments: res.escalation_reason || "Documented in SIEM incident resolution",
            detail: `Resolution: ${res.ground_truth}`,
          })),
      ];
      setDrilldownModal({
        isOpen: true,
        cardType: "analyst_labeled",
        title: "3. Analyst-Labeled Incidents",
        description: "Incidents with closed resolution metadata recorded by human SOC analysts.",
        badgeCount: simulationResult.analyst_labeled ?? labeledItems.length,
        items: labeledItems,
      });
    } else if (cardType === "eligible") {
      const eligibleItems = simulationResult.stage_details?.eligible || [
        ...(simulationResult.per_incident_results || [])
          .filter((res) => res.ground_truth === "VERIFIED_TP" || res.ground_truth === "VERIFIED_FP")
          .map((res) => ({
            incident_id: res.incident_id,
            rule_id: res.rule_id,
            ground_truth: res.ground_truth,
            resolution: res.ground_truth === "VERIFIED_TP" ? "Confirmed True Positive" : "Verified False Positive",
            detail: `Independently verified ground-truth label: ${res.ground_truth}`,
          })),
      ];
      setDrilldownModal({
        isOpen: true,
        cardType: "eligible",
        title: "4. Eligible Ground Truth Incidents",
        description: "Independently verified human True Positive and False Positive benchmark controls eligible for empirical scoring.",
        badgeCount: simulationResult.eligible_ground_truth_count ?? eligibleItems.length,
        items: eligibleItems,
      });
    } else if (cardType === "evaluated") {
      const evalItems = simulationResult.per_incident_results || [];
      setDrilldownModal({
        isOpen: true,
        cardType: "evaluated",
        title: "6. Evaluated Incidents",
        description: "Incidents evaluated through policy directives, evidence contracts, and verdict trustworthiness scoring.",
        badgeCount: simulationResult.evaluated_cases ?? evalItems.length,
        items: evalItems,
      });
    }
  };

  // Open modal for Confusion Matrix cards
  const openConfusionModal = (bucket: "tp" | "tn" | "fp" | "fn" | "abstained") => {
    if (!simulationResult || !simulationResult.per_incident_results) return;
    setDrilldownSearch("");
    setDrilldownReasonFilter("ALL");

    const mapping = {
      tp: {
        title: "True Positives (Confirmed Attack Detected)",
        desc: "Incidents correctly identified as TRUE_POSITIVE aligned with verified malicious ground truth.",
        filter: (r: any) => r.effective_verdict === "TRUE_POSITIVE" && (r.ground_truth === "VERIFIED_TP" || r.is_correct === true),
      },
      tn: {
        title: "True Negatives (Benign Activity Cleared)",
        desc: "Incidents correctly identified as FALSE_POSITIVE aligned with verified benign ground truth.",
        filter: (r: any) => r.effective_verdict === "FALSE_POSITIVE" && (r.ground_truth === "VERIFIED_FP" || r.is_correct === true),
      },
      fp: {
        title: "False Positives (Benign Flagged as Attack)",
        desc: "Benign activity incorrectly classified as True Positive (Over-alerting).",
        filter: (r: any) =>
          r.effective_verdict === "TRUE_POSITIVE" &&
          (r.ground_truth === "VERIFIED_FP" ||
            (Boolean(r.ground_truth) && r.is_correct === false && r.is_critical_error === false)),
      },
      fn: {
        title: "False Negatives (Critical Missed Attacks)",
        desc: "Confirmed malicious incidents incorrectly dismissed as False Positive (Safety violation).",
        filter: (r: any) => r.effective_verdict === "FALSE_POSITIVE" && (r.ground_truth === "VERIFIED_TP" || r.is_critical_error === true),
      },
      abstained: {
        title: "Abstentions (Requires Analyst Review)",
        desc: "Incidents abstained due to missing mandatory evidence or contradictory telemetry.",
        filter: (r: any) => r.effective_verdict === "REQUIRES_ANALYST_ATTENTION" || r.is_abstained,
      },
    };

    const target = mapping[bucket];
    const filtered = simulationResult.per_incident_results.filter(target.filter);
    setDrilldownModal({
      isOpen: true,
      cardType: `confusion_${bucket}` as any,
      title: target.title,
      description: target.desc,
      badgeCount: filtered.length,
      items: filtered,
    });
  };

  const loadVersionIntoForm = (v: PromptVersion) => {
    setEditCommon(v.common_prompt || "");
    setEditRuleSpecific(v.rule_specific_prompt || "");
    setEditConditions(v.detection_conditions || "");
    setEditEvidence(v.required_evidence || "");
    setEditTpIndicators(v.tp_indicators || "");
    setEditFpIndicators(v.fp_indicators || "");
    setEditMissingInfo(v.missing_info_criteria || "");
    setEditEscalation(v.escalation_conditions || "");
    setEditQuestions(v.analyst_questions || []);
    setIsEditing(false);
  };

  const handleSelectVersion = (versionId: string) => {
    setSelectedVersionId(versionId);
    setVersionError(null);
    const v = rulePrompt?.versions.find((item) => item.id === versionId);
    if (v) {
      loadVersionIntoForm(v);
    } else if (versionId) {
      setVersionError({
        code: 404,
        title: "Version Unavailable",
        requestedVersionId: versionId,
        message: `The requested prompt policy version '${versionId}' does not exist for this rule.`,
      });
      clearForm();
    }
    if (typeof window !== "undefined") {
      const url = new URL(window.location.href);
      url.searchParams.set("version_id", versionId);
      window.history.pushState({}, "", url.toString());
    }
  };

  const handleOpenStudioForRule = (ruleId: string) => {
    setSelectedRuleId(ruleId);
    setRuleError(null);
    setVersionError(null);
    clearForm();
    setViewMode("studio");
    setPrimaryTab("overview");
    setStudioTab("editor");
    if (typeof window !== "undefined") {
      const url = new URL(window.location.href);
      url.searchParams.set("rule_id", ruleId);
      url.searchParams.delete("version_id");
      url.searchParams.delete("versionId");
      url.searchParams.set("tab", "overview");
      window.history.pushState({}, "", url.toString());
    }
  };

  const handleBackToTable = () => {
    setViewMode("table");
    setSelectedRuleId("");
    setSelectedVersionId("");
    setRuleError(null);
    setVersionError(null);
    clearForm();
    if (typeof window !== "undefined") {
      const url = new URL(window.location.href);
      url.searchParams.delete("rule_id");
      url.searchParams.delete("ruleId");
      url.searchParams.delete("version_id");
      url.searchParams.delete("versionId");
      window.history.pushState({}, "", url.toString());
    }
    loadSummaries();
  };

  const handleSwitchRuleInStudio = (ruleId: string) => {
    setSelectedRuleId(ruleId);
    setRuleError(null);
    setVersionError(null);
    clearForm();
    if (typeof window !== "undefined") {
      const url = new URL(window.location.href);
      url.searchParams.set("rule_id", ruleId);
      url.searchParams.delete("version_id");
      url.searchParams.delete("versionId");
      window.history.pushState({}, "", url.toString());
    }
  };

  // Generate AIS 2.0 Intelligent Draft
  const handleGenerateIntelligentDraft = async () => {
    if (!selectedRuleId) return;
    setActionLoading(true);
    setFeedback(null);
    try {
      const newDraft = await api.generateIntelligentDraft(selectedRuleId);
      await fetchPrompt(selectedRuleId);
      await fetchIntelligence(selectedRuleId);
      setSelectedVersionId(newDraft.id);
      loadVersionIntoForm(newDraft);
      setFeedback({
        type: "success",
        text: `Intelligent policy Version ${newDraft.version_number} synthesized from detection semantics and archetype rules.`,
      });
      loadSummaries();
    } catch (err: any) {
      setFeedback({ type: "error", text: err.message });
    } finally {
      setActionLoading(false);
    }
  };

  const handleSaveManualDraft = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedRuleId) return;
    setActionLoading(true);
    setFeedback(null);
    try {
      const newDraft = await api.createManualDraft(selectedRuleId, {
        common_prompt: editCommon,
        rule_specific_prompt: editRuleSpecific,
        detection_conditions: editConditions,
        required_evidence: editEvidence,
        tp_indicators: editTpIndicators,
        fp_indicators: editFpIndicators,
        missing_info_criteria: editMissingInfo,
        escalation_conditions: editEscalation,
        analyst_questions: editQuestions,
        change_summary: changeSummary || "Manual prompt update",
      });
      await fetchPrompt(selectedRuleId);
      setSelectedVersionId(newDraft.id);
      loadVersionIntoForm(newDraft);
      setIsEditing(false);
      setChangeSummary("");
      setFeedback({
        type: "success",
        text: `Manual draft Version ${newDraft.version_number} saved successfully. Quality revalidation required.`,
      });
      loadSummaries();
    } catch (err: any) {
      setFeedback({ type: "error", text: err.message });
    } finally {
      setActionLoading(false);
    }
  };

  // Run Simulation Lab evaluation
  const handleRunSimulation = async () => {
    if (!selectedRuleId) return;
    setLoadingSimulation(true);
    setFeedback(null);
    try {
      const res = await api.evaluatePolicySimulation(selectedRuleId, selectedVersionId, {
        provider_type: simulationProvider,
      });
      setSimulationResult(res);
      setStudioTab("simulation");
      setAdvancedSection("simulation");
      setPrimaryTab("advanced");
      const stat = res.status || res.simulation_status || "COMPLETED";
      setFeedback({
        type: stat === "FAILED" || stat === "EVALUATED_FAILED" ? "warning" : stat === "SIMULATED_ONLY" ? "warning" : "success",
        text: `Simulation Lab (${res.provider_type || simulationProvider}) completed: ${res.retrieved_count ?? res.sample_count} rule-matched incidents retrieved, ${res.scored_count ?? res.evaluated_cases ?? 0} verified scored. Status: ${stat}`,
      });
      // Synchronize G8 quality gate with fresh simulation results
      if (selectedVersionId) {
        await fetchQualityValidation(selectedRuleId, selectedVersionId);
      }
    } catch (err: any) {
      setFeedback({ type: "error", text: `Simulation failed: ${err.message}` });
    } finally {
      setLoadingSimulation(false);
    }
  };

  // Acknowledge Drift
  const handleAcknowledgeDrift = async () => {
    if (!selectedRuleId) return;
    setActionLoading(true);
    try {
      const res = await api.acknowledgeDriftEvents(selectedRuleId);
      await fetchDriftEvents(selectedRuleId);
      setFeedback({
        type: "success",
        text: `Acknowledged ${res.acknowledged_count} drift event(s). Policy monitoring updated.`,
      });
      loadSummaries();
    } catch (err: any) {
      setFeedback({ type: "error", text: `Failed to acknowledge drift: ${err.message}` });
    } finally {
      setActionLoading(false);
    }
  };

  // Bulk Quality Audit trigger
  const handleStartBulkAudit = async () => {
    setBulkAuditLoading(true);
    setShowBulkAuditModal(true);
    try {
      const job = await api.startBulkQualityAudit();
      setBulkAuditJob(job);
      await loadSummaries();
    } catch (err: any) {
      setFeedback({ type: "error", text: `Bulk audit failed: ${err.message}` });
    } finally {
      setBulkAuditLoading(false);
    }
  };

  const handleApprove = async () => {
    if (!selectedRuleId || !selectedVersionId) return;
    const versionBelongs = rulePrompt?.versions?.some((v) => v.id === selectedVersionId);
    if (!versionBelongs) {
      setFeedback({
        type: "error",
        text: "The selected prompt version does not match this rule.",
      });
      setShowApprovalModal(false);
      return;
    }
    setActionLoading(true);
    setFeedback(null);
    try {
      const approved = await api.approvePromptVersion(selectedRuleId, selectedVersionId, approvalSummary);
      await fetchPrompt(selectedRuleId);
      setShowApprovalModal(false);
      setFeedback({
        type: "success",
        text: `Version ${approved.version_number} approved and activated as production baseline. Evidence Contract synchronized.`,
      });
      loadSummaries();
    } catch (err: any) {
      setFeedback({ type: "error", text: `Approval blocked: ${err.message}` });
    } finally {
      setActionLoading(false);
    }
  };

  const handleRollback = async (targetVerId?: unknown) => {
    const versionIdToRollback = (typeof targetVerId === "string" ? targetVerId : null) || selectedVersionId;
    if (!selectedRuleId || !versionIdToRollback) return;
    const targetVer = rulePrompt?.versions.find((v) => v.id === versionIdToRollback) || selectedVersion;
    if (targetVer?.status === "REVOKED") {
      setFeedback({
        type: "error",
        text: `Cannot rollback to Version ${targetVer?.version_number} because it has been REVOKED. Revoked policies are permanently retired and cannot be reactivated.`,
      });
      return;
    }
    if (targetVer?.status !== "APPROVED") {
      setFeedback({
        type: "error",
        text: `Cannot rollback to Version ${targetVer?.version_number} because its status is ${targetVer?.status}. Only APPROVED policy versions can be restored.`,
      });
      return;
    }
    if (!confirm(`Are you sure you want to rollback production prompt to Version ${targetVer?.version_number}? This will create a new approved baseline based on this snapshot.`)) return;
    setActionLoading(true);
    setFeedback(null);
    try {
      const rolled = await api.rollbackPromptVersion(selectedRuleId, versionIdToRollback);
      await fetchPrompt(selectedRuleId);
      setSelectedVersionId(rolled.id);
      loadVersionIntoForm(rolled);
      setFeedback({
        type: "success",
        text: `Rollback successful: Activated new Version ${rolled.version_number}.`,
      });
      loadSummaries();
    } catch (err: any) {
      setFeedback({ type: "error", text: err.message });
    } finally {
      setActionLoading(false);
    }
  };

  const handleOpenRevoke = (ver: PromptVersion) => {
    setRevokeTargetVersion(ver);
    setRevocationReason("");
    setShowRevokeModal(true);
  };

  const handleConfirmRevoke = async () => {
    if (!selectedRuleId || !revokeTargetVersion || revocationReason.trim().length < 5) return;
    setRevoking(true);
    try {
      await api.revokePromptVersion(selectedRuleId, revokeTargetVersion.id, revocationReason.trim());
      await fetchPrompt(selectedRuleId);
      setShowRevokeModal(false);
      setRevokeTargetVersion(null);
      setRevocationReason("");
      setFeedback({
        type: "warning",
        text: `Policy Version ${revokeTargetVersion.version_number} has been REVOKED. AI verdict execution is suspended until an approved replacement is validated.`,
      });
      loadSummaries();
    } catch (err: any) {
      setFeedback({ type: "error", text: `Revocation failed: ${err.message}` });
    } finally {
      setRevoking(false);
    }
  };

  const handleAddQuestion = () => {
    if (newQuestionInput.trim()) {
      setEditQuestions([...editQuestions, newQuestionInput.trim()]);
      setNewQuestionInput("");
    }
  };

  const handleRemoveQuestion = (idx: number) => {
    setEditQuestions(editQuestions.filter((_, i) => i !== idx));
  };

  const getSeverityBadge = (sev: string) => {
    switch (sev?.toUpperCase()) {
      case "CRITICAL":
        return "bg-rose-950/80 text-rose-300 border-rose-800";
      case "HIGH":
        return "bg-orange-950/80 text-orange-300 border-orange-800";
      case "MEDIUM":
        return "bg-amber-950/80 text-amber-300 border-amber-800";
      default:
        return "bg-blue-950/80 text-blue-300 border-blue-800";
    }
  };

  const getScoreBadge = (score: number | null | undefined) => {
    if (score === null || score === undefined) {
      return "bg-slate-900 text-slate-400 border-slate-800";
    }
    if (score >= 80) {
      return "bg-emerald-950/80 text-emerald-300 border-emerald-800";
    }
    if (score >= 60) {
      return "bg-amber-950/80 text-amber-300 border-amber-800";
    }
    return "bg-rose-950/80 text-rose-300 border-rose-800";
  };

  const getReadinessBadge = (status?: string) => {
    switch (status?.toUpperCase()) {
      case "ACTIVE":
        return {
          label: "ACTIVE",
          classes: "bg-emerald-950 text-emerald-300 border-emerald-800",
        };
      case "APPROVED":
        return {
          label: "APPROVED",
          classes: "bg-teal-950 text-teal-300 border-teal-800",
        };
      case "READY_FOR_APPROVAL":
        return {
          label: "READY FOR APPROVAL",
          classes: "bg-cyan-950 text-cyan-300 border-cyan-800 animate-pulse",
        };
      case "VALIDATING":
        return {
          label: "VALIDATING",
          classes: "bg-blue-950 text-blue-300 border-blue-800",
        };
      case "LEARNING":
        return {
          label: "LEARNING",
          classes: "bg-amber-950 text-amber-300 border-amber-800",
        };
      case "BLOCKED":
        return {
          label: "BLOCKED",
          classes: "bg-rose-950 text-rose-300 border-rose-800",
        };
      case "INCOMPLETE":
      default:
        return {
          label: status ? status.replace(/_/g, " ") : "INCOMPLETE",
          classes: "bg-slate-900 text-slate-400 border-slate-800",
        };
    }
  };

  // Filter summaries for table
  const filteredSummaries = summaries.filter((item) => {
    if (searchFilter) {
      const q = searchFilter.toLowerCase();
      const matchName = item.rule_name.toLowerCase().includes(q);
      const matchEvent = item.event_type.toLowerCase().includes(q);
      const matchSource = (item.data_source || "").toLowerCase().includes(q);
      const matchArchetype = (item.detection_archetype || "").toLowerCase().includes(q);
      if (!matchName && !matchEvent && !matchSource && !matchArchetype) return false;
    }
    if (severityFilter && item.severity.toUpperCase() !== severityFilter.toUpperCase()) {
      return false;
    }
    if (baselineFilter === "APPROVED" && !item.has_approved_prompt) {
      return false;
    }
    if (baselineFilter === "DRAFT" && (item.has_approved_prompt || item.total_versions === 0)) {
      return false;
    }
    if (baselineFilter === "NONE" && item.total_versions > 0) {
      return false;
    }
    if (archetypeFilter && item.detection_archetype !== archetypeFilter) {
      return false;
    }
    if (completenessFilter && item.definition_completeness !== completenessFilter) {
      return false;
    }
    if (readinessFilter) {
      const r = item.production_readiness_status;
      if (readinessFilter === "BLOCKED" && r !== "BLOCKED" && r !== "INCOMPLETE") {
        return false;
      } else if (readinessFilter !== "BLOCKED" && r !== readinessFilter) {
        return false;
      }
    }
    return true;
  });

  const totalPages = Math.ceil(filteredSummaries.length / pageSize) || 1;
  const paginatedSummaries = filteredSummaries.slice((page - 1) * pageSize, page * pageSize);

  // Metrics Counters
  const totalRulesCount = summaries.length;
  const approvedPromptsCount = summaries.filter((s) => s.has_approved_prompt).length;
  const draftOnlyCount = summaries.filter((s) => !s.has_approved_prompt && s.total_versions > 0).length;
  const missingBaselineCount = summaries.filter((s) => s.total_versions === 0).length;
  const incompleteDefinitionCount = summaries.filter((s) => s.definition_completeness === "INCOMPLETE").length;
  const driftAlertCount = summaries.filter((s) => s.revalidation_required).length;

  const selectedRule = rules.find((r) => r.id === selectedRuleId || r.rule_id === selectedRuleId);
  const selectedVersion = rulePrompt?.versions.find((v) => v.id === selectedVersionId);
  const isSelectedActive = selectedVersion?.id === rulePrompt?.active_version_id;

  // Archetypes List for Filter
  const archetypeOptions = Array.from(
    new Set(summaries.map((s) => s.detection_archetype).filter(Boolean))
  );

  // =========================================================================
  // VIEW 1: RULES DIRECTORY TABLE
  // =========================================================================
  if (viewMode === "table") {
    return (
      <div className="space-y-4">
        {/* Page Header */}
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 border-b border-slate-800 pb-3.5">
          <div>
            <div className="flex items-center gap-2.5">
              <h1 className="text-lg sm:text-xl font-bold tracking-tight text-slate-100 flex items-center gap-2">
                <FileCode2 className="w-5 h-5 text-violet-400" />
                Verdictum AI — Agent Intelligence Studio 2.1
              </h1>
              <span className="px-2 py-0.5 rounded-full text-[10px] font-semibold bg-violet-950/80 text-violet-300 border border-violet-800/60 font-mono">
                Powered by WYSETEK Systems
              </span>
            </div>
            <p className="text-xs text-slate-400 mt-1">
              Build, validate, and govern AI detection policies.
            </p>
          </div>

          <div className="flex items-center gap-2 flex-wrap">
            {selectedRuleId && (
              <button
                type="button"
                onClick={() => setViewMode("studio")}
                className="px-3.5 py-1.5 text-xs rounded-lg bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 text-white font-semibold flex items-center gap-1.5 transition-all shadow-md shadow-violet-900/20"
              >
                <span>Open Studio</span>
                <ArrowRight className="w-3.5 h-3.5" />
              </button>
            )}

            <button
              onClick={() => {
                loadSummaries();
                loadRules();
              }}
              disabled={loadingSummaries}
              className="px-2.5 py-1.5 text-xs rounded-lg border border-slate-700 bg-slate-900 hover:bg-slate-800 text-slate-300 font-medium flex items-center gap-1.5 transition-colors"
            >
              <RefreshCw className={`w-3.5 h-3.5 text-cyan-400 ${loadingSummaries ? "animate-spin" : ""}`} />
              <span>Refresh</span>
            </button>

            {/* Contextual More Actions Dropdown */}
            <div className="relative">
              <button
                type="button"
                onClick={() => setShowExportMenu((prev) => !prev)}
                className="px-2.5 py-1.5 text-xs rounded-lg border border-slate-700 bg-slate-900 hover:bg-slate-800 text-slate-200 font-medium flex items-center gap-1.5 transition-colors"
                title="Secondary administrative operations"
              >
                <span>More Actions</span>
                <ChevronDown className={`w-3 h-3 text-slate-400 transition-transform ${showExportMenu ? "rotate-180" : ""}`} />
              </button>

              {showExportMenu && (
                <div className="absolute right-0 mt-1 w-56 rounded-xl border border-slate-800 bg-slate-950 py-1.5 shadow-2xl z-30 text-xs divide-y divide-slate-800/60">
                  <div className="py-1">
                    <button
                      type="button"
                      onClick={() => {
                        setShowExportMenu(false);
                        handleStartBulkAudit();
                      }}
                      disabled={bulkAuditLoading}
                      className="w-full text-left px-3 py-1.5 hover:bg-slate-900 text-slate-200 flex items-center gap-2"
                    >
                      <Layers className="w-3.5 h-3.5 text-indigo-400" />
                      <span>Bulk Audit Rules</span>
                    </button>

                    <button
                      type="button"
                      onClick={() => {
                        setShowExportMenu(false);
                        setPromptInspectorIncidentId(null);
                        setPromptInspectorRuleId(selectedRuleId || (selectedRule ? selectedRule.id : null));
                        setPromptInspectorVersionId(selectedVersionId || null);
                        setPromptInspectorInitialMode("capture");
                        setPromptInspectorOpen(true);
                      }}
                      className="w-full text-left px-3 py-1.5 hover:bg-slate-900 text-slate-200 flex items-center gap-2"
                    >
                      <Terminal className="w-3.5 h-3.5 text-emerald-400" />
                      <span>View Actual LLM Prompt</span>
                    </button>
                  </div>

                  <div className="py-1">
                    <div className="px-3 py-1 text-[10px] uppercase font-bold text-slate-500">Download Rule Prompts</div>
                    <button
                      type="button"
                      onClick={() => {
                        setShowExportMenu(false);
                        handleExportAll("json");
                      }}
                      disabled={downloadingExport}
                      className="w-full text-left px-3 py-1.5 hover:bg-slate-900 text-slate-200 flex items-center justify-between"
                    >
                      <span className="flex items-center gap-1.5">
                        <Download className="w-3 h-3 text-cyan-400" />
                        Download JSON
                      </span>
                      <span className="text-[10px] text-slate-500 font-mono">.json</span>
                    </button>
                    <button
                      type="button"
                      onClick={() => {
                        setShowExportMenu(false);
                        handleExportAll("markdown");
                      }}
                      disabled={downloadingExport}
                      className="w-full text-left px-3 py-1.5 hover:bg-slate-900 text-slate-200 flex items-center justify-between"
                    >
                      <span className="flex items-center gap-1.5">
                        <Download className="w-3 h-3 text-cyan-400" />
                        Download Markdown
                      </span>
                      <span className="text-[10px] text-slate-500 font-mono">.md</span>
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Top Metrics Cards (6 Compact KPI Cards) */}
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-2.5">
          <div className="p-3 rounded-xl border border-slate-800/80 bg-slate-900/60 shadow-sm">
            <div className="text-[10px] uppercase font-bold text-slate-400 flex items-center justify-between">
              <span>Monitored Rules</span>
              <FileCode className="w-3.5 h-3.5 text-slate-500" />
            </div>
            <div className="text-xl font-bold font-mono text-slate-100 mt-1">{totalRulesCount}</div>
            <div className="text-[10px] text-slate-500 mt-0.5">Active SIEM rules</div>
          </div>

          <div className="p-3 rounded-xl border border-slate-800/80 bg-slate-900/60 shadow-sm">
            <div className="text-[10px] uppercase font-bold text-slate-400 flex items-center justify-between">
              <span>Approved Policies</span>
              <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
            </div>
            <div className="text-xl font-bold font-mono text-emerald-400 mt-1">{approvedPromptsCount}</div>
            <div className="text-[10px] text-slate-500 mt-0.5">
              {totalRulesCount ? Math.round((approvedPromptsCount / totalRulesCount) * 100) : 0}% of rules active
            </div>
          </div>

          <div className="p-3 rounded-xl border border-slate-800/80 bg-slate-900/60 shadow-sm">
            <div className="text-[10px] uppercase font-bold text-slate-400 flex items-center justify-between">
              <span>Drafts</span>
              <Sparkles className="w-3.5 h-3.5 text-sky-400" />
            </div>
            <div className="text-xl font-bold font-mono text-sky-300 mt-1">{draftOnlyCount}</div>
            <div className="text-[10px] text-slate-500 mt-0.5">Drafts awaiting review</div>
          </div>

          <div className="p-3 rounded-xl border border-slate-800/80 bg-slate-900/60 shadow-sm">
            <div className="text-[10px] uppercase font-bold text-slate-400 flex items-center justify-between">
              <span>Average Quality</span>
              <Award className="w-3.5 h-3.5 text-cyan-400" />
            </div>
            <div className="text-xl font-bold font-mono text-cyan-300 mt-1">
              {qualitySummary ? `${Math.round(qualitySummary.quality_score_average)}/100` : "Not evaluated"}
            </div>
            <div className="text-[10px] text-slate-500 mt-0.5">Static verification index</div>
          </div>

          <div className="p-3 rounded-xl border border-slate-800/80 bg-slate-900/60 shadow-sm">
            <div className="text-[10px] uppercase font-bold text-slate-400 flex items-center justify-between">
              <span>Incomplete Definitions</span>
              <AlertCircle className="w-3.5 h-3.5 text-amber-400" />
            </div>
            <div className="text-xl font-bold font-mono text-amber-300 mt-1">{incompleteDefinitionCount}</div>
            <div className="text-[10px] text-slate-500 mt-0.5">Unresolved SIEM logic</div>
          </div>

          <div className="p-3 rounded-xl border border-slate-800/80 bg-slate-900/60 shadow-sm">
            <div className="text-[10px] uppercase font-bold text-slate-400 flex items-center justify-between">
              <span>Drift / Revalidation</span>
              <AlertTriangle className="w-3.5 h-3.5 text-rose-400" />
            </div>
            <div className="text-xl font-bold font-mono text-rose-400 mt-1">{driftAlertCount}</div>
            <div className="text-[10px] text-slate-500 mt-0.5">Requires re-audit</div>
          </div>
        </div>

        {/* Informational Architecture Banner */}
        <div className="p-2.5 rounded-xl border border-slate-800/80 bg-slate-950/60 text-xs text-slate-300 flex items-center justify-between gap-2.5">
          <div className="flex items-center gap-2">
            <Info className="w-4 h-4 text-cyan-400 shrink-0" />
            <span className="text-[11px] text-slate-300">
              <strong className="text-cyan-300">Agent Intelligence Studio Governance:</strong> 12 detection archetypes, 8 mandatory quality gates (G1–G8), simulation regression testing, and drift governance.
            </span>
          </div>
          <span className="text-[10px] font-mono text-slate-400 shrink-0 hidden md:inline"><strong className="text-cyan-400">Verdictum AI 2.1</strong> • Powered by WYSETEK Systems</span>
        </div>

        {/* Filter & Search Toolbar */}
        <div className="p-2.5 rounded-lg border border-slate-800 bg-slate-900/30 flex flex-wrap items-center justify-between gap-2">
          <div className="flex-1 min-w-[200px] relative">
            <Search className="w-3.5 h-3.5 text-slate-500 absolute left-2.5 top-1/2 -translate-y-1/2" />
            <input
              type="text"
              value={searchFilter}
              onChange={(e) => {
                setSearchFilter(e.target.value);
                setPage(1);
              }}
              placeholder="Search rules, archetypes, event types, or data sources..."
              className="w-full pl-8 pr-3 py-1.5 text-xs rounded border border-slate-800 bg-slate-950 text-slate-200 placeholder-slate-500 focus:outline-none focus:border-cyan-500"
            />
          </div>

          <div className="flex flex-wrap items-center gap-1.5">
            <select
              value={archetypeFilter}
              onChange={(e) => {
                setArchetypeFilter(e.target.value);
                setPage(1);
              }}
              className="px-2.5 py-1 text-xs rounded border border-slate-800 bg-slate-950 text-slate-300 focus:outline-none focus:border-cyan-500"
            >
              <option value="">All Archetypes</option>
              {archetypeOptions.map((arch) => (
                <option key={arch} value={arch}>
                  {arch}
                </option>
              ))}
            </select>

            <select
              value={completenessFilter}
              onChange={(e) => {
                setCompletenessFilter(e.target.value);
                setPage(1);
              }}
              className="px-2.5 py-1 text-xs rounded border border-slate-800 bg-slate-950 text-slate-300 focus:outline-none focus:border-cyan-500"
            >
              <option value="">All Definitions</option>
              <option value="VERIFIED">Verified Definition</option>
              <option value="INCOMPLETE">Incomplete / Unresolved</option>
              <option value="UNKNOWN">Unknown Status</option>
            </select>

            <select
              value={severityFilter}
              onChange={(e) => {
                setSeverityFilter(e.target.value);
                setPage(1);
              }}
              className="px-2.5 py-1 text-xs rounded border border-slate-800 bg-slate-950 text-slate-300 focus:outline-none focus:border-cyan-500"
            >
              <option value="">All Severities</option>
              <option value="CRITICAL">Critical</option>
              <option value="HIGH">High</option>
              <option value="MEDIUM">Medium</option>
              <option value="LOW">Low</option>
            </select>

            <select
              value={baselineFilter}
              onChange={(e) => {
                setBaselineFilter(e.target.value);
                setPage(1);
              }}
              className="px-2.5 py-1 text-xs rounded border border-slate-800 bg-slate-950 text-slate-300 focus:outline-none focus:border-cyan-500"
            >
              <option value="">All Baselines</option>
              <option value="APPROVED">Production Approved</option>
              <option value="DRAFT">Template Draft</option>
              <option value="NONE">No Baseline</option>
            </select>

            <select
              value={readinessFilter}
              onChange={(e) => {
                setReadinessFilter(e.target.value);
                setPage(1);
              }}
              className="px-2.5 py-1 text-xs rounded border border-slate-800 bg-slate-950 text-slate-300 focus:outline-none focus:border-cyan-500"
            >
              <option value="">All Readiness States</option>
              <option value="BLOCKED">Blocked / Incomplete</option>
              <option value="LEARNING">Learning</option>
              <option value="VALIDATING">Validating</option>
              <option value="READY_FOR_APPROVAL">Ready for Approval</option>
              <option value="APPROVED">Approved</option>
              <option value="ACTIVE">Active</option>
            </select>

            {(searchFilter || archetypeFilter || completenessFilter || severityFilter || baselineFilter || readinessFilter) && (
              <button
                type="button"
                onClick={() => {
                  setSearchFilter("");
                  setArchetypeFilter("");
                  setCompletenessFilter("");
                  setSeverityFilter("");
                  setBaselineFilter("");
                  setReadinessFilter("");
                  setPage(1);
                }}
                className="px-2 py-1 text-xs text-rose-400 hover:text-rose-300 font-medium transition-colors"
              >
                Clear Filters
              </button>
            )}
          </div>
        </div>

        {/* Rules Table */}
        <div className="rounded-lg border border-slate-800 bg-slate-950 overflow-hidden shadow-sm">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs">
              <thead>
                <tr className="border-b border-slate-800 bg-slate-900/60 text-[10px] font-mono text-slate-400">
                  <th className="py-2.5 px-3 font-semibold min-w-[220px]">Rule Name &amp; Event Type</th>
                  <th className="py-2.5 px-2 font-semibold w-24">Severity</th>
                  <th className="py-2.5 px-2 font-semibold w-32">Archetype</th>
                  <th className="py-2.5 px-2 font-semibold w-28">Definition</th>
                  <th className="py-2.5 px-2 font-semibold w-28">Quality Score</th>
                  <th className="py-2.5 px-3 font-semibold w-32">Baseline Status</th>
                  <th className="py-2.5 px-3 font-semibold w-40">Production Readiness</th>
                  <th className="py-2.5 px-2 font-semibold w-20">Drift Flag</th>
                  <th className="py-2.5 px-3 font-semibold text-right sticky right-0 bg-slate-900/95 backdrop-blur-xs shadow-[-8px_0_12px_-4px_rgba(0,0,0,0.5)] w-44">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/60">
                {loadingSummaries ? (
                  <tr>
                    <td colSpan={9} className="py-12 text-center text-slate-400 text-xs">
                      <RefreshCw className="w-5 h-5 animate-spin mx-auto mb-2 text-cyan-400" />
                      Loading Agent Intelligence Studio rule directory...
                    </td>
                  </tr>
                ) : paginatedSummaries.length === 0 ? (
                  <tr>
                    <td colSpan={9} className="py-12 text-center text-slate-500 text-xs">
                      No detection rules match the specified search or filter criteria.
                    </td>
                  </tr>
                ) : (
                  paginatedSummaries.map((item) => {
                    const isApproved = item.has_approved_prompt;
                    const hasDraft = !isApproved && item.total_versions > 0;
                    const isIncomplete = item.definition_completeness === "INCOMPLETE";
                    const rBadge = getReadinessBadge(item.production_readiness_status);
                    const gates = item.gates_passed_count ?? 0;
                    const missing = item.missing_requirements_count ?? 0;

                    return (
                      <tr
                        key={item.rule_id}
                        onClick={() => handleOpenStudioForRule(item.rule_id)}
                        className="hover:bg-slate-900/60 cursor-pointer transition-colors group"
                      >
                        <td className="py-2.5 px-3">
                          <div className="font-semibold text-slate-200 group-hover:text-cyan-400 transition-colors max-w-[280px] truncate" title={item.rule_name}>
                            {item.rule_name}
                          </div>
                          <div className="text-[10px] font-mono text-slate-400 mt-0.5 flex items-center gap-1.5">
                            <span>{item.event_type}</span>
                            {item.data_source && (
                              <span className="text-slate-500">({item.data_source})</span>
                            )}
                          </div>
                        </td>

                        <td className="py-2 px-2">
                          <span className={`px-1.5 py-0.5 rounded border text-[9px] font-bold ${getSeverityBadge(item.severity)}`}>
                            {item.severity}
                          </span>
                        </td>

                        <td className="py-2 px-2">
                          <span className="px-1.5 py-0.5 rounded text-[10px] font-mono bg-sky-950/80 text-sky-300 border border-sky-800/70">
                            {item.detection_archetype || "UNKNOWN"}
                          </span>
                        </td>

                        <td className="py-2 px-2">
                          {item.definition_completeness === "VERIFIED" ? (
                            <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[9px] font-semibold bg-emerald-950/80 text-emerald-300 border border-emerald-800">
                              <CheckCircle2 className="w-2.5 h-2.5" /> VERIFIED
                            </span>
                          ) : isIncomplete ? (
                            <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[9px] font-semibold bg-amber-950/80 text-amber-300 border border-amber-800" title="Authoritative threshold or logic missing. Blocked from approval.">
                              <AlertCircle className="w-2.5 h-2.5" /> INCOMPLETE
                            </span>
                          ) : (
                            <span className="px-1.5 py-0.5 rounded text-[9px] text-slate-400 font-mono">
                              {item.definition_completeness || "UNKNOWN"}
                            </span>
                          )}
                        </td>

                        <td className="py-2 px-2">
                          <span className={`px-2 py-0.5 rounded text-[10px] font-mono font-bold border ${getScoreBadge(item.quality_score)}`}>
                            {item.quality_score !== null && item.quality_score !== undefined
                              ? `${item.quality_score}/100`
                              : "—"}
                          </span>
                        </td>

                        <td className="py-2 px-3">
                          {isApproved ? (
                            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-semibold bg-emerald-950 text-emerald-400 border border-emerald-800">
                              <CheckCircle2 className="w-3 h-3 text-emerald-400" />
                              v{item.active_version_number || 1} Active
                            </span>
                          ) : hasDraft ? (
                            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-semibold bg-sky-950 text-sky-400 border border-sky-800">
                              <Sparkles className="w-3 h-3 text-sky-400" />
                              v{item.active_version_number || 1} Draft
                            </span>
                          ) : (
                            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-semibold bg-slate-900 text-slate-400 border border-slate-800">
                              No Baseline
                            </span>
                          )}
                        </td>

                        <td className="py-2 px-3">
                          <div className="flex flex-col gap-0.5">
                            <span className={`inline-block px-1.5 py-0.5 rounded border text-[9px] font-bold ${rBadge.classes} w-fit`}>
                              {rBadge.label}
                            </span>
                            <div className="text-[10px] text-slate-400 font-mono">
                              Gates: <span className="text-slate-300">{gates}/8</span>
                              {missing > 0 && (
                                <span className="ml-1.5 text-amber-400">({missing} missing)</span>
                              )}
                            </div>
                          </div>
                        </td>

                        <td className="py-2 px-2">
                          {item.revalidation_required ? (
                            <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[9px] font-bold bg-rose-950 text-rose-300 border border-rose-800 animate-pulse" title="SIEM rule changed or feedback logged. Revalidation required.">
                              <AlertTriangle className="w-2.5 h-2.5" /> DRIFT
                            </span>
                          ) : (
                            <span className="text-[10px] text-slate-600 font-mono">Clean</span>
                          )}
                        </td>

                        <td className="py-2.5 px-3 text-right sticky right-0 bg-slate-950/95 group-hover:bg-slate-900/95 backdrop-blur-xs shadow-[-8px_0_12px_-4px_rgba(0,0,0,0.5)]">
                          <div className="inline-flex items-center gap-1.5 justify-end">
                            <button
                              type="button"
                              onClick={(e) => {
                                e.stopPropagation();
                                setPromptInspectorIncidentId(null);
                                setPromptInspectorRuleId(item.rule_id);
                                setPromptInspectorVersionId(null);
                                setPromptInspectorInitialMode("capture");
                                setPromptInspectorOpen(true);
                              }}
                              title={`Inspect actual prompt payload for ${item.rule_name}`}
                              className="p-1.5 rounded-lg border border-slate-800 bg-slate-900/80 hover:bg-slate-800 text-slate-400 hover:text-emerald-400 transition-colors"
                            >
                              <Terminal className="w-3.5 h-3.5" />
                            </button>
                            <button
                              type="button"
                              onClick={(e) => {
                                e.stopPropagation();
                                handleExportSingleRule(item.rule_id, "json");
                              }}
                              disabled={downloadingExport}
                              title="Download rule prompt configuration (JSON)"
                              className="p-1.5 rounded-lg border border-slate-800 bg-slate-900/80 hover:bg-slate-800 text-slate-400 hover:text-cyan-300 transition-colors"
                            >
                              <Download className="w-3.5 h-3.5" />
                            </button>
                            <button
                              type="button"
                              onClick={(e) => {
                                e.stopPropagation();
                                handleOpenStudioForRule(item.rule_id);
                              }}
                              className="px-2.5 py-1 text-xs rounded-lg border border-cyan-800/80 bg-cyan-950/40 hover:bg-cyan-900/60 text-cyan-300 font-semibold inline-flex items-center gap-1 transition-colors shadow-sm"
                            >
                              <span>Open Studio</span>
                              <ArrowRight className="w-3 h-3" />
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>

          {/* Table Pagination */}
          <div className="p-3 border-t border-slate-800 bg-slate-900/40 flex items-center justify-between text-xs text-slate-400">
            <div>
              Showing {filteredSummaries.length > 0 ? (page - 1) * pageSize + 1 : 0} to{" "}
              {Math.min(page * pageSize, filteredSummaries.length)} of {filteredSummaries.length} rules
            </div>
            <div className="flex items-center gap-2">
              <button
                disabled={page <= 1}
                onClick={() => setPage((p) => Math.max(p - 1, 1))}
                className="px-2.5 py-1 text-xs rounded border border-slate-800 bg-slate-950 hover:bg-slate-900 disabled:opacity-40 disabled:cursor-not-allowed text-slate-300"
              >
                Previous
              </button>
              <span className="font-mono text-slate-300">
                {page} / {totalPages}
              </span>
              <button
                disabled={page >= totalPages}
                onClick={() => setPage((p) => Math.min(p + 1, totalPages))}
                className="px-2.5 py-1 text-xs rounded border border-slate-800 bg-slate-950 hover:bg-slate-900 disabled:opacity-40 disabled:cursor-not-allowed text-slate-300"
              >
                Next
              </button>
            </div>
          </div>
        </div>

        {/* Bulk Audit Modal */}
        {showBulkAuditModal && (
          <div className="fixed inset-0 z-50 bg-black/75 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-slate-950 border border-slate-800 rounded-lg max-w-lg w-full p-4 space-y-3 shadow-2xl">
              <div className="flex items-center justify-between border-b border-slate-800 pb-2">
                <div className="flex items-center gap-2 text-indigo-400">
                  <Layers className="w-4 h-4" />
                  <h3 className="text-sm font-bold text-slate-100">Bulk Quality Audit Engine</h3>
                </div>
                <button
                  onClick={() => setShowBulkAuditModal(false)}
                  className="text-slate-400 hover:text-slate-200"
                >
                  ✕
                </button>
              </div>

              {bulkAuditLoading ? (
                <div className="py-8 text-center text-slate-400 text-xs space-y-2">
                  <RefreshCw className="w-6 h-6 animate-spin mx-auto text-indigo-400" />
                  <p>Processing batch audit across detection rules (bounded chunking: 100/chunk)...</p>
                </div>
              ) : bulkAuditJob ? (
                <div className="space-y-3 text-xs">
                  <div className="p-2.5 rounded bg-slate-900/60 border border-slate-800 space-y-1">
                    <div className="flex justify-between text-slate-400">
                      <span>Job ID:</span>
                      <span className="font-mono text-slate-200">{bulkAuditJob.job_id}</span>
                    </div>
                    <div className="flex justify-between text-slate-400">
                      <span>Rules Evaluated:</span>
                      <span className="font-bold text-slate-100">{bulkAuditJob.total_rules_processed}</span>
                    </div>
                    <div className="flex justify-between text-slate-400">
                      <span>Static Checks Passed:</span>
                      <span className="text-emerald-400 font-semibold">{bulkAuditJob.passed_count}</span>
                    </div>
                    <div className="flex justify-between text-slate-400">
                      <span>Reviews Required:</span>
                      <span className="text-amber-400 font-semibold">{bulkAuditJob.review_required_count}</span>
                    </div>
                    <div className="flex justify-between text-slate-400">
                      <span>Critical / Hard Blockers:</span>
                      <span className="text-rose-400 font-semibold">{bulkAuditJob.critical_count}</span>
                    </div>
                  </div>
                  <p className="text-[11px] text-slate-400 italic">
                    Bulk assessment operates in strict read-only mode and does not alter approved baselines.
                  </p>
                </div>
              ) : (
                <p className="text-xs text-slate-400">Ready to initiate bulk static validation.</p>
              )}

              <div className="flex justify-end pt-2">
                <button
                  type="button"
                  onClick={() => setShowBulkAuditModal(false)}
                  className="px-3 py-1 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded text-xs font-semibold"
                >
                  Close
                </button>
              </div>
            </div>
          </div>
        )}
        {/* Actual LLM Prompt Inspector Modal (Table View) */}
        <ActualPromptInspectorModal
          isOpen={promptInspectorOpen}
          onClose={() => setPromptInspectorOpen(false)}
          incidentId={promptInspectorIncidentId}
          ruleId={promptInspectorRuleId || selectedRuleId || (selectedRule ? selectedRule.id : null)}
          ruleName={selectedRule ? selectedRule.name : undefined}
          versionId={promptInspectorVersionId || selectedVersionId || undefined}
          initialMode={promptInspectorInitialMode}
        />
      </div>
    );
  }

  // =========================================================================
  // VIEW 2: RULE PROMPT STUDIO (EDITOR & INSPECTION VIEW)
  // =========================================================================
  const isIncompleteDefinition = intelligenceData?.semantics?.definition_status === "INCOMPLETE";
  const blockingIssuesList = qualityAssessment?.blocking_issues || qualityAssessment?.blocking_findings || [];
  const hasHardGateFailure = blockingIssuesList.length > 0;
  const gateList: QualityGateResult[] = qualityAssessment?.gate_results
    ? Object.values(qualityAssessment.gate_results)
    : qualityAssessment?.gates || [];
  const passedGatesCount = gateList.filter((g) => g.status === "PASSED").length;
  const isApprovalEligible =
    (qualityAssessment?.approval_eligible ?? false) &&
    !isIncompleteDefinition &&
    !hasHardGateFailure &&
    passedGatesCount === 8 &&
    (learningProfile?.total_analyst_reviews || 0) >= 30;

  const studioQualityScore = qualityAssessment?.quality_score ?? null;
  const filledSegments =
    studioQualityScore !== null
      ? Math.max(0, Math.min(20, Math.round((studioQualityScore / 100) * 20)))
      : 0;
  const operationalStatus = (ruleError || versionError)
    ? null
    : deriveOperationalStatus({
      lifecycleStage: learningProfile?.lifecycle_stage,
      isApprovalEligible,
      isIncompleteDefinition,
      activeVersionStatus: selectedVersion?.status,
      hasHardGateFailure,
      totalAnalystReviews: learningProfile?.total_analyst_reviews || 0,
      qualityScore: qualityAssessment?.quality_score,
    });

  const activeVersion = rulePrompt?.versions.find((v) => v.id === rulePrompt.active_version_id) || null;
  const candidateDraft = rulePrompt?.versions.find((v) => v.status === "DRAFT") || null;

  const nextRecommendedAction = (() => {
    if (!rulePrompt || rulePrompt.versions.length === 0) {
      return {
        label: "Create Draft Policy",
        description: "No investigation policy exists for this detection rule. Author a baseline draft to begin.",
        action: () => {
          setPrimaryTab("advanced");
          setAdvancedSection("editor");
        },
        buttonText: "Create Baseline Draft",
        badge: "Baseline Missing",
        badgeColor: "bg-amber-950/80 text-amber-300 border-amber-800",
      };
    }
    if (selectedVersion?.status === "DRAFT" && (!qualityAssessment || qualityAssessment.quality_score === null || (qualityAssessment as any).overall_status === "UNVALIDATED" || qualityAssessment.validation_status === "UNVALIDATED")) {
      return {
        label: "Validate Draft Policy",
        description: `Candidate draft policy v${selectedVersion.version_number} requires deterministic quality gate evaluation (G1–G8).`,
        action: () => {
          if (selectedVersionId) fetchQualityValidation(selectedRuleId, selectedVersionId);
          setPrimaryTab("advanced");
          setAdvancedSection("quality");
        },
        buttonText: "Validate Draft (G1–G8)",
        badge: "Validation Pending",
        badgeColor: "bg-sky-950/80 text-sky-300 border-sky-800",
      };
    }
    if (hasHardGateFailure) {
      return {
        label: "Inspect Validation Issues",
        description: "Mandatory quality gate evaluation failed on blocking requirements. Resolve blockers before proceeding.",
        action: () => {
          setPrimaryTab("settings");
          setAdvancedSection("quality");
        },
        buttonText: "Inspect Quality Blockers",
        badge: "Blockers Present",
        badgeColor: "bg-rose-950/80 text-rose-300 border-rose-800",
      };
    }
    if ((learningProfile?.total_analyst_reviews || 0) < 30) {
      const remaining = 30 - (learningProfile?.total_analyst_reviews || 0);
      return {
        label: "Start Analyst Review",
        description: `${remaining} more double-blind analyst review${remaining === 1 ? "" : "s"} required to establish empirical ground truth baseline.`,
        action: () => {
          setPrimaryTab("incidents");
          setTimeout(() => {
            const el = document.getElementById("analyst-determination-form") || document.getElementById("incident-review-workbench");
            if (el) {
              el.scrollIntoView({ behavior: "smooth", block: "center" });
              el.classList.add("ring-2", "ring-cyan-500/80");
              setTimeout(() => {
                el.classList.remove("ring-2", "ring-cyan-500/80");
              }, 1500);
            }
          }, 80);
        },
        buttonText: "Start Double-Blind Review",
        badge: "Ground Truth Needed",
        badgeColor: "bg-indigo-950/80 text-indigo-300 border-indigo-800",
      };
    }
    if (learningProfile) {
      const totalReviews = learningProfile.total_analyst_reviews || 0;
      const verifiedTp = learningProfile.verified_tp_count || 0;
      const verifiedFp = learningProfile.verified_fp_count || 0;
      const decisive = (learningProfile.error_distribution?.decisive_evaluations ?? 0);

      // Class balance check: Tier 2 Supervised Pilot requires >= 10 TP and >= 10 FP
      if (totalReviews >= 30 && verifiedTp < 10) {
        return {
          label: "Collect True Positive Ground Truth",
          description: `${totalReviews} reviews collected (${verifiedTp} TP / ${verifiedFp} FP). At least 10 independently confirmed True Positive cases required for pilot calibration baseline. Currently 0 decisive AI predictions.`,
          action: () => {
            setPrimaryTab("incidents");
            setTimeout(() => {
              const el = document.getElementById("analyst-determination-form") || document.getElementById("incident-review-workbench");
              if (el) {
                el.scrollIntoView({ behavior: "smooth", block: "center" });
                el.classList.add("ring-2", "ring-cyan-500/80");
                setTimeout(() => {
                  el.classList.remove("ring-2", "ring-cyan-500/80");
                }, 1500);
              }
            }, 80);
          },
          buttonText: "Review Incidents Queue",
          badge: "Class Balance Needed",
          badgeColor: "bg-amber-950/80 text-amber-300 border-amber-800",
        };
      }

      if (learningProfile.empirical_accuracy === null) {
        return {
          label: "Evaluate Accuracy",
          description: decisive === 0
            ? `${totalReviews} verified reviews (${verifiedTp} TP / ${verifiedFp} FP). 0 decisive AI comparisons (16 abstentions, 15 un-evaluated). Click to compute empirical metrics.`
            : `${totalReviews} verified analyst reviews collected. Compute empirical accuracy and confusion matrix.`,
          action: handleEvaluateAccuracy,
          buttonText: evaluatingAccuracy ? "Evaluating..." : "Evaluate Accuracy",
          badge: decisive === 0 ? "Evaluation Needed" : "Evaluation Ready",
          badgeColor: "bg-teal-950/80 text-teal-300 border-teal-800",
        };
      }
    }
    if (isApprovalEligible && selectedVersion?.status !== "APPROVED") {
      return {
        label: "Request Administrator Approval",
        description: "All 8 mandatory quality gates and empirical accuracy criteria satisfied. Ready for production promotion sign-off.",
        action: () => {
          setShowApprovalModal(true);
        },
        buttonText: "Request Approval",
        badge: "Production Ready",
        badgeColor: "bg-emerald-950/80 text-emerald-300 border-emerald-800",
      };
    }
    return {
      label: "Run AI Simulation / Verification",
      description: "Approved baseline is active. Test real Local AWQ model inference against live SIEM incidents.",
      action: () => {
        setPrimaryTab("ai_evaluation");
      },
      buttonText: "Run AI Verification",
      badge: "Operational Active",
      badgeColor: "bg-cyan-950/80 text-cyan-300 border-cyan-800",
    };
  })();

  return (
    <div className="space-y-3">
      {compactUi ? (
        /* =========================================================================
           COMPACT MODE (3 TABS): SIMPLE BY DEFAULT — ADVANCED ON DEMAND
           ========================================================================= */
        <>
          {/* SECTION 1: COMPACT RULE TOOLBAR */}
          <CompactPageHeader
            title={ruleError ? "Rule Not Found" : (selectedRule?.name || selectedRuleId)}
            subtitle={
              showRuleDetails
                ? (intelligenceData?.semantics?.detection_objective || "Governed policy generation, quality validation, evidence contract alignment, and simulation regression testing.")
                : undefined
            }
            archetype={showRuleDetails ? (ruleError ? undefined : (intelligenceData?.classification?.primary_archetype || "DETECTION ENGINE")) : undefined}
            siemStatus={ruleError ? undefined : deriveSiemRuleStatus(selectedRule?.status)}
            activePolicy={
              ruleError || versionError || !activeVersion
                ? undefined
                : {
                    versionNumber: activeVersion.version_number,
                    status: activeVersion.status || "APPROVED",
                  }
            }
            draftPolicy={
              ruleError || versionError || !candidateDraft || candidateDraft.id === activeVersion?.id
                ? undefined
                : {
                    versionNumber: candidateDraft.version_number,
                    status: candidateDraft.status || "DRAFT",
                  }
            }
            lifecycleStatus={
              ruleError
                ? undefined
                : versionError
                  ? {
                    label: "Version Unavailable",
                    badgeClass: "bg-amber-950/70 border-amber-800 text-amber-300",
                    dotClass: "bg-amber-400",
                  }
                  : operationalStatus || undefined
            }
            backAction={{
              label: "Rules List",
              onClick: handleBackToTable,
            }}
            selector={
              <div className="flex items-center gap-1.5">
                <label className="text-[10px] font-semibold text-slate-400 uppercase tracking-wider shrink-0">
                  Rule:
                </label>
                <select
                  value={selectedRuleId}
                  onChange={(e) => handleSwitchRuleInStudio(e.target.value)}
                  disabled={loadingRules}
                  className="px-2 py-1 text-xs rounded-lg border border-cyan-500/40 bg-slate-900 text-slate-200 font-medium focus:outline-none focus:border-cyan-400 max-w-[220px] truncate"
                >
                  {selectedRuleId && !rules.some((r) => r.id === selectedRuleId) && (
                    <option value={selectedRuleId} disabled>
                      -- Rule Not Found ({selectedRuleId}) --
                    </option>
                  )}
                  {rules.map((r) => (
                    <option key={r.id} value={r.id}>
                      {r.name} ({r.severity})
                    </option>
                  ))}
                </select>
              </div>
            }
            actions={
              <div className="flex items-center gap-2">
                {!ruleError && (
                  <button
                    type="button"
                    onClick={() => setShowRuleDetails(!showRuleDetails)}
                    className={`px-2 py-1 rounded-lg border text-xs font-semibold flex items-center gap-1 transition-colors ${
                      showRuleDetails
                        ? "border-cyan-500 bg-cyan-950/60 text-cyan-200"
                        : "border-slate-800 bg-slate-900/60 hover:bg-slate-800 text-slate-400 hover:text-slate-200"
                    }`}
                    title="Toggle rule metadata and detection objective details"
                  >
                    <Info className="w-3.5 h-3.5 text-cyan-400" />
                    <span>Details</span>
                    <ChevronDown className={`w-3 h-3 transition-transform ${showRuleDetails ? "rotate-180" : ""}`} />
                  </button>
                )}
                <span className="hidden xl:inline text-[10px] font-mono text-slate-400 border-l border-slate-800 pl-2">
                  <strong className="text-cyan-400">Verdictum AI 2.1</strong> • WYSETEK Systems
                </span>
                <button
                  type="button"
                  onClick={() => {
                    setCompactUi(false);
                    if (typeof window !== "undefined") {
                      localStorage.setItem("VERDICTUM_COMPACT_UI_ENABLED", "false");
                    }
                  }}
                  className="px-2.5 py-1 rounded-lg border border-slate-700 bg-slate-900 text-slate-400 hover:text-slate-200 text-xs font-mono"
                  title="Switch to detailed legacy 7-tab layout"
                >
                  Legacy View
                </button>
              </div>
            }
          />

          {/* Expandable Secondary Rule Details Drawer */}
          {showRuleDetails && !ruleError && (
            <div data-testid="rule-details-drawer" className="p-3 rounded-xl border border-slate-800/80 bg-slate-900/80 text-xs space-y-2 animate-in fade-in duration-150">
              <div className="flex flex-wrap items-center justify-between gap-2 border-b border-slate-800/60 pb-2">
                <div className="flex flex-wrap items-center gap-2">
                  <span className="font-semibold text-slate-300">Archetype:</span>
                  <span className="font-mono text-cyan-300 bg-slate-950 px-2 py-0.5 rounded border border-cyan-800/50">
                    {intelligenceData?.classification?.primary_archetype || "DETECTION ENGINE"}
                  </span>
                  <span className="text-slate-600">•</span>
                  <span className="font-semibold text-slate-300">SIEM Status:</span>
                  <span className="font-mono text-slate-300 bg-slate-950 px-2 py-0.5 rounded border border-slate-800">
                    {selectedRule?.status === "ACTIVE" ? "SIEM Active" : selectedRule?.status ? `SIEM ${selectedRule.status}` : "SIEM Inactive"}
                  </span>
                  <span className="text-slate-600">•</span>
                  <span className="font-semibold text-slate-300">Tenant:</span>
                  <span className="font-mono text-slate-300 bg-slate-950 px-2 py-0.5 rounded border border-slate-800">
                    {selectedRule?.customer || "DEFAULT"}
                  </span>
                  <span className="text-slate-600">•</span>
                  <span className="font-semibold text-slate-300">Stage:</span>
                  <span className="font-mono text-violet-300 bg-violet-950/60 px-2 py-0.5 rounded border border-violet-800/60">
                    {learningProfile?.is_production_eligible ? "Production Verified" : (learningProfile?.total_analyst_reviews || 0) >= 30 ? "Validation Ready" : (learningProfile?.total_analyst_reviews || 0) > 0 ? "Supervised Learning" : "Awaiting Reviews"}
                  </span>
                </div>
                <div className="font-mono text-[10px] text-slate-500">
                  UUID: {selectedRule?.id || selectedRuleId}
                </div>
              </div>
              <p className="text-[11px] text-slate-400 leading-relaxed">
                {intelligenceData?.semantics?.detection_objective || "Governed policy generation, quality validation, evidence contract alignment, and simulation regression testing."}
              </p>
            </div>
          )}

          {/* Fail-Safe Handling: Rule Not Found (404) */}
          {ruleError ? (
            <div data-testid="ais-rule-not-found" className="p-6 rounded-xl border border-rose-800/80 bg-rose-950/40 text-slate-200 space-y-4">
              <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                <div className="flex items-center gap-3">
                  <div className="p-2.5 rounded-lg bg-rose-900/60 border border-rose-700/80 text-rose-300 shrink-0">
                    <AlertCircle className="w-6 h-6" />
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <h2 className="text-base font-bold text-rose-200">{ruleError.title}</h2>
                      <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-rose-900/90 text-rose-300 border border-rose-700">
                        HTTP {ruleError.code}
                      </span>
                    </div>
                    <p className="text-xs text-rose-300/90 mt-1">{ruleError.message}</p>
                  </div>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <button
                    type="button"
                    onClick={handleBackToTable}
                    className="px-3 py-1.5 rounded-lg border border-slate-700 bg-slate-900 hover:bg-slate-800 text-slate-200 text-xs font-semibold flex items-center gap-1.5 transition-colors"
                  >
                    <ArrowLeft className="w-3.5 h-3.5" />
                    Back to Rules
                  </button>
                  <button
                    type="button"
                    onClick={() => fetchPrompt(selectedRuleId)}
                    className="px-3 py-1.5 rounded-lg border border-rose-700 bg-rose-900/60 hover:bg-rose-900 text-rose-200 text-xs font-semibold flex items-center gap-1.5 transition-colors"
                  >
                    <RefreshCw className="w-3.5 h-3.5" />
                    Retry
                  </button>
                </div>
              </div>
              <div className="p-3 rounded-lg bg-slate-950/80 border border-slate-800/80 text-[11px] text-slate-400 space-y-1">
                <div className="font-semibold text-slate-300">Fail-Safe Security Policy:</div>
                <p>Detection rule specification could not be located in the SIEM registry. All policy evaluations, production approval gates, and autonomous execution are blocked.</p>
              </div>
            </div>
          ) : versionError ? (
            /* Fail-Safe Handling: Version Unavailable (404) */
            <div data-testid="ais-version-unavailable" className="p-6 rounded-xl border border-amber-800/80 bg-amber-950/40 text-slate-200 space-y-4">
              <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                <div className="flex items-center gap-3">
                  <div className="p-2.5 rounded-lg bg-amber-900/60 border border-amber-700/80 text-amber-300 shrink-0">
                    <AlertTriangle className="w-6 h-6" />
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <h2 className="text-base font-bold text-amber-200">{versionError.title}</h2>
                      <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-amber-900/90 text-amber-300 border border-amber-700">
                        HTTP {versionError.code}
                      </span>
                    </div>
                    <p className="text-xs text-amber-300/90 mt-1">{versionError.message}</p>
                  </div>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <button
                    type="button"
                    onClick={handleBackToTable}
                    className="px-3 py-1.5 rounded-lg border border-slate-700 bg-slate-900 hover:bg-slate-800 text-slate-200 text-xs font-semibold flex items-center gap-1.5 transition-colors"
                  >
                    <ArrowLeft className="w-3.5 h-3.5" />
                    Back to Rules
                  </button>
                  {rulePrompt?.active_version_id && (
                    <button
                      type="button"
                      onClick={() => handleSelectVersion(rulePrompt.active_version_id!)}
                      className="px-3 py-1.5 rounded-lg border border-cyan-700 bg-cyan-950/80 hover:bg-cyan-900 text-cyan-200 text-xs font-semibold flex items-center gap-1.5 transition-colors"
                    >
                      Load Active Policy v{rulePrompt.active_version?.version_number || 1}
                    </button>
                  )}
                </div>
              </div>
              <div className="p-3 rounded-lg bg-slate-950/80 border border-slate-800/80 text-[11px] text-slate-400 space-y-1">
                <div className="font-semibold text-slate-300">Version Isolation Guarantee:</div>
                <p>The system will not silently display or promote an alternative policy version. To continue, select a valid policy version or return to the rules catalog.</p>
              </div>
            </div>
          ) : (
            <>
              {/* SECTION 2: COMPACT RECOMMENDED NEXT ACTION NOTICE */}
              <div className="p-2 sm:px-3 rounded-xl border border-cyan-800/50 bg-gradient-to-r from-cyan-950/30 via-slate-900/50 to-slate-950/50 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2 text-xs">
                <div className="flex items-center gap-2 min-w-0">
                  <div className="p-1 rounded-md bg-cyan-900/40 border border-cyan-700/60 text-cyan-300 shrink-0">
                    <Sparkles className="w-3.5 h-3.5" />
                  </div>
                  <div className="flex items-center gap-2 truncate">
                    <span className="font-bold text-cyan-200 shrink-0" title="Next Recommended Action:">
                      Next Recommended Action: Action needed:
                    </span>
                    <span className="text-slate-300 truncate">
                      {nextRecommendedAction.description}
                    </span>
                    <span className={`hidden md:inline px-1.5 py-0.2 rounded text-[10px] font-mono border shrink-0 ${nextRecommendedAction.badgeColor}`}>
                      {nextRecommendedAction.badge}
                    </span>
                  </div>
                </div>
                <button
                  type="button"
                  data-testid="next-action-button"
                  onClick={nextRecommendedAction.action}
                  className="px-2.5 py-1 rounded-lg bg-cyan-600 hover:bg-cyan-500 text-slate-950 font-bold text-xs flex items-center gap-1.5 shrink-0 shadow-sm transition-all"
                >
                  {nextRecommendedAction.buttonText}
                  <ArrowRight className="w-3 h-3" />
                </button>
              </div>

              {/* SECTION 3: PRIMARY 3-TAB BAR + SECONDARY SETTINGS */}
              <div data-testid="ais-primary-tabs" className="flex items-center justify-between border-b border-slate-800/90 pb-0 text-xs">
                <div className="flex space-x-1">
                  {/* TAB 1: Review Incidents */}
                  <button
                    data-testid="tab-overview"
                    onClick={() => handleNavigateTab("incidents")}
                    className={`px-3 py-1.5 font-bold border-b-2 transition-colors flex items-center gap-1.5 rounded-t-lg ${
                      primaryTab === "incidents" || primaryTab === "overview"
                        ? "border-cyan-400 text-cyan-300 bg-slate-900/60"
                        : "border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-900/30"
                    }`}
                    title="Overview: Review incoming FortiSIEM incidents and record ground-truth analyst verdicts"
                  >
                    <Inbox className="w-4 h-4 text-cyan-400" />
                    <span>Review Incidents</span>
                  </button>

                  {/* TAB 2: Test AI */}
                  <button
                    data-testid="tab-test-ai"
                    onClick={() => handleNavigateTab("ai_evaluation")}
                    className={`px-3 py-1.5 font-bold border-b-2 transition-colors flex items-center gap-1.5 rounded-t-lg ${
                      primaryTab === "ai_evaluation" || primaryTab === "test_ai"
                        ? "border-cyan-400 text-cyan-300 bg-slate-900/60"
                        : "border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-900/30"
                    }`}
                    title="Test AI inference against incidents and track model evaluation performance"
                  >
                    <FlaskConical className="w-4 h-4 text-amber-400" />
                    <span>Test AI</span>
                  </button>

                  {/* TAB 3: Accuracy & Learning */}
                  <button
                    data-testid="tab-learning"
                    onClick={() => handleNavigateTab("accuracy")}
                    className={`px-3 py-1.5 font-bold border-b-2 transition-colors flex items-center gap-1.5 rounded-t-lg ${
                      primaryTab === "accuracy" || primaryTab === "learning"
                        ? "border-cyan-400 text-cyan-300 bg-slate-900/60"
                        : "border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-900/30"
                    }`}
                    title="Analyst Review & Learning: Empirical accuracy, class balance calibration, and Tier 2 pilot eligibility"
                  >
                    <Shield className="w-4 h-4 text-emerald-400" />
                    <span>Accuracy &amp; Learning</span>
                    {learningProfile?.total_analyst_reviews !== undefined && (
                      <span className="px-1.5 py-0.2 rounded-full text-[10px] bg-slate-800 text-slate-300 font-mono">
                        {learningProfile.total_analyst_reviews}
                      </span>
                    )}
                  </button>
                </div>

                {/* ADMINISTRATIVE SETTINGS CONTROL (SECONDARY) */}
                <div className="flex items-center gap-2">
                  <button
                    data-testid="tab-advanced"
                    onClick={() => handleNavigateTab("settings")}
                    className={`px-2.5 py-1.5 font-medium border-b-2 transition-colors flex items-center gap-1.5 rounded-t-lg ${
                      primaryTab === "settings" || primaryTab === "advanced"
                        ? "border-cyan-400 text-cyan-300 bg-slate-900/60"
                        : "border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-900/30"
                    }`}
                    title="Advanced Configuration: Administrative policy controls and configuration"
                  >
                    <Sliders className="w-3.5 h-3.5 text-sky-400" />
                    <span className="hidden sm:inline">Advanced Settings</span>
                    <span className="sm:hidden">Settings</span>
                    {blockingIssuesList.length > 0 && (
                      <span className="px-1.5 py-0.2 rounded-full text-[9px] bg-amber-950 text-amber-300 border border-amber-800">
                        {blockingIssuesList.length}
                      </span>
                    )}
                  </button>
                </div>
              </div>
            </>
          )}
        </>
      ) : (
        /* =========================================================================
           LEGACY 7-TAB MODE (PRESERVED FOR FULL BACKWARD COMPATIBILITY)
           ========================================================================= */
        <>
          <div className="p-2.5 sm:px-3 rounded-xl theme-glass-panel flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2">
            <div className="flex items-center gap-2.5">
              <button
                type="button"
                onClick={handleBackToTable}
                className="px-2.5 py-1.5 rounded-lg theme-secondary-btn text-xs font-semibold flex items-center gap-1.5 transition-colors"
              >
                <ArrowLeft className="w-3.5 h-3.5 text-cyan-400" />
                <Table className="w-3.5 h-3.5 text-slate-400" />
                Rules List
              </button>

              <div>
                <div className="flex items-center gap-2 flex-wrap">
                  <h1 className="text-base sm:text-lg font-bold tracking-tight text-slate-100">
                    Agent Intelligence Studio 2.0
                  </h1>
                  <span className="px-2 py-0.5 rounded-full text-[10px] font-semibold bg-slate-950/80 text-slate-300 border border-slate-700/80 font-mono uppercase tracking-wide">
                    {intelligenceData?.classification?.primary_archetype || "DETECTION ENGINE"}
                  </span>
                </div>
                <p className="text-[11px] text-slate-400 mt-0.5">
                  Governed policy generation, 8-gate quality validation, evidence contract alignment, and simulation regression checks.
                </p>
              </div>
            </div>

            <div className="flex items-center gap-2 w-full sm:w-auto">
              <label className="text-[10px] font-semibold text-slate-400 uppercase tracking-wider shrink-0">
                Select Rule:
              </label>
              <select
                value={selectedRuleId}
                onChange={(e) => handleSwitchRuleInStudio(e.target.value)}
                disabled={loadingRules}
                className="px-2.5 py-1.5 text-xs rounded-lg border border-cyan-500/40 bg-slate-950/90 text-slate-200 font-medium focus:outline-none focus:border-cyan-400 min-w-[240px] max-w-[380px] truncate w-full sm:w-auto"
              >
                {selectedRuleId && !rules.some((r) => r.id === selectedRuleId) && (
                  <option value={selectedRuleId} disabled>
                    -- Rule Not Found ({selectedRuleId}) --
                  </option>
                )}
                {rules.map((r) => (
                  <option key={r.id} value={r.id}>
                    {r.name} ({r.severity})
                  </option>
                ))}
