"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import {
  BookOpen,
  Search,
  Filter,
  CheckCircle2,
  AlertTriangle,
  ShieldAlert,
  ShieldCheck,
  RefreshCw,
  Sparkles,
  Database,
  Cpu,
  Layers,
  ArrowRight,
  Eye,
  Check,
  X,
  Info,
  SlidersHorizontal,
  ChevronRight,
} from "lucide-react";
import { api, LearningRecord, SimilarCaseMatch, RuleItem } from "@/lib/api";

export default function AgentMemoryPage() {
  const [records, setRecords] = useState<LearningRecord[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [ruleFilter, setRuleFilter] = useState("");
  const [verdictFilter, setVerdictFilter] = useState("");
  const [statusFilter, setStatusFilter] = useState("");
  const [search, setSearch] = useState("");

  const [rules, setRules] = useState<RuleItem[]>([]);
  const [seedingLoading, setSeedingLoading] = useState(false);
  const [feedback, setFeedback] = useState<{ type: "success" | "error"; text: string } | null>(null);

  // Similar cases search tool
  const [simQueryIncidentId, setSimQueryIncidentId] = useState("");
  const [simQueryCommand, setSimQueryCommand] = useState("");
  const [simQueryIp, setSimQueryIp] = useState("");
  const [simMatches, setSimMatches] = useState<SimilarCaseMatch[]>([]);
  const [simSearching, setSimSearching] = useState(false);
  const [simSearched, setSimSearched] = useState(false);

  // Detail Modal
  const [activeRecord, setActiveRecord] = useState<LearningRecord | null>(null);

  const fetchRecords = async () => {
    setLoading(true);
    try {
      const res = await api.getLearningRecords({
        page,
        page_size: 20,
        rule_id: ruleFilter || undefined,
        verdict: verdictFilter || undefined,
        verification_status: statusFilter || undefined,
        search: search || undefined,
      });
      setRecords(res.items);
      setTotal(res.total);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRecords();
  }, [page, ruleFilter, verdictFilter, statusFilter]);

  useEffect(() => {
    api.getRules({ page_size: 50 }).then((res) => setRules(res.items)).catch(() => { });
  }, []);

  const handleSeedHistorical = async () => {
    setSeedingLoading(true);
    setFeedback(null);
    try {
      const res = await api.seedHistoricalLearning();
      await fetchRecords();
      setFeedback({
        type: "success",
        text: `Successfully initialized ${res.seeded_count} verified learning records from historical SIEM ground truth!`,
      });
    } catch (err: any) {
      setFeedback({ type: "error", text: err.message });
    } finally {
      setSeedingLoading(false);
    }
  };

  const handleRunSimilarSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    setSimSearching(true);
    setSimSearched(true);
    try {
      const matches = await api.findSimilarCases({
        incident_id: simQueryIncidentId.trim() || undefined,
        command_substring: simQueryCommand.trim() || undefined,
        source_ip: simQueryIp.trim() || undefined,
        top_k: 5,
      });
      setSimMatches(matches);
    } catch (err: any) {
      console.error(err);
    } finally {
      setSimSearching(false);
    }
  };

  const getVerdictBadge = (verdict: string) => {
    switch (verdict) {
      case "TRUE_POSITIVE":
        return <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-semibold bg-rose-950/60 text-rose-400 border border-rose-800/60"><ShieldAlert className="w-3 h-3" /> True Positive</span>;
      case "FALSE_POSITIVE":
        return <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-semibold bg-emerald-950/60 text-emerald-400 border border-emerald-800/60"><ShieldCheck className="w-3 h-3" /> False Positive</span>;
      case "REQUIRES_ATTENTION":
        return <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-semibold bg-amber-950/60 text-amber-400 border border-amber-800/60"><AlertTriangle className="w-3 h-3" /> Requires Attention</span>;
      default:
        return <span className="text-xs text-zinc-400">{verdict}</span>;
    }
  };

  return (
    <div className="space-y-3">
      {/* Page Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2 border-b border-slate-800 pb-2.5">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-base sm:text-lg font-bold tracking-tight text-slate-100">Agent Memory</h1>
            <span className="px-1.5 py-0.2 rounded-full text-[10px] font-semibold bg-sky-950/80 text-sky-400 border border-sky-800/60 font-mono">
              Agent Memory Engine
            </span>
          </div>
          <p className="text-[11px] text-slate-400 mt-0.5">
            Precedent management and analyst feedback knowledge base for few-shot reasoning and memory retrieval.
          </p>
        </div>

        <div className="flex items-center gap-1.5">
          <button
            onClick={handleSeedHistorical}
            disabled={seedingLoading}
            className="flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-slate-800 hover:bg-slate-700 text-xs font-medium text-slate-200 border border-slate-700 transition-colors"
          >
            {seedingLoading ? <RefreshCw className="w-3 h-3 animate-spin" /> : <Database className="w-3 h-3 text-sky-400" />}
            Seed Precedent Memory
          </button>
          <button
            onClick={fetchRecords}
            className="p-1 rounded-md bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-slate-200 border border-slate-700"
            title="Refresh"
          >
            <RefreshCw className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>

      {feedback && (
        <div className={`p-2.5 rounded-md text-xs border ${feedback.type === "success"
            ? "bg-emerald-950/60 border-emerald-800 text-emerald-300"
            : "bg-rose-950/60 border-rose-800 text-rose-300"
          }`}>
          {feedback.text}
        </div>
      )}

      {/* KPI Counters */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
        <div className="p-2 sm:p-2.5 rounded-lg border border-slate-800 bg-slate-950 shadow-sm">
          <div className="text-[10px] font-medium text-slate-400">Total Verified Records</div>
          <div className="text-xl font-bold text-slate-100 font-mono mt-0.5">{total}</div>
        </div>
        <div className="p-2 sm:p-2.5 rounded-lg border border-rose-950/40 bg-rose-950/20 shadow-sm">
          <div className="text-[10px] font-medium text-rose-400">Verified True Positives</div>
          <div className="text-xl font-bold text-rose-300 font-mono mt-0.5">
            {records.filter((r) => r.verified_verdict === "TRUE_POSITIVE").length}
          </div>
        </div>
        <div className="p-2 sm:p-2.5 rounded-lg border border-emerald-950/40 bg-emerald-950/20 shadow-sm">
          <div className="text-[10px] font-medium text-emerald-400">Verified False Positives</div>
          <div className="text-xl font-bold text-emerald-300 font-mono mt-0.5">
            {records.filter((r) => r.verified_verdict === "FALSE_POSITIVE").length}
          </div>
        </div>
        <div className="p-2 sm:p-2.5 rounded-lg border border-indigo-950/40 bg-indigo-950/20 shadow-sm">
          <div className="text-[10px] font-medium text-indigo-400">SIEM Rules Covered</div>
          <div className="text-xl font-bold text-indigo-300 font-mono mt-0.5">{rules.length}</div>
        </div>
      </div>

      {/* Section: Deterministic Similar Cases Explorer Tool */}
      <div className="p-2.5 sm:p-3 rounded-lg border border-sky-900/40 bg-sky-950/10 space-y-2.5">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-1.5 border-b border-sky-900/40 pb-1.5">
          <div>
            <h2 className="text-xs sm:text-sm font-bold text-sky-300 flex items-center gap-1.5">
              <Cpu className="w-3.5 h-3.5 text-sky-400" />
              Deterministic Similar Case Matcher
            </h2>
            <p className="text-[10px] text-slate-400 mt-0.5">
              Query verified cases based on exact command artifacts, source IP, or event type overlap.
            </p>
          </div>
          <span className="text-[9px] font-mono text-sky-400/80 bg-sky-950/60 px-1.5 py-0.2 rounded border border-sky-800/40">
            Rule-Based Similarity
          </span>
        </div>

        <form onSubmit={handleRunSimilarSearch} className="grid grid-cols-1 sm:grid-cols-3 gap-2">
          <div>
            <label className="text-[10px] font-semibold text-slate-400 uppercase tracking-wider block mb-0.5">
              Search by Command / Keyword
            </label>
            <input
              type="text"
              placeholder="e.g. powershell, certutil, cmd.exe..."
              value={simQueryCommand}
              onChange={(e) => setSimQueryCommand(e.target.value)}
              className="w-full px-2.5 py-1 text-xs rounded border border-slate-800 bg-slate-950 text-slate-200 placeholder-slate-500 focus:outline-none"
            />
          </div>

          <div>
            <label className="text-[10px] font-semibold text-slate-400 uppercase tracking-wider block mb-0.5">
              Search by Source IP
            </label>
            <input
              type="text"
              placeholder="e.g. 10.0.4.15..."
              value={simQueryIp}
              onChange={(e) => setSimQueryIp(e.target.value)}
              className="w-full px-2.5 py-1 text-xs rounded border border-slate-800 bg-slate-950 text-slate-200 placeholder-slate-500 focus:outline-none"
            />
          </div>

          <div className="flex items-end">
            <button
              type="submit"
              disabled={simSearching}
              className="w-full py-1 px-3 bg-sky-800 hover:bg-sky-700 text-white rounded text-xs font-bold transition-colors flex items-center justify-center gap-1.5"
            >
              {simSearching ? (
                <>
                  <RefreshCw className="w-3 h-3 animate-spin" /> Searching...
                </>
              ) : (
                <>
                  <Search className="w-3 h-3" /> Find Matches
                </>
              )}
            </button>
          </div>
        </form>

        {/* Similar Cases Results */}
        {simSearched && (
          <div className="space-y-1.5 pt-1.5 border-t border-sky-900/30">
            <div className="text-xs font-semibold text-slate-300">
              Matching Verified Cases ({simMatches.length} found):
            </div>
            {simMatches.length === 0 ? (
              <div className="p-3 rounded border border-dashed border-slate-800 text-center text-xs text-slate-500">
                No verified cases matched the given telemetry criteria.
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                {simMatches.map((match) => (
                  <div
                    key={match.learning_record_id}
                    className="p-2.5 rounded-lg border border-slate-800 bg-slate-950/70 space-y-1.5 text-xs"
                  >
                    <div className="flex items-center justify-between">
                      <span className="font-mono font-bold text-slate-200">
                        {match.incident_vendor_id}
                      </span>
                      <div className="flex items-center gap-1.5">
                        <span className="px-1.5 py-0.2 rounded text-[9px] font-bold bg-sky-950 text-sky-400 border border-sky-800 font-mono">
                          {Math.round(match.match_score * 100)}% Match
                        </span>
                        {getVerdictBadge(match.verified_verdict)}
                      </div>
                    </div>

                    <div className="text-slate-300 text-[11px] line-clamp-1 font-medium">{match.title}</div>

                    <div className="text-slate-400 text-[11px] bg-slate-900 p-2 rounded border border-slate-800 whitespace-pre-wrap">
                      {match.analyst_explanation}
                    </div>

                    <div className="pt-0.5">
                      <span className="text-[9px] uppercase font-semibold text-slate-500 block mb-0.5">
                        Matched Telemetry Features:
                      </span>
                      <div className="flex flex-wrap gap-1">
                        {match.matched_features.map((feat, idx) => (
                          <span
                            key={idx}
                            className="px-1.5 py-0.2 rounded text-[9px] bg-slate-800 text-slate-300 font-mono"
                          >
                            {feat}
                          </span>
                        ))}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      {/* Main Verified Knowledge Base Repository Table */}
      <div className="space-y-2">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2">
          <h2 className="text-xs sm:text-sm font-bold text-slate-100 flex items-center gap-1.5">
            <BookOpen className="w-3.5 h-3.5 text-emerald-400" />
            Verified Case Knowledge Catalog
          </h2>

          {/* Filters */}
          <div className="flex flex-wrap gap-1.5 items-center text-xs">
            <select
              value={ruleFilter}
              onChange={(e) => {
                setRuleFilter(e.target.value);
                setPage(1);
              }}
              className="px-2 py-1 rounded-md border border-slate-800 bg-slate-950 text-slate-300 focus:outline-none"
            >
              <option value="">All SIEM Rules</option>
              {rules.map((r) => (
                <option key={r.id} value={r.id}>
                  {r.name}
                </option>
              ))}
            </select>

            <select
              value={verdictFilter}
              onChange={(e) => {
                setVerdictFilter(e.target.value);
                setPage(1);
              }}
              className="px-2 py-1 rounded-md border border-slate-800 bg-slate-950 text-slate-300 focus:outline-none"
            >
              <option value="">All Verified Verdicts</option>
              <option value="TRUE_POSITIVE">True Positive</option>
              <option value="FALSE_POSITIVE">False Positive</option>
              <option value="REQUIRES_ATTENTION">Requires Attention</option>
            </select>

            <select
              value={statusFilter}
              onChange={(e) => {
                setStatusFilter(e.target.value);
                setPage(1);
              }}
              className="px-2 py-1 rounded-md border border-slate-800 bg-slate-950 text-slate-300 focus:outline-none"
            >
              <option value="">All Statuses</option>
              <option value="VERIFIED">Verified Ground Truth</option>
              <option value="DISPUTED">Disputed</option>
              <option value="UNDER_REVIEW">Under Review</option>
            </select>
          </div>
        </div>

        <div className="border border-slate-800 rounded-lg overflow-hidden bg-slate-950 shadow-sm">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs text-slate-300">
              <thead className="bg-slate-900/60 text-slate-400 uppercase tracking-wider text-[10px] font-mono border-b border-slate-800">
                <tr>
                  <th className="py-2 px-2.5 font-semibold">Incident / Title</th>
                  <th className="py-2 px-2.5 font-semibold">SIEM Rule</th>
                  <th className="py-2 px-2.5 font-semibold">Verified Verdict</th>
                  <th className="py-2 px-2.5 font-semibold">Analyst Explanation &amp; Indicators</th>
                  <th className="py-2 px-2.5 font-semibold">Verification Status</th>
                  <th className="py-2 px-2.5 font-semibold">Recorded Date</th>
                  <th className="py-2 px-2.5 text-right font-semibold">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/60">
                {loading ? (
                  <tr>
                    <td colSpan={7} className="py-8 text-center text-slate-500 font-sans">
                      <RefreshCw className="w-4 h-4 animate-spin mx-auto mb-1.5 text-slate-600" />
                      Loading verified knowledge base records...
                    </td>
                  </tr>
                ) : records.length === 0 ? (
                  <tr>
                    <td colSpan={7} className="py-8 text-center text-slate-500 font-sans">
                      No learning records found. Click &quot;Seed Historical Cases&quot; to populate verified records.
                    </td>
                  </tr>
                ) : (
                  records.map((rec) => (
                    <tr key={rec.id} className="hover:bg-slate-900/40 transition-colors">
                      <td className="py-1.5 px-2.5">
                        <div className="font-semibold text-slate-100 font-mono text-xs">
                          {rec.incident_vendor_id}
                        </div>
                        <div className="text-slate-400 text-[10px] line-clamp-1 max-w-xs">
                          {rec.incident_title}
                        </div>
                      </td>
                      <td className="py-1.5 px-2.5 text-slate-300 font-medium text-xs">
                        {rec.rule_name}
                      </td>
                      <td className="py-1.5 px-2.5">
                        {getVerdictBadge(rec.verified_verdict)}
                      </td>
                      <td className="py-1.5 px-2.5">
                        <div className="text-slate-300 text-[11px] line-clamp-2 max-w-md">
                          {rec.analyst_explanation}
                        </div>
                        {rec.tp_indicators.length > 0 && (
                          <div className="text-[10px] text-rose-400 mt-0.5 line-clamp-1 font-mono">
                            TP IOC: {rec.tp_indicators[0]}
                          </div>
                        )}
                        {rec.fp_indicators.length > 0 && (
                          <div className="text-[10px] text-emerald-400 mt-0.5 line-clamp-1 font-mono">
                            FP Tool: {rec.fp_indicators[0]}
                          </div>
                        )}
                      </td>
                      <td className="py-1.5 px-2.5">
                        <span className="px-1.5 py-0.2 rounded text-[10px] font-semibold bg-emerald-950/80 text-emerald-400 border border-emerald-800/60">
                          {rec.verification_status}
                        </span>
                      </td>
                      <td className="py-1.5 px-2.5 text-slate-400 text-[10px]">
                        {new Date(rec.feedback_timestamp).toLocaleDateString()}
                      </td>
                      <td className="py-1.5 px-2.5 text-right">
                        <button
                          onClick={() => setActiveRecord(rec)}
                          className="px-2 py-0.5 bg-slate-900 hover:bg-slate-800 text-slate-200 rounded text-xs font-medium border border-slate-700 transition-colors"
                        >
                          View Details
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Detail Modal */}
      {activeRecord && (
        <div className="fixed inset-0 z-50 bg-black/75 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-slate-950 border border-slate-800 rounded-lg max-w-xl w-full p-4 space-y-3 shadow-2xl">
            <div className="flex items-start justify-between border-b border-slate-800 pb-2">
              <div>
                <span className="text-[10px] font-mono px-1.5 py-0.2 rounded bg-slate-900 border border-slate-800 text-slate-400">
                  {activeRecord.incident_vendor_id}
                </span>
                <h3 className="text-sm font-bold text-slate-100 mt-1">{activeRecord.incident_title}</h3>
                <p className="text-[11px] text-slate-400">Rule: {activeRecord.rule_name}</p>
              </div>
              <button
                onClick={() => setActiveRecord(null)}
                className="p-1 rounded text-slate-400 hover:text-slate-200"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <div className="space-y-2 text-xs">
              <div className="flex items-center gap-2">
                <span className="text-slate-400 font-semibold text-[11px]">Verified Verdict:</span>
                {getVerdictBadge(activeRecord.verified_verdict)}
                <span className="px-1.5 py-0.2 rounded text-[10px] font-semibold bg-emerald-950 text-emerald-400 border border-emerald-800">
                  {activeRecord.verification_status}
                </span>
              </div>

              <div>
                <span className="text-slate-400 font-semibold block mb-0.5 text-[11px]">Analyst Technical Explanation:</span>
                <div className="p-2 rounded bg-slate-900 border border-slate-800 text-slate-200 whitespace-pre-wrap text-[11px]">
                  {activeRecord.analyst_explanation}
                </div>
              </div>

              {activeRecord.tp_indicators.length > 0 && (
                <div>
                  <span className="text-rose-400 font-semibold block mb-0.5 text-[11px]">Confirmed True Positive Indicators:</span>
                  <ul className="list-disc list-inside space-y-0.5 text-slate-300 text-[11px]">
                    {activeRecord.tp_indicators.map((tp, i) => (
                      <li key={i}>{tp}</li>
                    ))}
                  </ul>
                </div>
              )}

              {activeRecord.fp_indicators.length > 0 && (
                <div>
                  <span className="text-emerald-400 font-semibold block mb-0.5 text-[11px]">Confirmed Benign / FP Indicators:</span>
                  <ul className="list-disc list-inside space-y-0.5 text-slate-300 text-[11px]">
                    {activeRecord.fp_indicators.map((fp, i) => (
                      <li key={i}>{fp}</li>
                    ))}
                  </ul>
                </div>
              )}

              {activeRecord.evidence_references.length > 0 && (
                <div>
                  <span className="text-slate-400 font-semibold block mb-0.5 text-[11px]">Evidence Artifact References:</span>
                  <div className="flex flex-wrap gap-1">
                    {activeRecord.evidence_references.map((ref, i) => (
                      <span key={i} className="px-1.5 py-0.2 rounded bg-slate-900 border border-slate-800 text-slate-300 font-mono text-[10px]">
                        {ref}
                      </span>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <div className="flex justify-end pt-2 border-t border-slate-800">
              <button
                type="button"
                onClick={() => setActiveRecord(null)}
                className="px-3 py-1 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded text-xs font-semibold"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import {
  Play,
  RotateCcw,
  CheckCircle,
  AlertTriangle,
  XCircle,
  Clock,
  Layers,
  ShieldAlert,
  Server,
  FileText,
  BarChart2,
  Eye,
  RefreshCw,
  Info,
  ChevronRight,
  ExternalLink,
} from "lucide-react";
import Link from "next/link";
import {
  api,
  DryRunConfig,
  DryRunJob,
  DryRunResult,
  RuleItem,
} from "@/lib/api";
import { MetricSummaryCard, NextActionCard, AdvancedDetailsPanel } from "@/components/compact/CompactDesignSystem";

export default function AgentSimulationLabPage() {
  const [configs, setConfigs] = useState<DryRunConfig[]>([]);
  const [jobs, setJobs] = useState<DryRunJob[]>([]);
  const [rules, setRules] = useState<RuleItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [launching, setLaunching] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);
  const [llmStatus, setLlmStatus] = useState<{
    is_healthy: boolean;
    model?: string;
    latency_ms?: number;
    endpoint_provenance?: string;
  } | null>(null);

  // Form State
  const [name, setName] = useState("Dry-Run Simulation Replay");
  const [description, setDescription] = useState("Automated incident replay with deterministic heuristic simulator");
  const [selectedRuleId, setSelectedRuleId] = useState<string>("");
  const [providerType, setProviderType] = useState("SIMULATED");
  const [splitStrategy, setSplitStrategy] = useState("ALL");
  const [sampleLimit, setSampleLimit] = useState<number | "">("");

  // Inspect Modal State
  const [selectedJob, setSelectedJob] = useState<DryRunJob | null>(null);
  const [jobResults, setJobResults] = useState<DryRunResult[]>([]);
  const [loadingResults, setLoadingResults] = useState(false);
  const [selectedResult, setSelectedResult] = useState<DryRunResult | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  async function loadData() {
    setLoading(true);
    setError(null);
    try {
      const [fetchedRules, fetchedJobs, fetchedConfigs, fetchedLlmStatus] = await Promise.all([
        api.getRules().then((res) => res.items).catch(() => []),
        api.getDryRunJobs(30).catch(() => []),
        api.getDryRunConfigs().catch(() => []),
        api.getLlmStatus().catch(() => null),
      ]);
      setRules(fetchedRules);
      setJobs(fetchedJobs);
      setConfigs(fetchedConfigs);
      setLlmStatus(fetchedLlmStatus);
      if (fetchedLlmStatus?.is_healthy) {
        setProviderType("OPENAI_COMPATIBLE");
      }
    } catch (err: any) {
      setError(err.message || "Failed to load dry-run data");
    } finally {
      setLoading(false);
    }
  }

  async function handleLaunch() {
    if (!name.trim()) {
      setError("Please provide a configuration name");
      return;
    }

    setLaunching(true);
    setError(null);
    setSuccessMsg(null);

    try {
      // 1. Create Config
      const newConfig = await api.createDryRunConfig({
        name: name.trim(),
        description: description.trim(),
        rule_id: selectedRuleId || undefined,
        provider_type: providerType,
        split_strategy: splitStrategy,
      });

      // 2. Trigger Job
      const limit = typeof sampleLimit === "number" && sampleLimit > 0 ? sampleLimit : undefined;
      const job = await api.triggerDryRunJob(newConfig.id, limit);

      setSuccessMsg(`Dry-run replay job launched and completed: ${job.processed_items} incidents processed.`);
      await loadData();
      inspectJob(job);
    } catch (err: any) {
      setError(err.message || "Execution failed");
    } finally {
      setLaunching(false);
    }
  }

  async function inspectJob(job: DryRunJob) {
    setSelectedJob(job);
    setSelectedResult(null);
    setLoadingResults(true);
    try {
      const results = await api.getDryRunJobResults(job.id, 100);
      setJobResults(results);
      if (results.length > 0) {
        setSelectedResult(results[0]);
      }
    } catch (err: any) {
      setError("Failed to load job results");
    } finally {
      setLoadingResults(false);
    }
  }

  return (
    <div className="space-y-3.5">
      {/* Top Banner */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pb-2.5 border-b border-border">
        <div>
          <div className="flex items-center gap-2.5">
            <h1 className="text-lg sm:text-xl font-bold text-foreground">Agent Simulation Lab</h1>
            <span className="px-2 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
              Validation Engine
            </span>
          </div>
          <p className="text-xs text-muted-foreground mt-0.5">
            Controlled testing, heuristic simulation, and replay benchmarking without production impact.
          </p>
        </div>

        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-secondary/40 border border-border text-xs text-muted-foreground">
            <Server className={`w-3 h-3 ${llmStatus?.is_healthy ? "text-emerald-400" : "text-amber-400"}`} />
            <span>
              Verdictum Cortex LLM:{" "}
              {llmStatus?.endpoint_provenance === "HTTP_MOCK" ? (
                <strong className="text-cyan-300">HTTP_MOCK ({llmStatus.model || "Test Endpoint"})</strong>
              ) : llmStatus?.is_healthy ? (
                <strong className="text-emerald-400">Connected ({llmStatus.model || "Qwen 2.5 7B"})</strong>
              ) : (
                <strong className="text-foreground">Disconnected (Phase 3 Guard)</strong>
              )}
            </span>
          </div>
          <button
            onClick={loadData}
            disabled={loading}
            className="flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-secondary hover:bg-secondary/80 text-foreground text-xs border border-border"
          >
            <RefreshCw className={`w-3 h-3 ${loading ? "animate-spin" : ""}`} />
            Refresh
          </button>
        </div>
      </div>

      {/* Compact Simulation Metrics Row */}
      {(() => {
        const totalItemsEvaluated = jobs.reduce((acc, j) => acc + (j.processed_items || 0), 0);
        const verifiedCases = jobResults.filter((r) => r.ground_truth_verdict && r.ground_truth_verdict !== "Unlabeled");
        const agreedCases = verifiedCases.filter((r) => r.is_agreement).length;
        const accuracyText = verifiedCases.length > 0
          ? `${Math.round((agreedCases / verifiedCases.length) * 100)}%`
          : "N/A (Pending Ground Truth)";

        return (
          <>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5">
              <MetricSummaryCard
                label="Replay Engine"
                value={llmStatus?.is_healthy ? "Local LLM" : "Heuristic Sim"}
                subtext={llmStatus?.is_healthy ? `${llmStatus.model || "Qwen 2.5"}` : "Deterministic Fallback"}
                status={llmStatus?.is_healthy ? "success" : "normal"}
              />
              <MetricSummaryCard
                label="Replay Batches"
                value={jobs.length}
                subtext={`${configs.length} active configurations`}
                status="normal"
              />
              <MetricSummaryCard
                label="Scanned Incidents"
                value={totalItemsEvaluated}
                subtext="Total items processed across jobs"
                status="normal"
              />
              <MetricSummaryCard
                label="Empirical Accuracy"
                value={accuracyText}
                subtext={verifiedCases.length > 0 ? `${verifiedCases.length} verified ground truth cases` : "Requires verified analyst cases"}
                status={verifiedCases.length > 0 ? "success" : "neutral"}
              />
            </div>

            <NextActionCard
              title={selectedJob ? `Inspecting Replay Batch: ${selectedJob.config_name || selectedJob.id}` : "Configure and Launch Replay Batch"}
              description={selectedJob ? "Examine predicted verdicts and reasoning below, or open statistical evaluation reports in Verdict Intelligence." : "Select a detection rule and partition strategy to benchmark agent policies against historical incidents."}
              actionLabel={selectedJob ? "View Evaluation Report" : "Launch Replay"}
              onAction={selectedJob ? () => { window.location.href = `/verdict-intelligence?jobId=${selectedJob.id}`; } : handleLaunch}
              status="primary"
            />
          </>
        );
      })()}

      {/* Prominent Simulation Guard Warning */}
      <div className="p-2.5 sm:p-3 rounded-lg bg-amber-500/10 border border-amber-500/30 flex items-start gap-2.5">
        <AlertTriangle className="w-4 h-4 text-amber-400 shrink-0 mt-0.5" />
        <div className="text-xs space-y-0.5">
          <div className="font-semibold text-amber-200">
            Dry-Run Simulation Guardrail Active
          </div>
          <p className="text-amber-300/90 leading-relaxed text-[11px]">
            All verdicts are generated by deterministic heuristic simulation algorithms and explicitly tagged{" "}
            <code className="px-1 py-0.5 rounded bg-amber-950/80 font-mono text-[10px]">is_simulated = True</code>.
            All historical closure fields (<code className="px-1 py-0.5 rounded bg-amber-950/80 font-mono text-[10px]">resolution</code>,{" "}
            <code className="px-1 py-0.5 rounded bg-amber-950/80 font-mono text-[10px]">comments</code>,{" "}
            <code className="px-1 py-0.5 rounded bg-amber-950/80 font-mono text-[10px]">clearedReason</code>) are strictly isolated
            from model input payloads to prevent data leakage.
          </p>
        </div>
      </div>

      {error && (
        <div className="p-2.5 rounded-md bg-red-500/10 border border-red-500/30 text-red-400 text-xs flex items-center justify-between">
          <span>{error}</span>
          <button onClick={() => setError(null)} className="text-xs hover:underline">Dismiss</button>
        </div>
      )}

      {successMsg && (
        <div className="p-2.5 rounded-md bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 text-xs flex items-center justify-between">
          <span>{successMsg}</span>
          <button onClick={() => setSuccessMsg(null)} className="text-xs hover:underline">Dismiss</button>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-3.5">
        {/* Left Column: Replay Launcher Configuration */}
        <div className="lg:col-span-5 space-y-3.5">
          <div className="p-3 sm:p-3.5 rounded-lg border border-border bg-card shadow-sm space-y-3">
            <div className="flex items-center gap-2 pb-2 border-b border-border">
              <Play className="w-3.5 h-3.5 text-primary" />
              <h2 className="font-semibold text-foreground text-xs uppercase tracking-wide">
                Configure Dry-Run Replay
              </h2>
            </div>

            <div className="space-y-2.5 text-xs">
              <div>
                <label className="block text-[11px] font-medium text-muted-foreground mb-1">
                  Replay Job Name *
                </label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full px-2.5 py-1.5 rounded-md bg-background border border-border text-foreground text-xs focus:outline-none focus:ring-1 focus:ring-primary"
                  placeholder="e.g. CrowdStrike Suspicious Activity Replay"
                />
              </div>

              <div>
                <label className="block text-[11px] font-medium text-muted-foreground mb-1">
                  Target SIEM Detection Rule
                </label>
                <select
                  value={selectedRuleId}
                  onChange={(e) => setSelectedRuleId(e.target.value)}
                  className="w-full px-2.5 py-1.5 rounded-md bg-background border border-border text-foreground text-xs focus:outline-none focus:ring-1 focus:ring-primary"
                >
                  <option value="">All Detection Rules (Full Dataset)</option>
                  {rules.map((r) => (
                    <option key={r.id} value={r.id}>
                      {r.name} ({r.event_type})
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-[11px] font-medium text-muted-foreground mb-1">
                  Inference Model Provider
                </label>
                <select
                  value={providerType}
                  onChange={(e) => setProviderType(e.target.value)}
                  className="w-full px-2.5 py-1.5 rounded-md bg-background border border-border text-foreground text-xs focus:outline-none focus:ring-1 focus:ring-primary font-mono text-[11px]"
                >
                  <option value="OPENAI_COMPATIBLE">
                    OPENAI_COMPATIBLE ({llmStatus?.endpoint_provenance === "HTTP_MOCK" ? "HTTP_MOCK Test Endpoint" : llmStatus?.is_healthy ? "Verdictum Cortex Configured Endpoint — Online" : "Verdictum Cortex Node"})
                  </option>
                  <option value="SIMULATED">SIMULATED (Deterministic Heuristics - Fallback)</option>
                  <option value="DISABLED">DISABLED (Safe Provider Default)</option>
                </select>
              </div>

              <div>
                <label className="block text-[11px] font-medium text-muted-foreground mb-1">
                  Dataset Splitting Strategy
                </label>
                <select
                  value={splitStrategy}
                  onChange={(e) => setSplitStrategy(e.target.value)}
                  className="w-full px-2.5 py-1.5 rounded-md bg-background border border-border text-foreground text-xs focus:outline-none focus:ring-1 focus:ring-primary"
                >
                  <option value="ALL">ALL (100% Ingested Rule Incidents)</option>
                  <option value="CHRONOLOGICAL_70_30">
                    CHRONOLOGICAL_70_30 (Holdout 30% Most Recent Incidents)
                  </option>
                  <option value="GROUP_AWARE_HOST">
                    GROUP_AWARE_HOST (Group by Host Device to Prevent Leakage)
                  </option>
                </select>
                <p className="text-[10px] text-muted-foreground mt-0.5">
                  Prevents training/evaluation contamination across related security telemetry.
                </p>
              </div>

              <div>
                <label className="block text-[11px] font-medium text-muted-foreground mb-1">
                  Sample Limit (Optional)
                </label>
                <input
                  type="number"
                  min="1"
                  max="1000"
                  value={sampleLimit}
                  onChange={(e) => setSampleLimit(e.target.value ? parseInt(e.target.value) : "")}
                  placeholder="Leave empty to test full partition"
                  className="w-full px-2.5 py-1.5 rounded-md bg-background border border-border text-foreground text-xs focus:outline-none focus:ring-1 focus:ring-primary"
                />
              </div>

              <div className="pt-1">
                <button
                  onClick={handleLaunch}
                  disabled={launching}
                  className="w-full py-2 px-3 rounded-md bg-primary hover:bg-primary/90 text-primary-foreground font-semibold text-xs flex items-center justify-center gap-2 transition-colors disabled:opacity-50"
                >
                  {launching ? (
                    <>
                      <RefreshCw className="w-3.5 h-3.5 animate-spin" />
                      <span>Executing Batch Replay...</span>
                    </>
                  ) : (
                    <>
                      <Play className="w-3.5 h-3.5" />
                      <span>Launch Dry-Run Replay</span>
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>

          {/* Architecture Card */}
          <div className="p-3 rounded-lg border border-border bg-card/60 text-[11px] space-y-1.5 text-muted-foreground">
            <div className="flex items-center gap-1.5 font-semibold text-foreground text-xs">
              <Info className="w-3 h-3 text-primary" />
              <span>Dry-Run Pipeline Flow</span>
            </div>
            <p>
              1. <strong>Strict Allowlist:</strong> Normalized incident without ground truth is extracted.
            </p>
            <p>
              2. <strong>Provider Call:</strong> Dispatched to provider abstraction with timeout and schema guard.
            </p>
            <p>
              3. <strong>Defensive Fallback:</strong> Any schema breach defaults to <code>REQUIRES_ATTENTION</code>.
            </p>
            <p>
              4. <strong>Automated Metric Rollup:</strong> Updates rule readiness metrics for evaluation reports.
            </p>
          </div>
        </div>

        {/* Right Column: Recent Jobs Table */}
        <div className="lg:col-span-7 space-y-3">
          <div className="p-3 sm:p-3.5 rounded-lg border border-border bg-card shadow-sm space-y-3">
            <div className="flex items-center justify-between pb-2 border-b border-border">
              <div className="flex items-center gap-2">
                <Clock className="w-3.5 h-3.5 text-primary" />
                <h2 className="font-semibold text-foreground text-xs uppercase tracking-wide">
                  Replay Job History ({jobs.length})
                </h2>
              </div>
              <span className="text-[11px] text-muted-foreground">Select a job to inspect results</span>
            </div>

            {jobs.length === 0 ? (
              <div className="p-6 text-center text-muted-foreground text-xs">
                No dry-run replay jobs executed yet. Launch a replay configuration on the left.
              </div>
            ) : (
              <div className="divide-y divide-border overflow-hidden rounded-md border border-border">
                {jobs.map((job) => {
                  const isSelected = selectedJob?.id === job.id;
                  return (
                    <div
                      key={job.id}
                      onClick={() => inspectJob(job)}
                      className={`p-2.5 transition-colors cursor-pointer flex items-center justify-between hover:bg-secondary/40 ${
                        isSelected ? "bg-primary/10 border-l-4 border-l-primary" : "bg-card"
                      }`}
                    >
                      <div className="space-y-0.5">
                        <div className="flex items-center gap-2">
                          <span className="font-semibold text-xs text-foreground">
                            {job.config_name || "Dry-Run Job"}
                          </span>
                          <span
                            className={`px-1.5 py-0.2 rounded text-[10px] font-bold ${
                              job.status === "COMPLETED"
                                ? "bg-emerald-500/10 text-emerald-400"
                                : job.status === "FAILED"
                                ? "bg-red-500/10 text-red-400"
                                : "bg-amber-500/10 text-amber-400"
                            }`}
                          >
                            {job.status}
                          </span>
                          {job.is_simulated && (
                            <span className="px-1.5 py-0.2 rounded text-[9px] bg-secondary text-amber-300 border border-amber-500/30">
                              SIMULATED
                            </span>
                          )}
                        </div>
                        <div className="text-[11px] text-muted-foreground flex items-center gap-2.5">
                          <span>Processed: {job.processed_items} / {job.total_items}</span>
                          <span>Errors: {job.error_count}</span>
                          <span>Started: {new Date(job.started_at).toLocaleTimeString()}</span>
                        </div>
                      </div>

                      <div className="flex items-center gap-1.5">
                        <Link
                          href={`/verdict-intelligence?jobId=${job.id}`}
                          onClick={(e) => e.stopPropagation()}
                          className="px-2 py-0.5 rounded bg-secondary hover:bg-secondary/80 text-foreground text-[11px] font-medium border border-border flex items-center gap-1"
                        >
                          <BarChart2 className="w-3 h-3 text-primary" />
                          <span>Evaluation</span>
                        </Link>
                        <ChevronRight className="w-3.5 h-3.5 text-muted-foreground" />
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Results Inspector Modal / Section */}
      {selectedJob && (
        <div className="p-3 sm:p-3.5 rounded-lg border border-border bg-card shadow-sm space-y-3">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2.5 pb-2.5 border-b border-border">
            <div>
              <h3 className="text-sm sm:text-base font-bold text-foreground flex items-center gap-2">
                <FileText className="w-4 h-4 text-primary" />
                Replay Results: {selectedJob.config_name || selectedJob.id}
              </h3>
              <p className="text-[11px] text-muted-foreground">
                Inspecting individual incident verdicts, model reasoning, and ground-truth comparisons.
              </p>
            </div>

            <div className="flex items-center gap-1.5">
              <Link
                href={`/verdict-intelligence?jobId=${selectedJob.id}`}
                className="px-2.5 py-1 rounded-md bg-primary hover:bg-primary/90 text-primary-foreground text-xs font-semibold flex items-center gap-1.5"
              >
                <BarChart2 className="w-3 h-3" />
                View Full Report
              </Link>
              <a
                href={`/api/evaluations/job/${selectedJob.id}/export/csv`}
                download
                className="px-2.5 py-1 rounded-md bg-secondary hover:bg-secondary/80 text-foreground text-xs font-medium border border-border flex items-center gap-1.5"
              >
                CSV
              </a>
              <a
                href={`/api/evaluations/job/${selectedJob.id}/export/json`}
                download
                className="px-2.5 py-1 rounded-md bg-secondary hover:bg-secondary/80 text-foreground text-xs font-medium border border-border flex items-center gap-1.5"
              >
                JSON
              </a>
            </div>
          </div>

          {loadingResults ? (
            <div className="p-6 text-center text-xs text-muted-foreground flex items-center justify-center gap-2">
              <RefreshCw className="w-3.5 h-3.5 animate-spin text-primary" />
              Loading replay results...
            </div>
          ) : jobResults.length === 0 ? (
            <div className="p-6 text-center text-xs text-muted-foreground">
              No results recorded for this job.
            </div>
          ) : (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-3">
              {/* Results List */}
              <div className="lg:col-span-5 border border-border rounded-md overflow-hidden max-h-[420px] overflow-y-auto divide-y divide-border bg-background">
                {jobResults.map((r) => {
                  const isCur = selectedResult?.id === r.id;
                  return (
                    <div
                      key={r.id}
                      onClick={() => setSelectedResult(r)}
                      className={`p-2 text-xs cursor-pointer transition-colors ${
                        isCur ? "bg-primary/10 border-l-4 border-l-primary" : "hover:bg-secondary/40"
                      }`}
                    >
                      <div className="flex items-center justify-between mb-0.5">
                        <span className="font-mono font-bold text-foreground text-[11px]">
                          {r.incident_vendor_id || r.incident_id.slice(0, 10)}
                        </span>
                        <span
                          className={`px-1.5 py-0.2 rounded text-[9px] font-bold ${
                            r.predicted_verdict === "TRUE_POSITIVE"
                              ? "bg-red-500/10 text-red-400"
                              : r.predicted_verdict === "FALSE_POSITIVE"
                              ? "bg-emerald-500/10 text-emerald-400"
                              : "bg-amber-500/10 text-amber-400"
                          }`}
                        >
                          {r.predicted_verdict}
                        </span>
                      </div>
                      <div className="text-muted-foreground text-[11px] truncate">{r.incident_title || r.rule_name}</div>
                      <div className="mt-0.5 flex items-center justify-between text-[10px] text-muted-foreground">
                        <span>Confidence: {r.confidence}%</span>
                        <span className={`font-semibold ${r.is_agreement ? "text-emerald-400" : "text-amber-400"}`}>
                          {r.is_agreement ? "✓ Agreed" : "≠ Disagreed/Abstained"}
                        </span>
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Result Detail Inspector */}
              <div className="lg:col-span-7 p-3 border border-border rounded-md bg-background text-xs space-y-3">
                {selectedResult ? (
                  <>
                    <div className="flex items-start justify-between border-b border-border pb-2">
                      <div>
                        <div className="flex items-center gap-2">
                          <span className="font-mono font-bold text-sm text-foreground">
                            {selectedResult.incident_vendor_id || selectedResult.incident_id}
                          </span>
                          <span
                            className={`px-2 py-0.5 rounded text-[10px] font-bold ${
                              selectedResult.predicted_verdict === "TRUE_POSITIVE"
                                ? "bg-red-500/10 text-red-400"
                                : selectedResult.predicted_verdict === "FALSE_POSITIVE"
                                ? "bg-emerald-500/10 text-emerald-400"
                                : "bg-amber-500/10 text-amber-400"
                            }`}
                          >
                            Model: {selectedResult.predicted_verdict}
                          </span>
                          {selectedResult.is_simulated && (
                            <span className="px-1.5 py-0.5 rounded text-[9px] bg-amber-500/10 text-amber-400 border border-amber-500/30">
                              SIMULATED
                            </span>
                          )}
                        </div>
                        <div className="text-[11px] text-muted-foreground mt-0.5">
                          Rule: {selectedResult.rule_name || "Unknown"} | Latency: {selectedResult.latency_ms}ms | Model: {selectedResult.model_identifier}
                        </div>
                      </div>

                      <div className="text-right text-[11px]">
                        <div className="text-muted-foreground">Historical Analyst Ground Truth:</div>
                        <div className="font-bold text-foreground mt-0.5">
                          {selectedResult.ground_truth_verdict || "Unlabeled"}
                        </div>
                      </div>
                    </div>

                    <div className="space-y-1">
                      <div className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">
                        Reasoning & Analytical Justification
                      </div>
                      <div className="p-2.5 rounded-md bg-secondary/30 border border-border font-mono text-[11px] text-foreground/90 leading-relaxed whitespace-pre-wrap">
                        {selectedResult.reasoning}
                      </div>
                    </div>

                    {selectedResult.supporting_evidence.length > 0 && (
                      <div className="space-y-1">
                        <div className="text-[10px] font-semibold text-emerald-400 uppercase tracking-wider">
                          Supporting Evidence Cited ({selectedResult.supporting_evidence.length})
                        </div>
                        <ul className="list-disc list-inside text-[11px] text-muted-foreground space-y-0.5">
                          {selectedResult.supporting_evidence.map((ev, i) => (
                            <li key={i}>{ev}</li>
                          ))}
                        </ul>
                      </div>
                    )}

                    {(selectedResult.missing_evidence.length > 0 || selectedResult.analyst_questions.length > 0) && (
                      <AdvancedDetailsPanel
                        title={`Investigation Diagnostics (${selectedResult.missing_evidence.length} gaps, ${selectedResult.analyst_questions.length} questions)`}
                        defaultOpen={false}
                      >
                        <div className="space-y-3 pt-1">
                          {selectedResult.missing_evidence.length > 0 && (
                            <div className="space-y-1">
                              <div className="text-[10px] font-semibold text-amber-400 uppercase tracking-wider">
                                Missing Telemetry / Information Gaps
                              </div>
                              <ul className="list-disc list-inside text-[11px] text-muted-foreground space-y-0.5">
                                {selectedResult.missing_evidence.map((gap, i) => (
                                  <li key={i}>{gap}</li>
                                ))}
                              </ul>
                            </div>
                          )}

                          {selectedResult.analyst_questions.length > 0 && (
                            <div className="space-y-1">
                              <div className="text-[10px] font-semibold text-primary uppercase tracking-wider">
                                Recommended Analyst Clarification Questions
                              </div>
                              <ul className="list-disc list-inside text-[11px] text-muted-foreground space-y-0.5">
                                {selectedResult.analyst_questions.map((q, i) => (
                                  <li key={i}>{q}</li>
                                ))}
                              </ul>
                            </div>
                          )}
                        </div>
                      </AdvancedDetailsPanel>
                    )}
                  </>
                ) : (
                  <div className="p-6 text-center text-muted-foreground text-xs">
                    Select a result from the list to view model reasoning.
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useEffect, useState, use } from "react";
import Link from "next/link";
import {
  AlertTriangle,
  ArrowLeft,
  Eye,
  EyeOff,
  Copy,
  Check,
  FileCode,
  Layers,
  Clock,
  ShieldCheck,
  ShieldAlert,
  Server,
  Network,
  Tag,
  Cpu,
  FileCheck2,
  Sparkles,
  Loader2,
  Bot,
  CheckCircle2,
  AlertCircle,
  Database,
  RefreshCw,
  Scale,
  FileSearch,
  Terminal,
} from "lucide-react";
import { api, IncidentDetail, IncidentAiVerdictResponse } from "@/lib/api";
import { copyToClipboard as copyTextToClipboard } from "@/lib/clipboard";
import { useApp } from "@/context/AppContext";
import { HistoricalTelemetryTimeline } from "@/components/telemetry/HistoricalTelemetryTimeline";
import { formatExecutionProvenanceBadge } from "@/lib/provenance";
import { IncidentVerdictMatrix } from "@/components/compact/IncidentVerdictMatrix";
import { NextActionCard, AdvancedDetailsPanel } from "@/components/compact/CompactDesignSystem";
import { ActualPromptInspectorModal } from "@/components/prompt-inspector/ActualPromptInspectorModal";

export default function AITriageWorkbenchDetailPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const resolvedParams = use(params);
  const incidentId = resolvedParams.id;
  const { blindReviewMode, setBlindReviewMode } = useApp();

  const [incident, setIncident] = useState<IncidentDetail | null>(null);
  const [modelPayload, setModelPayload] = useState<any | null>(null);
  const [activeTab, setActiveTab] = useState<
    "overview" | "events" | "rule" | "ground_truth" | "raw_json" | "model_payload" | "timeline" | "canonical_evidence"
  >("overview");
  const [isLoading, setIsLoading] = useState(true);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [analyzing, setAnalyzing] = useState(false);
  const [aiVerdict, setAiVerdict] = useState<IncidentAiVerdictResponse | null>(null);
  const [verdictError, setVerdictError] = useState<string | null>(null);
  const [syncingResolution, setSyncingResolution] = useState(false);
  const [syncSuccessMessage, setSyncSuccessMessage] = useState<string | null>(null);
  const [llmOnline, setLlmOnline] = useState<boolean | null>(null);
  const [promptInspectorOpen, setPromptInspectorOpen] = useState(false);

  useEffect(() => {
    let mounted = true;
    api.getLlmStatus()
      .then((res) => {
        if (mounted) setLlmOnline(Boolean(res?.is_healthy));
      })
      .catch(() => {
        if (mounted) setLlmOnline(false);
      });
    const onStatus = (e: Event) => {
      const detail = (e as CustomEvent).detail;
      if (mounted && detail && typeof detail.is_healthy === "boolean") {
        setLlmOnline(detail.is_healthy);
      }
    };
    window.addEventListener("llm-status-change", onStatus);
    return () => {
      mounted = false;
      window.removeEventListener("llm-status-change", onStatus);
    };
  }, []);

  const handleSyncResolution = async () => {
    if (!incident) return;
    setSyncingResolution(true);
    setSyncSuccessMessage(null);
    try {
      const res = await api.syncFortiSiemIncidentResolution(incident.incident_id);
      const refreshed = await api.getIncidentDetail(incidentId, blindReviewMode);
      setIncident(refreshed);
      setSyncSuccessMessage(
        res.resolution
          ? `Resolution pulled: ${res.resolution}${res.cleared_user ? ` by ${res.cleared_user}` : ""}`
          : "Synchronized with FortiSIEM (Incident remains Open)."
      );
      setTimeout(() => setSyncSuccessMessage(null), 5000);
    } catch (err: any) {
      setError(err.message || "Failed to sync resolution from FortiSIEM");
    } finally {
      setSyncingResolution(false);
    }
  };

  const handleRequestAiVerdict = async () => {
    setAnalyzing(true);
    setVerdictError(null);
    try {
      const verdict = await api.getIncidentAiVerdict(incidentId);
      setAiVerdict(verdict);
    } catch (err: any) {
      setVerdictError(err.message || "Failed to generate AI verdict from Local LLM.");
    } finally {
      setAnalyzing(false);
    }
  };

  useEffect(() => {
    async function loadData() {
      setIsLoading(true);
      setError(null);
      try {
        const data = await api.getIncidentDetail(incidentId, blindReviewMode);
        setIncident(data);
        setAiVerdict(blindReviewMode ? null : (data.ai_verdict || null));

        // Also fetch model payload to demonstrate allowlist compliance
        try {
          const mp = await api.getIncidentModelPayload(incidentId);
          setModelPayload(mp);
        } catch {
          // ignore if model payload fails
        }
      } catch (err: any) {
        setError(err.message || "Failed to load incident detail");
      } finally {
        setIsLoading(false);
      }
    }
    loadData();
  }, [incidentId, blindReviewMode]);

  const copyToClipboard = async (text: string) => {
    if (!text) return;
    const success = await copyTextToClipboard(text);
    if (success) {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const formatEpoch = (epoch?: number, fallbackIso?: string) => {
    if (!epoch) {
      if (fallbackIso) {
        try {
          return new Date(fallbackIso).toLocaleString([], {
            dateStyle: "short",
            timeStyle: "medium",
          });
        } catch {
          return "N/A";
        }
      }
      return "N/A";
    }
    const ms = epoch < 1e11 ? epoch * 1000 : epoch;
    return new Date(ms).toLocaleString([], {
      dateStyle: "short",
      timeStyle: "medium",
    });
  };

  if (isLoading) {
    return (
      <div className="flex h-96 items-center justify-center text-slate-400 text-xs">
        Loading incident {incidentId}...
      </div>
    );
  }

  if (error || !incident) {
    return (
      <div className="space-y-4">
        <Link href="/ai-triage-workbench" className="inline-flex items-center gap-1.5 text-xs text-cyan-400 hover:underline">
          <ArrowLeft className="h-3.5 w-3.5" /> Back to AI Triage Workbench
        </Link>
        <div className="rounded-xl border border-rose-800 bg-rose-950/40 p-6 text-rose-300 text-xs">
          {error || "Incident not found"}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-3.5">
      {/* Top Breadcrumb & Controls */}
      <div className="flex flex-col gap-2.5 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex items-center gap-2.5">
          <Link
            href="/ai-triage-workbench"
            className="flex h-7 w-7 items-center justify-center rounded-md border border-slate-800 bg-slate-900 text-slate-300 hover:bg-slate-800 hover:text-white"
          >
            <ArrowLeft className="h-3.5 w-3.5" />
          </Link>
          <div>
            <div className="flex items-center gap-1.5">
              <span className="font-mono text-[11px] text-slate-400">Incident</span>
              <span className="font-mono font-bold text-slate-100 text-xs sm:text-sm">{incident.incident_id}</span>
              <span className="rounded bg-slate-800 border border-slate-700 px-1.5 py-0.2 text-[9px] font-bold text-slate-200">
                {incident.severity}
              </span>
              <span
                className={`rounded px-1.5 py-0.2 text-[9px] font-mono border ${
                  incident.status_code === 2
                    ? "bg-slate-900 text-slate-400 border-slate-800"
                    : "bg-cyan-950 text-cyan-300 border-cyan-800"
                }`}
              >
                {incident.status_name}
              </span>
            </div>
            <h1 className="text-sm sm:text-base font-bold text-slate-100 mt-0.5">{incident.title}</h1>
          </div>
        </div>

        {/* Header Action Buttons */}
        <div className="flex items-center gap-2">
          <button
            onClick={handleRequestAiVerdict}
            disabled={analyzing}
            className="flex items-center gap-1.5 rounded-md border border-emerald-700/80 bg-emerald-950/80 hover:bg-emerald-900 px-2.5 py-1 text-xs font-semibold text-emerald-300 shadow-sm transition-all disabled:opacity-50"
            title="Invoke Verdict Triage Agent for instant AI security verdict"
          >
            {analyzing ? (
              <>
                <Loader2 className="h-3.5 w-3.5 animate-spin text-emerald-400" />
                <span>Analyzing Incident...</span>
              </>
            ) : (
              <>
                {aiVerdict ? (
                  <>
                    <RefreshCw className="h-3.5 w-3.5 text-emerald-400" />
                    <span>Re-evaluate Agent Verdict</span>
                  </>
                ) : (
                  <>
                    <Sparkles className="h-3.5 w-3.5 text-emerald-400" />
                    <span>Verdict Triage Agent</span>
                  </>
                )}
              </>
            )}
          </button>

          <button
            onClick={() => setBlindReviewMode(!blindReviewMode)}
            className={`flex items-center gap-1.5 rounded-md border px-2.5 py-1 text-xs font-semibold transition-all ${
              blindReviewMode
                ? "border-amber-500/80 bg-amber-950/80 text-amber-300 shadow-sm"
                : "border-slate-800 bg-slate-900 text-slate-400 hover:text-slate-200"
            }`}
          >
            {blindReviewMode ? (
              <>
                <EyeOff className="h-3.5 w-3.5 text-amber-400" />
                <span>Blind Review: ON</span>
              </>
            ) : (
              <>
                <Eye className="h-3.5 w-3.5 text-slate-400" />
                <span>Blind Review: OFF</span>
              </>
            )}
          </button>
        </div>
      </div>

      {blindReviewMode && (
        <div className="rounded-lg border border-amber-800/80 bg-amber-950/40 p-2.5 text-xs text-amber-300 flex items-center gap-2.5">
          <EyeOff className="h-3.5 w-3.5 shrink-0 text-amber-400" />
          <div className="text-[11px] leading-tight">
            <strong className="font-semibold text-amber-200">Blind Review Active:</strong> Historical ground truth tab and resolution verdicts are masked from view for this incident.
          </div>
        </div>
      )}

      {/* 4-Dimension Incident Verdict Clarity Matrix */}
      <IncidentVerdictMatrix
        proposedVerdict={aiVerdict?.proposed_verdict || aiVerdict?.verdict}
        validatedVerdict={aiVerdict?.verdict}
        analystVerdict={incident.ground_truth?.resolution}
        operationalStatus={incident.status_name}
        confidence={aiVerdict?.confidence}
        validationStatus={aiVerdict?.validation_status}
        groundingRatio={aiVerdict?.grounding_ratio}
        trustScore={aiVerdict?.trust_score}
        isBlindMode={blindReviewMode}
      />

      {/* Operational Next Action Card */}
      {(() => {
        let actionTitle = "Review Evidence Telemetry";
        let actionDesc = "Examine raw event logs, entity indicators, and rule context before assigning disposition.";
        let actionBtnText: string | undefined = undefined;
        let onAction: (() => void) | undefined = undefined;

        if (!aiVerdict) {
          actionTitle = "Generate Automated AI Verdict";
          actionDesc = "Run the local LLM Triage Agent against canonical evidence to evaluate threat disposition.";
          actionBtnText = "Run AI Verdict";
          onAction = handleRequestAiVerdict;
        } else if (aiVerdict.verdict === "REQUIRES_ATTENTION") {
          actionTitle = "Investigate Flagged Inconsistencies";
          actionDesc = aiVerdict.analyst_action_directive || "Model proposed verdict was withheld due to ungrounded claims or missing required evidence. Analyst validation required.";
        } else if (!incident.ground_truth?.resolution) {
          actionTitle = "Record Analyst Ground Truth";
          actionDesc = `AI classified as ${aiVerdict.verdict.replace(/_/g, " ")} (${Math.round(aiVerdict.confidence)}% confidence). Confirm or override in Human Review Queue.`;
          actionBtnText = "Submit Human Review";
          onAction = () => { setActiveTab("ground_truth"); };
        } else {
          actionTitle = "Review Synchronized Ground Truth";
          actionDesc = `Ground truth resolution recorded as '${incident.ground_truth.resolution}'. FortiSIEM status is '${incident.status_name}'.`;
        }

        return (
          <NextActionCard
            title={actionTitle}
            description={actionDesc}
            actionLabel={actionBtnText}
            onAction={onAction}
            status={aiVerdict?.verdict === "REQUIRES_ATTENTION" ? "warning" : "primary"}
          />
        );
      })()}

      {/* AI Verdict Result Box */}
      {verdictError && (
        <div className="rounded-lg border border-rose-800/80 bg-rose-950/40 p-3 text-xs text-rose-300 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <AlertCircle className="h-4 w-4 text-rose-400" />
            <span>{verdictError}</span>
          </div>
          <button onClick={() => setVerdictError(null)} className="text-xs hover:underline">
            Dismiss
          </button>
        </div>
      )}

      {aiVerdict && (
        <div className="rounded-xl border border-slate-800 bg-slate-950 p-4 space-y-3.5 shadow-lg">
          {/* Header Row */}
          <div className="flex flex-wrap items-center justify-between border-b border-slate-800 pb-2.5 gap-2">
            <div className="flex items-center gap-2 flex-wrap">
              <span className="flex items-center gap-1.5 text-xs font-bold text-emerald-400 bg-emerald-950/60 border border-emerald-800 px-2 py-0.5 rounded">
                <Sparkles className="h-3.5 w-3.5" />
                Verdict Triage Agent
              </span>
              <span className="text-xs font-mono text-slate-400">
                Engine: {aiVerdict.model_identifier}
              </span>
              {aiVerdict.evaluated_at && (
                <span className="text-[10px] font-mono text-cyan-400 bg-cyan-950/60 border border-cyan-800/60 px-1.5 py-0.5 rounded flex items-center gap-1" title={`Evaluated at ${aiVerdict.evaluated_at}`}>
                  <Database className="h-2.5 w-2.5" />
                  Stored Verdict
                </span>
              )}
              {aiVerdict.contract_id && (
                <span className="text-[10px] font-mono text-purple-300 bg-purple-950/60 border border-purple-800/60 px-1.5 py-0.5 rounded flex items-center gap-1" title={`Contract: ${aiVerdict.contract_id} v${aiVerdict.contract_version || 1}`}>
                  <Scale className="h-2.5 w-2.5 text-purple-400" />
                  Contract: {aiVerdict.contract_id} (v{aiVerdict.contract_version || 1})
                </span>
              )}
              {aiVerdict.compiler_version && (
                <span className="text-[10px] font-mono text-emerald-300 bg-emerald-950/60 border border-emerald-800/60 px-1.5 py-0.5 rounded flex items-center gap-1" title={`Compiled Policy Digest: ${aiVerdict.compilation_digest || 'N/A'}`}>
                  <FileCode className="h-2.5 w-2.5 text-emerald-400" />
                  Compiler: {aiVerdict.compiler_version} ({aiVerdict.policy_sections_count || 9}/9 secs)
                </span>
              )}
              <span className="text-[10px] font-mono text-amber-300 bg-amber-950/60 border border-amber-800/60 px-1.5 py-0.5 rounded flex items-center gap-1" title="Honest calibration status: Withheld until >= 30 verified ground truth cases">
                <ShieldCheck className="h-2.5 w-2.5 text-amber-400" />
                Calibration: {aiVerdict.calibration_status || "NOT_CALIBRATED"}
              </span>
            </div>
            <div className="flex flex-wrap items-center gap-3 text-xs font-mono text-slate-400">
              <span className="flex items-center gap-1 text-slate-300" title="Inference Execution Time">
                <Clock className="h-3 w-3 text-cyan-400" />
                Time: <strong className="text-slate-100">{aiVerdict.latency_ms} ms</strong>
                <span className="text-[10px] text-slate-500">({(aiVerdict.latency_ms / 1000).toFixed(2)}s)</span>
              </span>

              <span className="flex items-center gap-1 text-slate-300" title="Tokens Consumed">
                <Cpu className="h-3 w-3 text-purple-400" />
                Tokens: <strong className="text-purple-300">{aiVerdict.total_tokens || 0}</strong>
                <span className="text-[10px] text-slate-500">({aiVerdict.prompt_tokens || 0} in / {aiVerdict.completion_tokens || 0} out)</span>
              </span>

              {(() => {
                const pb = formatExecutionProvenanceBadge({
                  executionProvenance: aiVerdict.execution_provenance,
                  isSimulated: aiVerdict.is_simulated,
                  validationStatus: aiVerdict.validation_status,
                  modelIdentifier: aiVerdict.model_identifier,
                  currentS2Health: llmOnline ? "ONLINE" : "OFFLINE",
                });
                const text =
                  aiVerdict.validation_status === "INVALID_MODEL_OUTPUT"
                    ? "• INVALID_MODEL_OUTPUT (Abstained)"
                    : pb.label === "SIMULATED"
                    ? "• SIMULATED (Non-Production)"
                    : ["POLICY_GUARD", "PREFLIGHT_GUARD", "TOKEN_BUDGET_GUARD", "VALIDATION_GUARD"].includes(pb.label)
                    ? `• Deterministic Guard (${aiVerdict.model_identifier || pb.label})`
                    : pb.label === "LIVE_PROVIDER"
                    ? llmOnline
                      ? `• LIVE_PROVIDER (${aiVerdict.model_identifier || "Verdictum Cortex"}) • Cortex Online`
                      : `• Historical Live Record (Cortex Offline Now) • LIVE_PROVIDER`
                    : `• Provenance: ${pb.label} (${aiVerdict.model_identifier || "Model"}) • Cortex Now: ${llmOnline ? "ONLINE" : "OFFLINE"}`;
                return (
                  <span
                    className={`px-1.5 py-0.5 rounded border font-semibold ${pb.className}`}
                    title={pb.sublabel}
                  >
                    {text}
                  </span>
                );
              })()}
              <button
                type="button"
                onClick={() => setPromptInspectorOpen(true)}
                className="px-2 py-0.5 rounded border border-emerald-700 bg-emerald-950/60 hover:bg-emerald-900/80 text-emerald-300 text-[10px] font-semibold flex items-center gap-1 shadow-sm transition-colors"
                title="Inspect exact prompt payload sent to Local LLM for this incident"
              >
                <Terminal className="w-3 h-3 text-emerald-400" />
                <span>View Actual LLM Prompt</span>
              </button>
              <button
                onClick={() => setAiVerdict(null)}
                className="text-slate-400 hover:text-slate-200 text-xs px-1"
                title="Hide banner"
              >
                ✕
              </button>
            </div>
          </div>

          {/* Overrule Alert Banner (when LLM proposed TP/FP but validator overrode to REQUIRES_ATTENTION) */}
          {aiVerdict.proposed_verdict && aiVerdict.proposed_verdict !== aiVerdict.verdict && (
            <div className="rounded-lg border border-amber-500/80 bg-amber-950/40 p-3 text-xs text-amber-200 flex items-start gap-2.5">
              <ShieldAlert className="h-4 w-4 text-amber-400 shrink-0 mt-0.5" />
              <div className="space-y-1">
                <div className="font-semibold text-amber-300 flex items-center gap-2">
                  <span>Deterministic Safety Override Applied</span>
                  <span className="text-[10px] font-mono bg-amber-900/60 border border-amber-700 px-1.5 py-0.2 rounded text-amber-200">
                    Proposed: {aiVerdict.proposed_verdict} → Final: {aiVerdict.verdict}
                  </span>
                </div>
                <p className="text-[11px] text-amber-300/90 leading-relaxed">
                  The model proposed a decisive <strong>{aiVerdict.proposed_verdict}</strong>, but independent verification rejected it due to incomplete telemetry, ungrounded claims, or unapproved policy contracts.
                </p>
              </div>
            </div>
          )}

          {/* Authoritative Verdict Card */}
          <div
            className={`rounded-lg border p-3 flex flex-wrap items-center justify-between gap-3 ${
              aiVerdict.verdict === "TRUE_POSITIVE"
                ? "bg-rose-950/50 border-rose-800 text-rose-200"
                : aiVerdict.verdict === "FALSE_POSITIVE"
                ? "bg-emerald-950/50 border-emerald-800 text-emerald-200"
                : "bg-amber-950/50 border-amber-800 text-amber-200"
            }`}
          >
            <div className="flex items-center gap-2.5">
              {aiVerdict.verdict === "TRUE_POSITIVE" ? (
                <AlertTriangle className="h-6 w-6 text-rose-400 shrink-0" />
              ) : aiVerdict.verdict === "FALSE_POSITIVE" ? (
                <CheckCircle2 className="h-6 w-6 text-emerald-400 shrink-0" />
              ) : (
                <AlertCircle className="h-6 w-6 text-amber-400 shrink-0" />
              )}
              <div>
                <div className="text-[10px] uppercase font-mono tracking-wider opacity-80 flex items-center gap-1.5">
                  Authoritative Platform Verdict
                  {aiVerdict.is_decisive_accepted ? (
                    <span className="text-[9px] bg-emerald-900/80 border border-emerald-600 px-1 py-0.2 rounded text-emerald-300 font-bold">
                      VERIFIED ACCEPTED
                    </span>
                  ) : (
                    <span className="text-[9px] bg-amber-900/80 border border-amber-600 px-1 py-0.2 rounded text-amber-300 font-bold">
                      ABSTAINED / FORCED ATTENTION
                    </span>
                  )}
                </div>
                <div className="text-base font-extrabold tracking-tight">
                  {aiVerdict.verdict.replace(/_/g, " ")}
                </div>
              </div>
            </div>

            <div className="flex items-center gap-6">
              {aiVerdict.raw_model_confidence !== undefined && aiVerdict.raw_model_confidence !== aiVerdict.confidence && (
                <div className="text-right border-r border-slate-700/60 pr-5">
                  <div className="text-[10px] uppercase font-mono tracking-wider text-slate-400" title="Raw uncalibrated score generated by LLM prior to validation">
                    Raw LLM Score
                  </div>
                  <div className="text-xs font-mono text-slate-300">
                    {Math.round(aiVerdict.raw_model_confidence)}% <span className="text-[9px] text-slate-500">(Uncalibrated)</span>
                  </div>
                </div>
              )}
              <div className="text-right">
                <div className="text-[10px] uppercase font-mono tracking-wider opacity-80" title="Effective confidence after independent deterministic evidence verification">
                  Effective Confidence
                </div>
                <div className="text-lg font-extrabold font-mono">
                  {Math.round(aiVerdict.confidence)}%
                </div>
              </div>
            </div>
          </div>

          {/* Phase 2 Evidence Grounding & Verification Metrics Bar */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs font-mono">
            {/* Metric 1: Completeness */}
            <div className="p-2 rounded-lg bg-slate-900/80 border border-slate-800">
              <span className="text-[9px] text-slate-400 block uppercase">Evidence Completeness</span>
              <div className="flex items-baseline gap-1.5 mt-0.5">
                <span className={`text-sm font-bold ${
                  (aiVerdict.evidence_completeness ?? 0) >= 0.8
                    ? "text-emerald-400"
                    : (aiVerdict.evidence_completeness ?? 0) >= 0.4
                    ? "text-amber-400"
                    : "text-rose-400"
                }`}>
                  {Math.round((aiVerdict.evidence_completeness ?? 0) * 100)}%
                </span>
                <span className="text-[10px] text-slate-500">
                  ({aiVerdict.canonical_evidence_count ?? 0} canonical recs)
                </span>
              </div>
            </div>

            {/* Metric 2: Claim Grounding */}
            <div className="p-2 rounded-lg bg-slate-900/80 border border-slate-800">
              <span className="text-[9px] text-slate-400 block uppercase">Claim Grounding Ratio</span>
              <div className="flex items-baseline gap-1.5 mt-0.5">
                {(aiVerdict.total_claims_count ?? 0) === 0 ? (
                  <>
                    <span className={`text-sm font-bold ${aiVerdict.verdict === "REQUIRES_ATTENTION" ? "text-amber-400" : "text-rose-400"}`}>
                      N/A
                    </span>
                    <span className="text-[10px] text-slate-400">
                      (0/0 claims — unclaimed)
                    </span>
                  </>
                ) : (
                  <>
                    <span className={`text-sm font-bold ${
                      (aiVerdict.grounding_ratio ?? 0) >= 0.99
                        ? "text-emerald-400"
                        : "text-rose-400"
                    }`}>
                      {Math.round((aiVerdict.grounding_ratio ?? 0) * 100)}%
                    </span>
                    <span className="text-[10px] text-slate-500">
                      ({aiVerdict.grounded_claims_count ?? 0}/{aiVerdict.total_claims_count ?? 0} grounded)
                    </span>
                  </>
                )}
              </div>
            </div>

            {/* Metric 3: Validation Status */}
            <div className="p-2 rounded-lg bg-slate-900/80 border border-slate-800">
              <span className="text-[9px] text-slate-400 block uppercase">Validation Status</span>
              <div className="mt-0.5 flex flex-wrap items-center gap-1.5">
                <span className={`text-xs font-bold px-1.5 py-0.5 rounded border inline-block ${
                  aiVerdict.validation_status === "VALIDATED"
                    ? "bg-emerald-950 text-emerald-300 border-emerald-800"
                    : aiVerdict.validation_status === "INSUFFICIENT_EVIDENCE"
                    ? "bg-amber-950 text-amber-300 border-amber-800"
                    : "bg-rose-950 text-rose-300 border-rose-800"
                }`}>
                  {aiVerdict.validation_status || "UNVERIFIED"}
                </span>
                {aiVerdict.trust_score !== undefined && aiVerdict.trust_score !== null && (() => {
                  const isCalibrated = Boolean(aiVerdict.is_calibrated);
                  const rawScore = Number(aiVerdict.trust_score);
                  const capApplied = Boolean((aiVerdict as { trust_cap_applied?: boolean }).trust_cap_applied) || (!isCalibrated && rawScore > 6);
                  const effectiveScore = isCalibrated ? rawScore : Math.min(6, rawScore);
                  const historicalScore = (aiVerdict as { historical_trust_score?: number | null }).historical_trust_score ?? (capApplied ? rawScore : null);
                  return (
                    <span className="inline-flex items-center gap-1.5 flex-wrap">
                      <span className={`text-[10px] font-mono px-1.5 py-0.5 rounded border ${
                        effectiveScore >= 7
                          ? "bg-emerald-950/60 text-emerald-300 border-emerald-800/70"
                          : effectiveScore >= 4
                          ? "bg-amber-950/60 text-amber-300 border-amber-800/70"
                          : "bg-rose-950/60 text-rose-300 border-rose-800/70"
                      }`}>
                        Trust: {effectiveScore}/10 ({isCalibrated ? "Calibrated" : capApplied ? "Uncalibrated Cap" : "Uncalibrated Ordinal"})
                      </span>
                      {historicalScore !== null && historicalScore !== undefined && historicalScore !== effectiveScore && (
                        <span className="text-[10px] font-mono px-1.5 py-0.5 rounded border bg-slate-900 text-slate-400 border-slate-700" title="Preserved legacy stored score prior to uncalibrated <= 6/10 cap">
                          Historical stored: {historicalScore}/10 (pre-cap)
                        </span>
                      )}
                    </span>
                  );
                })()}
              </div>
              {aiVerdict.final_disposition && (
                <span className="text-[9px] text-slate-400 font-mono block mt-1 truncate" title={aiVerdict.final_disposition}>
                  Disposition: {aiVerdict.final_disposition}
                </span>
              )}
            </div>

            {/* Metric 4: Replay Audit */}
            <div className="p-2 rounded-lg bg-slate-900/80 border border-slate-800">
              <span className="text-[9px] text-slate-400 block uppercase">Replay Signature</span>
              <div className="flex items-center justify-between mt-0.5">
                <span className="text-xs text-cyan-300 font-mono truncate" title={aiVerdict.replay_signature}>
                  {aiVerdict.replay_signature ? `${aiVerdict.replay_signature.substring(0, 10)}...` : "N/A"}
                </span>
                {aiVerdict.replay_signature && (
                  <button
                    onClick={() => copyToClipboard(aiVerdict.replay_signature || "")}
                    className="text-[9px] text-slate-400 hover:text-white"
                    title="Copy full cryptographic signature"
                  >
                    Copy
                  </button>
                )}
              </div>
            </div>
          </div>

          {/* Analyst Action Directive */}
          {aiVerdict.analyst_action_directive && (
            <div className="rounded-lg border border-cyan-800/60 bg-cyan-950/30 p-2.5 text-xs text-cyan-200 flex items-start gap-2">
              <FileCheck2 className="h-4 w-4 text-cyan-400 shrink-0 mt-0.5" />
              <div>
                <strong className="text-cyan-300 font-semibold block text-[11px] uppercase tracking-wider">
                  Analyst Action Directive:
                </strong>
                <p className="text-xs text-slate-200 font-sans mt-0.5 leading-relaxed">
                  {aiVerdict.analyst_action_directive}
                </p>
              </div>
            </div>
          )}

          {/* Reason & Analytical Justification */}
          <div className="rounded-lg border border-slate-800 bg-slate-900/60 p-3 space-y-1">
            <div className="text-[10px] font-mono uppercase text-slate-400 tracking-wider flex items-center gap-1.5">
              <Bot className="h-3 w-3 text-cyan-400" />
              Analytical Justification & Deterministic Evaluation
            </div>
            <p className="text-xs text-slate-200 leading-relaxed font-sans">
              {aiVerdict.reason}
            </p>
          </div>

          {/* Advanced Technical Diagnostics & Evidence Validation (Collapsible on demand) */}
          <AdvancedDetailsPanel
            title={`Technical Diagnostics & Evidence Validation (${(aiVerdict.validation_reason_codes?.length || 0) + (aiVerdict.unsupported_claims?.length || 0) + (aiVerdict.missing_evidence?.length || 0)} indicators)`}
            defaultOpen={aiVerdict.verdict === "REQUIRES_ATTENTION"}
          >
            <div className="space-y-3 pt-1">
              {/* Validation Reason Codes */}
              {aiVerdict.validation_reason_codes && aiVerdict.validation_reason_codes.length > 0 && (
                <div className="space-y-1">
                  <div className="text-[10px] font-mono uppercase text-slate-400 tracking-wider">
                    Validation Assessment Codes ({aiVerdict.validation_reason_codes.length}):
                  </div>
                  <div className="flex flex-wrap gap-1.5">
                    {aiVerdict.validation_reason_codes.map((code, idx) => (
                      <span
                        key={idx}
                        className={`text-[10px] font-mono px-2 py-0.5 rounded border ${
                          code.includes("PASSED")
                            ? "bg-emerald-950/70 text-emerald-300 border-emerald-800"
                            : code.includes("CLAIM_UNGROUNDED") || code.includes("CONTRADICTION")
                            ? "bg-rose-950/80 text-rose-300 border-rose-800"
                            : "bg-amber-950/70 text-amber-300 border-amber-800"
                        }`}
                      >
                        {code}
                      </span>
                    ))}
                  </div>
                </div>
              )}

              {/* Unsupported Claims Alert (if any hallucinated claims detected) */}
              {aiVerdict.unsupported_claims && aiVerdict.unsupported_claims.length > 0 && (
                <div className="rounded-lg border border-rose-800/80 bg-rose-950/40 p-3 space-y-2 text-xs">
                  <div className="flex items-center gap-2 text-rose-300 font-semibold">
                    <AlertTriangle className="h-4 w-4 text-rose-400" />
                    <span>Unsupported / Fabricated Claims Detected ({aiVerdict.unsupported_claims.length})</span>
                  </div>
                  <p className="text-[11px] text-rose-200/90 leading-relaxed">
                    The model cited facts not present in verified incident telemetry. Independent verification flagged and neutralized these claims:
                  </p>
                  <div className="space-y-1 font-mono text-[11px]">
                    {aiVerdict.unsupported_claims.map((claim, idx) => (
                      <div key={idx} className="p-1.5 rounded bg-rose-950 border border-rose-800/60 flex items-center justify-between">
                        <div>
                          <span className="text-rose-400 font-bold">{claim.claim_type}: </span>
                          <span className="text-slate-200">{String(claim.asserted_value)} </span>
                          <span className="text-slate-500">({claim.field})</span>
                        </div>
                        <span className="text-[9px] bg-rose-900 text-rose-200 px-1 py-0.2 rounded uppercase">
                          {claim.grounding_status || "UNGROUNDED"}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Missing Required Telemetry & Field Mapping Diagnostics */}
              {aiVerdict.missing_evidence && aiVerdict.missing_evidence.length > 0 && (
                <div className="rounded-lg border border-slate-800/80 bg-slate-900/40 p-3 space-y-1.5">
                  <div className="text-[10px] font-mono uppercase text-amber-400 tracking-wider flex items-center gap-1.5">
                    <AlertCircle className="h-3 w-3" />
                    Missing Required Evidence Telemetry ({aiVerdict.missing_evidence.length})
                  </div>
                  <ul className="text-xs space-y-1.5 text-slate-300">
                    {aiVerdict.missing_evidence.map((item, idx) => {
                      const itemKey = typeof item === "object" && item !== null ? JSON.stringify(item) : String(item);
                      const status = (aiVerdict as any).field_validation_status?.[itemKey] || (aiVerdict as any).field_validation_status?.[item as any];
                      return (
                        <li key={idx} className="text-[11px] leading-tight flex items-center justify-between font-mono">
                          <span className="text-amber-200/90">{itemKey}</span>
                          {status && (
                            <span className={`text-[9px] px-1.5 py-0.5 rounded uppercase font-semibold ${
                              status === "NOT_MAPPED"
                                ? "bg-rose-950 text-rose-300 border border-rose-800"
                                : status === "CONTEXT_OMITTED"
                                ? "bg-purple-950 text-purple-300 border border-purple-800"
                                : status === "NOT_IN_SOURCE"
                                ? "bg-slate-800 text-slate-300 border border-slate-700"
                                : "bg-amber-950 text-amber-300 border border-amber-800"
                            }`}>
                              {status === "NOT_MAPPED" ? "Field Mapping Error" : status === "NOT_IN_SOURCE" ? "Not In Source" : status}
                            </span>
                          )}
                        </li>
                      );
                    })}
                  </ul>
                </div>
              )}

              {/* Unmapped Raw Attributes Detected */}
              {(aiVerdict as any).unmapped_fields && (aiVerdict as any).unmapped_fields.length > 0 && (
                <div className="rounded-lg border border-amber-900/60 bg-amber-950/20 p-2.5 space-y-1 text-xs">
                  <div className="text-[10px] font-mono uppercase text-amber-400 tracking-wider flex items-center gap-1.5">
                    <AlertTriangle className="h-3 w-3 text-amber-400" />
                    Unmapped Source Event Attributes ({(aiVerdict as any).unmapped_fields.length})
                  </div>
                  <p className="text-[11px] text-amber-300/80 leading-relaxed font-sans">
                    Source telemetry contains unmapped raw attributes. Normalization fell back safely without data corruption:
                  </p>
                  <div className="flex flex-wrap gap-1 font-mono text-[10px] pt-1">
                    {(aiVerdict as any).unmapped_fields.slice(0, 10).map((field: any, idx: number) => {
                      const isObj = typeof field === "object" && field !== null;
                      const fieldName = isObj ? (field.raw_field || JSON.stringify(field)) : String(field);
                      const fieldValue = isObj && field.value !== undefined ? String(field.value) : null;
                      const fieldReason = isObj && field.reason ? String(field.reason) : null;
                      const sourceEvt = isObj && field.source_event_id ? String(field.source_event_id) : null;
                      const titleTooltip = [
                        `Field: ${fieldName}`,
                        fieldValue ? `Value: ${fieldValue}` : null,
                        fieldReason ? `Reason: ${fieldReason}` : null,
                        sourceEvt ? `Event: ${sourceEvt}` : null,
                      ].filter(Boolean).join(" | ");

                      return (
                        <span
                          key={idx}
                          title={titleTooltip}
                          className="bg-slate-900 text-slate-300 px-1.5 py-0.5 rounded border border-slate-800 hover:border-amber-700/60 transition-colors"
                        >
                          {fieldName}
                          {fieldValue && (
                            <span className="text-slate-500 ml-1 font-sans">
                              ({fieldValue.length > 25 ? fieldValue.slice(0, 25) + "…" : fieldValue})
                            </span>
                          )}
                        </span>
                      );
                    })}
                    {(aiVerdict as any).unmapped_fields.length > 10 && (
                      <span className="text-slate-500 self-center">+{(aiVerdict as any).unmapped_fields.length - 10} more</span>
                    )}
                  </div>
                </div>
              )}

              {/* Supporting Evidence Attributes */}
              {aiVerdict.supporting_evidence && aiVerdict.supporting_evidence.length > 0 && (
                <div className="rounded-lg border border-slate-800/80 bg-slate-900/40 p-3 space-y-1.5">
                  <div className="text-[10px] font-mono uppercase text-slate-400 tracking-wider">
                    Supporting Evidence Attributes ({aiVerdict.supporting_evidence.length})
                  </div>
                  <ul className="text-xs space-y-1 text-slate-300 list-disc list-inside">
                    {aiVerdict.supporting_evidence.map((ev, idx) => (
                      <li key={idx} className="text-[11px] font-mono leading-tight">
                        {typeof ev === "object" && ev !== null ? JSON.stringify(ev) : String(ev)}
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {/* Phase 3 Verified Historical Precedents (Semantic RAG) */}
              {aiVerdict.retrieved_precedents && aiVerdict.retrieved_precedents.length > 0 && (
                <div className="rounded-lg border border-indigo-900/60 bg-indigo-950/20 p-3 space-y-2 text-xs">
                  <div className="flex items-center justify-between text-indigo-300 font-semibold">
                    <div className="flex items-center gap-2">
                      <Database className="h-4 w-4 text-indigo-400" />
                      <span>Verified Historical Precedents ({aiVerdict.retrieved_precedents.length})</span>
                    </div>
                    <span className="text-[10px] font-mono text-indigo-400/80">
                      Tenant-Isolated & Exact-Rule Scoped
                    </span>
                  </div>
                  <div className="space-y-2">
                    {aiVerdict.retrieved_precedents.map((prec, idx) => (
                      <div key={idx} className="p-2.5 rounded bg-slate-900/90 border border-indigo-900/40 text-[11px] font-mono space-y-1">
                        <div className="flex items-center justify-between">
                          <span className="text-indigo-300 font-bold">{prec.incident_title || prec.incident_id}</span>
                          <div className="flex items-center gap-2">
                            <span className="text-[10px] text-slate-400">Similarity: {(prec.similarity_score * 100).toFixed(0)}%</span>
                            <span className={`px-1.5 py-0.2 rounded text-[10px] font-bold ${
                              prec.verified_verdict === "TRUE_POSITIVE"
                                ? "bg-rose-950 text-rose-300 border border-rose-800"
                                : "bg-emerald-950 text-emerald-300 border border-emerald-800"
                            }`}>
                              {prec.verified_verdict}
                            </span>
                          </div>
                        </div>
                        <p className="text-slate-300 font-sans text-xs">
                          {prec.analyst_explanation}
                        </p>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </AdvancedDetailsPanel>
        </div>
      )}

      {/* Tabs Header */}
      <div className="flex border-b border-slate-800 space-x-1 overflow-x-auto text-xs font-medium">
        <button
          onClick={() => setActiveTab("overview")}
          className={`px-3 py-1.5 border-b-2 transition-colors whitespace-nowrap ${
            activeTab === "overview"
              ? "border-cyan-500 text-cyan-300 font-semibold"
              : "border-transparent text-slate-400 hover:text-slate-200"
          }`}
        >
          Incident Overview
        </button>

        <button
          onClick={() => setActiveTab("events")}
          className={`px-3 py-1.5 border-b-2 transition-colors whitespace-nowrap flex items-center gap-1.5 ${
            activeTab === "events"
              ? "border-cyan-500 text-cyan-300 font-semibold"
              : "border-transparent text-slate-400 hover:text-slate-200"
          }`}
        >
          Raw Events
          <span className="rounded bg-slate-800 px-1 py-0.2 text-[9px] font-mono text-slate-300">
            {incident.events.length}
          </span>
        </button>

        <button
          onClick={() => setActiveTab("rule")}
          className={`px-3 py-1.5 border-b-2 transition-colors whitespace-nowrap ${
            activeTab === "rule"
              ? "border-cyan-500 text-cyan-300 font-semibold"
              : "border-transparent text-slate-400 hover:text-slate-200"
          }`}
        >
          Detection Intelligence Context
        </button>

        <button
          onClick={() => setActiveTab("ground_truth")}
          className={`px-3 py-1.5 border-b-2 transition-colors whitespace-nowrap flex items-center gap-1.5 ${
            activeTab === "ground_truth"
              ? "border-cyan-500 text-cyan-300 font-semibold"
              : "border-transparent text-slate-400 hover:text-slate-200"
          }`}
        >
          Historical Ground Truth
          {blindReviewMode && <EyeOff className="h-3 w-3 text-amber-400" />}
        </button>

        <button
          onClick={() => setActiveTab("raw_json")}
          className={`px-3 py-1.5 border-b-2 transition-colors whitespace-nowrap ${
            activeTab === "raw_json"
              ? "border-cyan-500 text-cyan-300 font-semibold"
              : "border-transparent text-slate-400 hover:text-slate-200"
          }`}
        >
          Raw Payload JSON
        </button>

        <button
          onClick={() => setActiveTab("model_payload")}
          className={`px-3 py-1.5 border-b-2 transition-colors whitespace-nowrap flex items-center gap-1.5 ${
            activeTab === "model_payload"
              ? "border-cyan-500 text-cyan-300 font-semibold"
              : "border-transparent text-slate-400 hover:text-slate-200"
          }`}
        >
          <Cpu className="h-3 w-3 text-cyan-400" />
          Evidence Integrity Guardrail
        </button>

        <button
          onClick={() => setActiveTab("timeline")}
          className={`px-3 py-1.5 border-b-2 transition-colors whitespace-nowrap flex items-center gap-1.5 ${
            activeTab === "timeline"
              ? "border-cyan-500 text-cyan-300 font-semibold"
              : "border-transparent text-slate-400 hover:text-slate-200"
          }`}
        >
          <Clock className="h-3 w-3 text-cyan-400" />
          Historical Telemetry Timeline
        </button>

        <button
          onClick={() => setActiveTab("canonical_evidence")}
          className={`px-3 py-1.5 border-b-2 transition-colors whitespace-nowrap flex items-center gap-1.5 ${
            activeTab === "canonical_evidence"
              ? "border-cyan-500 text-cyan-300 font-semibold"
              : "border-transparent text-slate-400 hover:text-slate-200"
          }`}
        >
          <Scale className="h-3 w-3 text-cyan-400" />
          Canonical Evidence
          {modelPayload?.canonical_evidence && (
            <span className="rounded bg-slate-800 px-1 py-0.2 text-[9px] font-mono text-cyan-300">
              {modelPayload.canonical_evidence.length}
            </span>
          )}
        </button>
      </div>

      {/* Tab 1: Overview */}
      {activeTab === "overview" && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-3">
          <div className="lg:col-span-2 space-y-3">
            {/* Description & Detail */}
            <div className="rounded-lg border border-slate-800 bg-slate-950 p-3 sm:p-3.5 space-y-2.5">
              <h2 className="text-xs font-bold uppercase tracking-wider text-slate-300">
                Investigation Description & Details
              </h2>
              <div className="space-y-2 text-xs leading-relaxed text-slate-300">
                <div>
                  <span className="text-[10px] font-mono text-slate-500 block mb-0.5">Description:</span>
                  <div className="p-2.5 rounded-md bg-slate-900 border border-slate-800 font-mono text-xs">
                    {incident.description || "No description provided by SIEM."}
                  </div>
                </div>
                {incident.detail && (
                  <div>
                    <span className="text-[10px] font-mono text-slate-500 block mb-0.5">Detail Telemetry:</span>
                    <pre className="p-2.5 rounded-md bg-slate-900 border border-slate-800 font-mono text-[11px] overflow-x-auto whitespace-pre-wrap max-h-56">
                      {incident.detail}
                    </pre>
                  </div>
                )}
              </div>
            </div>

            {/* Network & Device Evidence */}
            <div className="rounded-lg border border-slate-800 bg-slate-950 p-3 sm:p-3.5 space-y-2.5">
              <h2 className="text-xs font-bold uppercase tracking-wider text-slate-300">
                Network & Reporting Entities
              </h2>
              <div className="grid grid-cols-2 gap-2 text-xs font-mono">
                <div className="p-2.5 rounded-md bg-slate-900 border border-slate-800">
                  <span className="text-slate-500 text-[9px] block">Source IP:</span>
                  <span className="text-slate-200 font-bold">{incident.source_ip || "Internal / Host"}</span>
                </div>
                <div className="p-2.5 rounded-md bg-slate-900 border border-slate-800">
                  <span className="text-slate-500 text-[9px] block">Reporting IP:</span>
                  <span className="text-slate-200">{incident.reporting_ip || "N/A"}</span>
                </div>
                <div className="p-2.5 rounded-md bg-slate-900 border border-slate-800">
                  <span className="text-slate-500 text-[9px] block">Reporting Device:</span>
                  <span className="text-slate-200 truncate block">{incident.reporting_device || "N/A"}</span>
                </div>
                <div className="p-2.5 rounded-md bg-slate-900 border border-slate-800">
                  <span className="text-slate-500 text-[9px] block">Category / Subcategory:</span>
                  <span className="text-slate-200 truncate block">
                    {incident.category || "General"} {incident.subcategory ? `· ${incident.subcategory}` : ""}
                  </span>
                </div>
              </div>
            </div>
          </div>

          {/* Right Summary Column */}
          <div className="space-y-3">
            <div className="rounded-lg border border-slate-800 bg-slate-950 p-3 sm:p-3.5 space-y-2.5 text-xs">
              <h2 className="font-bold uppercase tracking-wider text-slate-300 text-xs">Metadata Summary</h2>
              <div className="space-y-1.5 font-mono text-[11px]">
                <div className="flex justify-between py-1 border-b border-slate-800">
                  <span className="text-slate-400">SIEM Event Type:</span>
                  <span className="text-slate-200 truncate max-w-[150px]">{incident.event_type}</span>
                </div>
                <div className="flex justify-between py-1 border-b border-slate-800">
                  <span className="text-slate-400">Rule Name:</span>
                  <span className="text-slate-200 truncate max-w-[150px]">{incident.rule_name || "Unmapped"}</span>
                </div>
                <div className="flex justify-between py-1 border-b border-slate-800">
                  <span className="text-slate-400">First Seen:</span>
                  <span className="text-slate-200">{formatEpoch(incident.first_seen_epoch)}</span>
                </div>
                <div className="flex justify-between py-1 border-b border-slate-800">
                  <span className="text-slate-400">Last Seen:</span>
                  <span className="text-slate-200">{formatEpoch(incident.last_seen_epoch)}</span>
                </div>
                <div className="flex justify-between py-1 border-b border-slate-800">
                  <span className="text-slate-400">Created At:</span>
                  <span className="text-slate-200">{formatEpoch(incident.created_at_epoch, incident.created_at)}</span>
                </div>
                <div className="flex justify-between py-1">
                  <span className="text-slate-400">Customer:</span>
                  <span className="text-slate-200">{incident.customer || "Enterprise Default"}</span>
                </div>
              </div>

              {incident.rule_id && (
                <div className="pt-1">
                  <Link
                    href={`/detection-intelligence/${incident.rule_id}`}
                    className="block w-full text-center rounded-md bg-slate-900 border border-slate-800 py-1.5 text-xs font-semibold text-cyan-400 hover:bg-slate-800 transition-colors"
                  >
                    View Detection Intelligence Rule →
                  </Link>
                </div>
              )}
            </div>

            {/* FortiSIEM Resolution & Ground Truth Card */}
            <div className="rounded-lg border border-slate-800 bg-slate-950 p-3 sm:p-3.5 space-y-2.5 text-xs">
              <div className="flex items-center justify-between border-b border-slate-800 pb-2">
                <div className="flex items-center gap-1.5 font-bold uppercase tracking-wider text-slate-300 text-xs">
                  <ShieldCheck className="h-3.5 w-3.5 text-cyan-400" />
                  <span>SIEM Resolution & Ground Truth</span>
                </div>
                <button
                  onClick={handleSyncResolution}
                  disabled={syncingResolution}
                  className="inline-flex items-center gap-1 rounded bg-slate-900 border border-cyan-800/60 px-2 py-0.5 text-[10px] font-semibold text-cyan-300 hover:bg-slate-800 disabled:opacity-50 transition-colors"
                  title="Pull latest closure status, resolution, and cleared reason from FortiSIEM"
                >
                  <RefreshCw className={`h-2.5 w-2.5 ${syncingResolution ? "animate-spin text-cyan-400" : ""}`} />
                  <span>{syncingResolution ? "Syncing..." : "Sync SIEM"}</span>
                </button>
              </div>

              {syncSuccessMessage && (
                <div className="rounded bg-emerald-950/70 border border-emerald-800 p-2 text-[11px] text-emerald-300 flex items-center gap-1.5">
                  <CheckCircle2 className="h-3.5 w-3.5 text-emerald-400 shrink-0" />
                  <span>{syncSuccessMessage}</span>
                </div>
              )}

              {blindReviewMode ? (
                <div className="rounded bg-amber-950/30 border border-amber-900/60 p-2.5 text-[11px] text-amber-300 flex items-center gap-2">
                  <EyeOff className="h-3.5 w-3.5 text-amber-400 shrink-0" />
                  <span>Resolution details hidden in Blind Review mode.</span>
                </div>
              ) : (
                <div className="space-y-2">
                  {/* Status & Resolution Row */}
                  <div className="grid grid-cols-2 gap-2">
                    <div className="p-2 rounded bg-slate-900 border border-slate-800">
                      <span className="text-[9px] uppercase tracking-wider text-slate-400 block mb-0.5">
                        Incident Status
                      </span>
                      <span className={`inline-flex items-center gap-1 px-1.5 py-0.2 rounded border text-[10px] font-bold ${
                        incident.status_name === "Manually Cleared" || incident.status_code === 2
                          ? "bg-purple-950/80 text-purple-300 border-purple-800"
                          : "bg-blue-950/80 text-blue-300 border-blue-800"
                      }`}>
                        {incident.status_name === "Manually Cleared" && <Check className="h-2.5 w-2.5" />}
                        {incident.status_name}
                      </span>
                    </div>

                    <div className="p-2 rounded bg-slate-900 border border-slate-800">
                      <span className="text-[9px] uppercase tracking-wider text-slate-400 block mb-0.5">
                        Resolution
                      </span>
                      <span className={`inline-block px-1.5 py-0.2 rounded border text-[10px] font-bold ${
                        incident.ground_truth?.resolution === "True Positive"
                          ? "bg-rose-950/90 text-rose-300 border-rose-800"
                          : incident.ground_truth?.resolution === "False Positive"
                          ? "bg-emerald-950/90 text-emerald-300 border-emerald-800"
                          : "bg-slate-900 text-slate-400 border-slate-800"
                      }`}>
                        {incident.ground_truth?.resolution || "Unresolved / Open"}
                      </span>
                    </div>
                  </div>

                  {/* Cleared Reason */}
                  {incident.ground_truth?.cleared_reason && (
                    <div className="p-2 rounded bg-slate-900 border border-slate-800">
                      <span className="text-[9px] uppercase tracking-wider text-slate-400 block mb-0.5">
                        Cleared Reason
                      </span>
                      <p className="text-[11px] text-slate-200 font-sans italic">
                        "{incident.ground_truth.cleared_reason}"
                      </p>
                    </div>
                  )}

                  {/* Cleared User & Cleared Time */}
                  <div className="grid grid-cols-2 gap-2 text-[10px] font-mono text-slate-400 pt-1 border-t border-slate-800/80">
                    <div>
                      <span className="text-slate-500 block text-[9px]">Cleared User:</span>
                      <span className="text-slate-200 font-semibold truncate block">
                        {incident.ground_truth?.cleared_user || "N/A"}
                      </span>
                    </div>
                    <div>
                      <span className="text-slate-500 block text-[9px]">Cleared Time:</span>
                      <span className="text-slate-200 truncate block">
                        {incident.ground_truth?.cleared_time_epoch
                          ? formatEpoch(incident.ground_truth.cleared_time_epoch)
                          : "N/A"}
                      </span>
                    </div>
                  </div>

                  {incident.ground_truth?.comments && (
                    <div className="text-[10px] text-slate-400 pt-1">
                      <span className="text-slate-500 block text-[9px]">Comments:</span>
                      <span className="text-slate-300">{incident.ground_truth.comments}</span>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Tab 2: Raw Events Explorer */}
      {activeTab === "events" && (
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <span className="text-xs text-slate-400 font-mono">
              Displaying all {incident.events.length} raw security event logs and vendor attributes
            </span>
          </div>

          {incident.events.length === 0 ? (
            <div className="p-8 rounded-lg border border-slate-800 bg-slate-950 text-center text-xs text-slate-400 font-mono">
              No raw security events recorded for this incident.
            </div>
          ) : (
            <div className="space-y-2.5">
              {incident.events.map((evt, idx) => {
                const rawLog = evt.raw_log || evt.attributes?.["Raw Event Log"] || evt.attributes?.["rawMessage"] || evt.attributes?.["rawEventLog"];
                // Filter out raw log from the key-value attributes grid to avoid duplication
                const filteredAttrs = Object.entries(evt.attributes || {}).filter(
                  ([k]) => k !== "Raw Event Log" && k !== "rawMessage" && k !== "rawEventLog"
                );

                return (
                  <div key={evt.id || idx} className="rounded-lg border border-slate-800 bg-slate-950 p-3 space-y-2 font-mono text-xs">
                    <div className="flex items-center justify-between border-b border-slate-800/80 pb-1.5">
                      <div className="flex items-center gap-2">
                        <span className="rounded bg-cyan-950/70 border border-cyan-800 px-1.5 py-0.2 text-[9px] text-cyan-300 font-bold">
                          EVENT #{idx + 1}
                        </span>
                        <span className="text-slate-400 text-[10px]">ID: {evt.event_id}</span>
                        <span className="text-slate-400 text-[10px]">· {evt.event_type}</span>
                      </div>
                      <span className="text-[10px] text-slate-500">
                        Received: {formatEpoch(evt.event_receive_time, incident.created_at)}
                      </span>
                    </div>

                    {rawLog && (
                      <div>
                        <div className="flex items-center justify-between mb-0.5">
                          <span className="text-[9px] text-slate-500 uppercase">Raw Event Log:</span>
                          <button
                            onClick={() => copyToClipboard(String(rawLog))}
                            className="text-[9px] text-cyan-400 hover:text-cyan-300"
                          >
                            Copy Log
                          </button>
                        </div>
                        <pre className="p-2 rounded bg-slate-900 border border-slate-800 text-[10px] text-slate-300 overflow-x-auto whitespace-pre-wrap max-h-48 leading-relaxed selection:bg-cyan-900 selection:text-white">
                          {String(rawLog)}
                        </pre>
                      </div>
                    )}

                    {/* Generic Vendor Attributes Grid */}
                    {filteredAttrs.length > 0 && (
                      <div>
                        <span className="text-[9px] text-slate-500 uppercase block mb-1">
                          Parsed Vendor Attributes ({filteredAttrs.length}):
                        </span>
                        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-1.5">
                          {filteredAttrs.map(([attrKey, attrVal]) => (
                            <div key={attrKey} className="p-1.5 rounded bg-slate-900/60 border border-slate-800/80 overflow-hidden">
                              <span className="text-[9px] text-slate-400 block truncate" title={attrKey}>
                                {attrKey}
                              </span>
                              <span className="text-slate-200 text-xs font-medium break-all" title={String(attrVal)}>
                                {typeof attrVal === "object" ? JSON.stringify(attrVal) : String(attrVal)}
                              </span>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Tab 3: Detection Intelligence Context */}
      {activeTab === "rule" && (
        <div className="rounded-lg border border-slate-800 bg-slate-950 p-3.5 space-y-3">
          <div className="flex items-center justify-between border-b border-slate-800 pb-2">
            <div>
              <h2 className="text-sm font-bold text-slate-100">{incident.rule_name || incident.event_type}</h2>
              <span className="text-xs font-mono text-cyan-400">{incident.event_type}</span>
            </div>
            {incident.rule_id && (
              <Link
                href={`/detection-intelligence/${incident.rule_id}`}
                className="rounded-md bg-cyan-600 px-2.5 py-1 text-xs font-semibold text-white hover:bg-cyan-500"
              >
                Open Full Detection Spec
              </Link>
            )}
          </div>

          <div className="text-xs text-slate-300">
            <span className="text-[10px] font-mono text-slate-500 block mb-0.5">Rule Description:</span>
            <p className="p-2.5 rounded-md bg-slate-900 border border-slate-800 text-xs">
              {incident.rule_description || "No standalone description available."}
            </p>
          </div>
        </div>
      )}

      {/* Tab 4: Historical Ground Truth */}
      {activeTab === "ground_truth" && (
        <div className="space-y-3">
          {blindReviewMode || !incident.ground_truth ? (
            <div className="rounded-lg border border-dashed border-amber-800/80 bg-amber-950/20 p-6 text-center text-xs">
              <EyeOff className="h-6 w-6 text-amber-400 mx-auto mb-1.5" />
              <h3 className="font-bold text-amber-300 text-xs">Ground Truth Masked in Blind Review Mode</h3>
              <p className="text-slate-400 mt-1 max-w-md mx-auto text-[11px]">
                Historical resolution and comments are hidden so you can test independent verdicts without bias.
              </p>
              <button
                onClick={() => setBlindReviewMode(false)}
                className="mt-3 rounded-md bg-amber-700/80 px-2.5 py-1 text-xs font-semibold text-white hover:bg-amber-600"
              >
                Disable Blind Review to Reveal
              </button>
            </div>
          ) : (
            <div className="rounded-lg border border-slate-800 bg-slate-950 p-3.5 space-y-3 text-xs font-mono">
              <div className="flex items-center justify-between border-b border-slate-800 pb-2.5">
                <div className="flex items-center gap-3">
                  <div>
                    <span className="text-[9px] text-slate-500 uppercase block">Historical Verdict Label:</span>
                    <span
                      className={`mt-0.5 inline-block px-2.5 py-0.5 rounded border text-xs font-bold ${
                        incident.ground_truth.resolution.includes("True")
                          ? "bg-rose-950 text-rose-300 border-rose-800"
                          : incident.ground_truth.resolution.includes("False")
                          ? "bg-emerald-950 text-emerald-300 border-emerald-800"
                          : "bg-slate-900 text-slate-400 border-slate-800"
                      }`}
                    >
                      {incident.ground_truth.resolution || "Unlabeled"}
                    </span>
                  </div>

                  <div>
                    <span className="text-[9px] text-slate-500 uppercase block">Status:</span>
                    <span className="mt-0.5 inline-flex items-center gap-1 px-2 py-0.5 rounded border text-[10px] font-bold bg-slate-900 text-slate-200 border-slate-800">
                      {incident.status_name}
                    </span>
                  </div>
                </div>

                <div className="flex items-center gap-2">
                  {incident.ground_truth.is_ml_generated && (
                    <span className="rounded bg-purple-950 text-purple-300 border border-purple-800 px-1.5 py-0.5 text-[9px] uppercase font-bold">
                      Machine Learning Note
                    </span>
                  )}
                  <button
                    onClick={handleSyncResolution}
                    disabled={syncingResolution}
                    className="inline-flex items-center gap-1 rounded bg-slate-900 border border-cyan-800/60 px-2.5 py-1 text-xs font-semibold text-cyan-300 hover:bg-slate-800 disabled:opacity-50 transition-colors"
                  >
                    <RefreshCw className={`h-3 w-3 ${syncingResolution ? "animate-spin text-cyan-400" : ""}`} />
                    <span>{syncingResolution ? "Syncing..." : "Sync from FortiSIEM"}</span>
                  </button>
                </div>
              </div>

              <div>
                <span className="text-[9px] text-slate-500 uppercase block mb-0.5">Cleared Reason:</span>
                <div className="p-2.5 rounded-md bg-slate-900 border border-slate-800 text-slate-200 text-xs">
                  {incident.ground_truth.cleared_reason || "None recorded."}
                </div>
              </div>

              <div>
                <span className="text-[9px] text-slate-500 uppercase block mb-0.5">Analyst / System Comments:</span>
                <div className="p-2.5 rounded-md bg-slate-900 border border-slate-800 text-slate-200 text-xs">
                  {incident.ground_truth.comments || "No historical comments."}
                </div>
              </div>

              <div className="grid grid-cols-2 gap-2 text-[10px] text-slate-400 border-t border-slate-800 pt-2">
                <div>Cleared User: {incident.ground_truth.cleared_user || "System / Unspecified"}</div>
                <div>Cleared Time: {formatEpoch(incident.ground_truth.cleared_time_epoch)}</div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Tab 5: Raw JSON Viewer */}
      {activeTab === "raw_json" && (
        <div className="rounded-lg border border-slate-800 bg-slate-950 p-3 space-y-2">
          <div className="flex items-center justify-between">
            <span className="text-xs font-mono text-slate-400">
              Unmodified original SIEM ingestion payload
            </span>
            <button
              onClick={() => copyToClipboard(JSON.stringify(incident.raw_payload, null, 2))}
              className="flex items-center gap-1.5 rounded-md border border-slate-800 bg-slate-900 px-2 py-0.5 text-xs text-slate-300 hover:text-white"
            >
              {copied ? <Check className="h-3 w-3 text-emerald-400" /> : <Copy className="h-3 w-3" />}
              {copied ? "Copied" : "Copy Payload"}
            </button>
          </div>
          <pre className="rounded-md bg-slate-900 border border-slate-800 p-3 font-mono text-[11px] text-cyan-300 overflow-x-auto max-h-[500px] overflow-y-auto">
            {JSON.stringify(incident.raw_payload, null, 2)}
          </pre>
        </div>
      )}

      {/* Tab 6: Evidence Integrity Guardrail */}
      {activeTab === "model_payload" && (
        <div className="rounded-lg border border-slate-800 bg-slate-950 p-3 space-y-2.5">
          <div className="flex items-center justify-between border-b border-slate-800 pb-2">
            <div>
              <h2 className="text-xs font-bold uppercase tracking-wider text-cyan-400 flex items-center gap-1.5">
                <ShieldCheck className="h-3.5 w-3.5" />
                Evidence Integrity Guardrail (Zero Leakage Verification)
              </h2>
              <p className="text-[10px] text-slate-400 mt-0.5">
                Whitelisted features sent to LLM pipelines. Resolution verdicts, analyst comments, and closure timestamps are strictly excluded.
              </p>
            </div>
            <button
              onClick={() => copyToClipboard(JSON.stringify(modelPayload, null, 2))}
              className="flex items-center gap-1.5 rounded-md border border-slate-800 bg-slate-900 px-2 py-0.5 text-xs text-slate-300 hover:text-white"
            >
              {copied ? <Check className="h-3 w-3 text-emerald-400" /> : <Copy className="h-3 w-3" />}
              {copied ? "Copied" : "Copy Model Input"}
            </button>
          </div>

          <pre className="rounded-md bg-slate-900 border border-slate-800 p-3 font-mono text-[11px] text-emerald-400 overflow-x-auto max-h-[500px] overflow-y-auto">
            {JSON.stringify(modelPayload, null, 2)}
          </pre>
        </div>
      )}

      {/* Tab 7: Historical Telemetry Timeline */}
      {activeTab === "timeline" && (
        <HistoricalTelemetryTimeline incidentId={incident.incident_id} />
      )}

      {/* Tab 8: Canonical Evidence Records */}
      {activeTab === "canonical_evidence" && (
        <div className="space-y-3 font-mono text-xs">
          <div className="flex items-center justify-between border-b border-slate-800 pb-2">
            <div>
              <h2 className="text-xs font-bold uppercase tracking-wider text-cyan-400 flex items-center gap-1.5">
                <Scale className="h-3.5 w-3.5" />
                Normalized Canonical Evidence Records
              </h2>
              <p className="text-[10px] text-slate-400 mt-0.5">
                Each SIEM field is normalized into an immutable, deterministically keyed evidence record with SHA-256 cryptographic digest.
              </p>
            </div>
            {modelPayload?.canonical_evidence && (
              <span className="text-[10px] text-slate-400">
                Total: <strong className="text-cyan-300">{modelPayload.canonical_evidence.length}</strong> items
              </span>
            )}
          </div>

          {!modelPayload?.canonical_evidence || modelPayload.canonical_evidence.length === 0 ? (
            <div className="p-8 rounded-lg border border-slate-800 bg-slate-950 text-center text-slate-400">
              No normalized canonical evidence records available for this incident.
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              {modelPayload.canonical_evidence.map((ev: any, idx: number) => (
                <div
                  key={ev.evidence_id || idx}
                  className="p-3 rounded-lg bg-slate-950 border border-slate-800 space-y-1.5 hover:border-slate-700 transition-colors"
                >
                  <div className="flex items-center justify-between border-b border-slate-800/80 pb-1">
                    <span className="text-[9px] bg-cyan-950 text-cyan-300 border border-cyan-800 px-1.5 py-0.2 rounded font-bold">
                      {ev.evidence_type || ev.evidence_category || "TELEMETRY"}
                    </span>
                    <button
                      onClick={() => copyToClipboard(ev.evidence_id)}
                      className="text-[9px] text-slate-400 hover:text-white"
                      title="Copy evidence ID"
                    >
                      {ev.evidence_id}
                    </button>
                  </div>

                  <div>
                    <span className="text-[9px] text-slate-500 block">Canonical Field:</span>
                    <span className="text-cyan-300 font-bold">{ev.source_field || ev.canonical_field}</span>
                    {(ev.raw_field_name || ev.source_system) && (
                      <span className="text-[10px] text-slate-500 ml-1.5">
                        ({ev.raw_field_name ? "raw: " : "src: "}
                        <span className="text-slate-400">{ev.raw_field_name || ev.source_system}</span>)
                      </span>
                    )}
                  </div>

                  <div>
                    <span className="text-[9px] text-slate-500 block">Observed Value:</span>
                    <div className="p-1.5 rounded bg-slate-900 border border-slate-800/80 text-slate-200 text-[11px] break-all max-h-24 overflow-y-auto">
                      {typeof ev.observed_value === "object"
                        ? JSON.stringify(ev.observed_value)
                        : String(ev.observed_value)}
                    </div>
                  </div>

                  <div className="flex items-center justify-between text-[9px] text-slate-500 pt-1 border-t border-slate-900">
                    <span>Event: {ev.source_event_id || "incident_level"}</span>
                    <span title={ev.integrity_digest}>
                      SHA: {ev.integrity_digest ? ev.integrity_digest.substring(0, 10) : "N/A"}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Actual LLM Prompt Inspector Modal */}
      <ActualPromptInspectorModal
        isOpen={promptInspectorOpen}
        onClose={() => setPromptInspectorOpen(false)}
        incidentId={incidentId}
        ruleId={incident?.rule_id}
        initialMode="capture"
      />
    </div>
  );
}

"use client";

import React, { useEffect, useState, Suspense } from "react";
import Link from "next/link";
import { useSearchParams, useRouter } from "next/navigation";
import {
  AlertTriangle,
  Search,
  Filter,
  Eye,
  EyeOff,
  ChevronLeft,
  ChevronRight,
  ExternalLink,
  Shield,
  Clock,
  Layers,
  ArrowUpDown,
  DownloadCloud,
  Sparkles,
  Loader2,
  Bot,
  CheckCircle2,
  AlertCircle,
  X,
  Cpu,
  Database,
  RefreshCw,
  Trash2,
} from "lucide-react";
import { api, IncidentListItem, IncidentAiVerdictResponse, IncidentMatchedRuleSummary } from "@/lib/api";
import { useApp } from "@/context/AppContext";
import { formatExecutionProvenanceBadge } from "@/lib/provenance";
import { CompactRuleScopeBar } from "@/components/compact/CompactDesignSystem";

function AITriageWorkbenchContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { user, blindReviewMode, setBlindReviewMode } = useApp();

  const [incidents, setIncidents] = useState<IncidentListItem[]>([]);
  const [total, setTotal] = useState(0);
  const [totalPages, setTotalPages] = useState(1);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(15);
  const [isLoading, setIsLoading] = useState(true);

  // Filters & Canonical Rule Disambiguation
  const [search, setSearch] = useState(searchParams.get("search") || "");
  const [exactRuleId, setExactRuleId] = useState(
    searchParams.get("exact_rule_id") || searchParams.get("rule_id") || ""
  );
  const [ruleOptions, setRuleOptions] = useState<
    Array<{ id: string; rule_id: string; name: string; event_type: string }>
  >([]);
  const [matchedRules, setMatchedRules] = useState<IncidentMatchedRuleSummary[]>([]);
  const [distinctRuleCount, setDistinctRuleCount] = useState(0);
  const [combinesMultipleRules, setCombinesMultipleRules] = useState(false);
  const [exactRuleMeta, setExactRuleMeta] = useState<{
    rule_uuid?: string | null;
    logical_rule_id?: string | null;
    rule_name?: string | null;
  } | null>(null);
  const [severity, setSeverity] = useState("");
  const [status, setStatus] = useState("");
  const [resolution, setResolution] = useState("");

  // AI Verdict Modal & Loading State
  const [analyzingId, setAnalyzingId] = useState<string | null>(null);
  const [aiVerdict, setAiVerdict] = useState<IncidentAiVerdictResponse | null>(null);
  const [verdictError, setVerdictError] = useState<string | null>(null);
  const [syncingResolutions, setSyncingResolutions] = useState(false);
  const [syncStatusMsg, setSyncStatusMsg] = useState<string | null>(null);
  const [llmOnline, setLlmOnline] = useState<boolean | null>(null);

  useEffect(() => {
    let mounted = true;
    api.getLlmStatus()
      .then((res) => {
        if (mounted) setLlmOnline(Boolean(res?.is_healthy));
      })
      .catch(() => {
        if (mounted) setLlmOnline(false);
      });
    const onStatus = (e: Event) => {
      const detail = (e as CustomEvent).detail;
      if (mounted && detail && typeof detail.is_healthy === "boolean") {
        setLlmOnline(detail.is_healthy);
      }
    };
    window.addEventListener("llm-status-change", onStatus);
    return () => {
      mounted = false;
      window.removeEventListener("llm-status-change", onStatus);
    };
  }, []);

  const handleSyncResolutions = async () => {
    setSyncingResolutions(true);
    setSyncStatusMsg(null);
    try {
      const res = await api.syncFortiSiemResolutions();
      setSyncStatusMsg(res.message);
      loadIncidents();
      setTimeout(() => setSyncStatusMsg(null), 6000);
    } catch (err: any) {
      setSyncStatusMsg(`Sync error: ${err.message}`);
      setTimeout(() => setSyncStatusMsg(null), 6000);
    } finally {
      setSyncingResolutions(false);
    }
  };

  const [purgingIncidents, setPurgingIncidents] = useState(false);

  const handlePurgeIncidents = async () => {
    if (
      !window.confirm(
        "Are you sure you want to permanently delete all incident records from the database? All detection rules, approved policies, users, and audit logs will be preserved."
      )
    ) {
      return;
    }
    setPurgingIncidents(true);
    setSyncStatusMsg(null);
    try {
      const res = await api.purgeAllIncidents();
      setSyncStatusMsg(res.message || "All incidents successfully purged from database.");
      await loadIncidents();
      setTimeout(() => setSyncStatusMsg(null), 8000);
    } catch (err: any) {
      setSyncStatusMsg(`Purge error: ${err.message}`);
      setTimeout(() => setSyncStatusMsg(null), 8000);
    } finally {
      setPurgingIncidents(false);
    }
  };

  const handleRequestAiVerdict = async (incidentId: string) => {
    setAnalyzingId(incidentId);
    setVerdictError(null);
    try {
      const verdict = await api.getIncidentAiVerdict(incidentId);
      setAiVerdict(verdict);
      setIncidents((prev) =>
        prev.map((item) => (item.incident_id === incidentId ? { ...item, ai_verdict: verdict } : item))
      );
    } catch (err: any) {
      setVerdictError(err.message || "Failed to generate AI verdict from Local LLM.");
    } finally {
      setAnalyzingId(null);
    }
  };

  useEffect(() => {
    let mounted = true;
    api.getRules({ page: 1, page_size: 100 })
      .then((res) => {
        if (mounted && Array.isArray(res?.items)) {
          setRuleOptions(
            res.items.map((r: any) => ({
              id: r.id,
              rule_id: r.rule_id,
              name: r.name,
              event_type: r.event_type,
            }))
          );
        }
      })
      .catch(() => {
        /* ignore rule catalog fetch warning */
      });
    return () => {
      mounted = false;
    };
  }, []);

  const loadIncidents = async () => {
    setIsLoading(true);
    try {
      const data = await api.getIncidents({
        page,
        page_size: pageSize,
        search: search || undefined,
        exact_rule_id: exactRuleId || undefined,
        severity: severity || undefined,
        status: status || undefined,
        resolution: resolution || undefined,
        blind_review: blindReviewMode,
      });
      setIncidents(data.items);
      setTotal(data.total);
      setTotalPages(data.total_pages);
      setMatchedRules(Array.isArray(data.matched_rules) ? data.matched_rules : []);
      setDistinctRuleCount(Number(data.distinct_rule_count ?? 0));
      setCombinesMultipleRules(Boolean(data.combines_multiple_rules));
      setExactRuleMeta(
        data.exact_rule_id || data.exact_logical_rule_id
          ? {
              rule_uuid: data.exact_rule_id,
              logical_rule_id: data.exact_logical_rule_id,
              rule_name: data.exact_rule_name,
            }
          : null
      );
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadIncidents();
  }, [page, pageSize, severity, status, resolution, exactRuleId, blindReviewMode]);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setPage(1);
    loadIncidents();
  };

  const getSeverityBadge = (sev: string) => {
    switch (sev?.toUpperCase()) {
      case "CRITICAL":
        return "bg-rose-950 text-rose-300 border-rose-800";
      case "HIGH":
        return "bg-orange-950 text-orange-300 border-orange-800";
      case "MEDIUM":
        return "bg-amber-950 text-amber-300 border-amber-800";
      case "LOW":
        return "bg-blue-950 text-blue-300 border-blue-800";
      default:
        return "bg-slate-800 text-slate-300 border-slate-700";
    }
  };

  const getVerdictBadge = (verdict?: string) => {
    if (!verdict) return "bg-slate-800 text-slate-400 border-slate-700";
    if (verdict.includes("Hidden")) {
      return "bg-amber-950/60 text-amber-400 border-amber-800/80 italic";
    }
    if (verdict.includes("True Positive")) {
      return "bg-rose-950/80 text-rose-300 border-rose-800";
    }
    if (verdict.includes("False Positive")) {
      return "bg-emerald-950/80 text-emerald-300 border-emerald-800";
    }
    return "bg-slate-800 text-slate-300 border-slate-700";
  };

  const formatEpoch = (epoch?: number) => {
    if (!epoch) return "N/A";
    const ms = epoch < 1e11 ? epoch * 1000 : epoch;
    return new Date(ms).toLocaleString([], {
      dateStyle: "short",
      timeStyle: "medium",
    });
  };

  const formatIncidentOccurredTime = (inc: IncidentListItem) => {
    const epoch = inc.first_seen_epoch || inc.created_at_epoch || inc.last_seen_epoch;
    if (epoch) {
      const ms = epoch < 1e11 ? epoch * 1000 : epoch;
      return new Date(ms).toLocaleString([], {
        dateStyle: "short",
        timeStyle: "medium",
      });
    }
    if (inc.created_at) {
      try {
        return new Date(inc.created_at).toLocaleString([], {
          dateStyle: "short",
          timeStyle: "medium",
        });
      } catch {
        return "N/A";
      }
    }
    return "N/A";
  };

  return (
    <div className="space-y-3">
      {/* Page Header */}
      <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-base sm:text-lg font-bold tracking-tight text-slate-100 flex items-center gap-2">
            <AlertTriangle className="h-4 w-4 text-cyan-400" />
            AI Triage Workbench
          </h1>
          <p className="text-[11px] text-slate-400 mt-0.5">
            Autonomous incident triage, evidence evaluation, and verdict reasoning
          </p>
        </div>

        {/* Action Buttons */}
        <div className="flex items-center gap-2">
          <button
            onClick={handleSyncResolutions}
            disabled={syncingResolutions}
            className="flex items-center gap-1.5 rounded-md border border-purple-800 bg-purple-950/60 px-2.5 py-1 text-xs font-semibold text-purple-300 hover:bg-purple-900/80 transition-colors shadow-sm disabled:opacity-50"
            title="Sync latest resolutions, cleared reasons, and closure status from FortiSIEM across all incidents"
          >
            <RefreshCw className={`h-3.5 w-3.5 ${syncingResolutions ? "animate-spin text-purple-400" : "text-purple-400"}`} />
            <span>{syncingResolutions ? "Syncing..." : "Sync Resolutions"}</span>
          </button>

          <Link
            href="/telemetry-hub"
            className="flex items-center gap-1.5 rounded-md border border-cyan-800 bg-cyan-950/60 px-2.5 py-1 text-xs font-semibold text-cyan-300 hover:bg-cyan-900/80 transition-colors shadow-sm"
          >
            <DownloadCloud className="h-3.5 w-3.5 text-cyan-400" />
            <span>Pull Telemetry</span>
          </Link>

          {user?.role === "Administrator" && (
            <button
              type="button"
              onClick={handlePurgeIncidents}
              disabled={purgingIncidents}
              className="flex items-center gap-1.5 rounded-md border border-rose-800/80 bg-rose-950/60 px-2.5 py-1 text-xs font-semibold text-rose-300 hover:bg-rose-900/80 transition-colors shadow-sm disabled:opacity-50"
              title="Permanently remove all incident data from database (Admins only)"
            >
              <Trash2 className={`h-3.5 w-3.5 text-rose-400 ${purgingIncidents ? "animate-spin" : ""}`} />
              <span>{purgingIncidents ? "Purging..." : "Purge Incidents"}</span>
            </button>
          )}
        </div>
      </div>

      {syncStatusMsg && (
        <div className="rounded-lg border border-purple-800/80 bg-purple-950/40 p-2.5 text-xs text-purple-300 flex items-center gap-2.5 animate-fadeIn">
          <CheckCircle2 className="h-3.5 w-3.5 shrink-0 text-purple-400" />
          <div className="text-[11px] leading-tight font-medium">
            {syncStatusMsg}
          </div>
        </div>
      )}

      {blindReviewMode && (
        <div className="rounded-lg border border-amber-800/80 bg-amber-950/40 p-2.5 text-xs text-amber-300 flex items-center gap-2.5">
          <EyeOff className="h-3.5 w-3.5 shrink-0 text-amber-400" />
          <div className="text-[11px] leading-tight">
            <strong className="font-semibold text-amber-200">Blind Review Active:</strong> Ground truth verdicts, resolution notes, and machine learning comments are masked.
          </div>
        </div>
      )}
      {!blindReviewMode && (
        <div className="rounded-lg border border-slate-800 bg-slate-900/60 p-2.5 text-xs text-slate-300 flex items-center justify-between gap-2.5" data-testid="blind-review-off-banner">
          <div className="flex items-center gap-2">
            <Eye className="h-3.5 w-3.5 shrink-0 text-slate-400" />
            <span className="text-[11px] leading-tight">
              <strong className="font-semibold text-slate-200">Blind Review UI Preference: OFF</strong> — Server-enforced double-blind isolation remains active for unreviewed incidents.
            </span>
          </div>
          <span className="text-[10px] font-mono px-1.5 py-0.5 rounded bg-slate-800 text-slate-400 border border-slate-700">
            Server Isolation Active
          </span>
        </div>
      )}

      {/* Filter and Search Bar */}
      <div className="flex flex-col md:flex-row gap-2 rounded-lg border border-slate-800 bg-slate-950 p-2 sm:p-2.5">
        <form onSubmit={handleSearchSubmit} className="flex-1 relative">
          <Search className="absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-slate-400" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search Incident ID, Title, Source IP, Device or Event Type..."
            className="w-full rounded-md border border-slate-800 bg-slate-900 py-1 pl-8 pr-16 text-xs text-slate-200 placeholder-slate-500 focus:border-cyan-500 focus:outline-none"
          />
          <button
            type="submit"
            className="absolute right-1 top-1/2 -translate-y-1/2 rounded bg-cyan-600 px-2 py-0.5 text-[10px] font-medium text-white hover:bg-cyan-500"
          >
            Search
          </button>
        </form>

        <div className="flex flex-wrap gap-1.5 items-center">
          {/* Exact Canonical Rule Filter */}
          <select
            aria-label="Exact Rule Filter"
            value={exactRuleId}
            onChange={(e) => {
              setExactRuleId(e.target.value);
              setPage(1);
            }}
            className="max-w-[260px] rounded-md border border-slate-800 bg-slate-900 px-2 py-1 text-xs text-slate-300 focus:border-cyan-500 focus:outline-none"
          >
            <option value="">All Rules (No Exact Filter)</option>
            {ruleOptions.map((r) => (
              <option key={r.id} value={r.id}>
                {r.rule_id} — {r.name} ({r.id.slice(0, 8)})
              </option>
            ))}
          </select>

          {/* Severity */}
          <select
            value={severity}
            onChange={(e) => {
              setSeverity(e.target.value);
              setPage(1);
            }}
            className="rounded-md border border-slate-800 bg-slate-900 px-2 py-1 text-xs text-slate-300 focus:border-cyan-500 focus:outline-none"
          >
            <option value="">All Severities</option>
            <option value="CRITICAL">Critical</option>
            <option value="HIGH">High</option>
            <option value="MEDIUM">Medium</option>
            <option value="LOW">Low</option>
          </select>

          {/* Status */}
          <select
            value={status}
            onChange={(e) => {
              setStatus(e.target.value);
              setPage(1);
            }}
            className="rounded-md border border-slate-800 bg-slate-900 px-2 py-1 text-xs text-slate-300 focus:border-cyan-500 focus:outline-none"
          >
            <option value="">All Statuses</option>
            <option value="open">Open</option>
            <option value="closed">Closed</option>
          </select>

          {/* Historical Verdict */}
          {!blindReviewMode && (
            <select
              value={resolution}
              onChange={(e) => {
                setResolution(e.target.value);
                setPage(1);
              }}
              className="rounded-md border border-slate-800 bg-slate-900 px-2 py-1 text-xs text-slate-300 focus:border-cyan-500 focus:outline-none"
            >
              <option value="">All Verdicts</option>
              <option value="True Positive">True Positive</option>
              <option value="False Positive">False Positive</option>
            </select>
          )}

          {(search || exactRuleId || severity || status || resolution) && (
            <button
              onClick={() => {
                setSearch("");
                setExactRuleId("");
                setSeverity("");
                setStatus("");
                setResolution("");
                setPage(1);
              }}
              className="rounded-md border border-slate-700 bg-slate-800 px-2.5 py-1 text-xs text-slate-300 hover:text-white"
            >
              Reset
            </button>
          )}
        </div>
      </div>

      {/* Multi-Rule Search Disambiguation & Exact Canonical Rule Status Banners */}
      {/* Compact Canonical Rule Scope & Multi-Rule Warning Bar */}
      <CompactRuleScopeBar
        matchedRules={matchedRules}
        distinctRuleCount={distinctRuleCount}
        totalIncidents={total}
        exactRuleId={exactRuleId}
        onSelectExactRule={(ruleId) => {
          setExactRuleId(ruleId);
          setPage(1);
        }}
        onClearExactRule={() => {
          setExactRuleId("");
          setPage(1);
        }}
        exactRuleLabel={exactRuleMeta?.logical_rule_id}
      />

      {/* Incidents Table */}
      <div className="rounded-lg border border-slate-800 bg-slate-950 overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead>
              <tr className="border-b border-slate-800 bg-slate-900/60 text-[10px] font-mono text-slate-400">
                <th className="py-2 px-2.5 font-medium w-28">Incident ID</th>
                <th className="py-2 px-2.5 font-medium min-w-[200px]">Rule / Event Type</th>
                <th className="py-2 px-2.5 font-medium w-20">Severity</th>
                <th className="py-2 px-2.5 font-medium w-28">Source / IP</th>
                <th className="py-2 px-2.5 font-medium w-36">Occurred Time</th>
                <th className="py-2 px-2.5 font-medium w-20">Events</th>
                <th className="py-2 px-2.5 font-medium w-28">Historical Verdict</th>
                <th className="py-2 px-2.5 font-medium text-right sticky right-0 bg-slate-900/95 backdrop-blur-xs shadow-[-8px_0_12px_-4px_rgba(0,0,0,0.5)] w-36">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/60 font-mono">
              {isLoading ? (
                <tr>
                  <td colSpan={8} className="py-8 text-center text-slate-400 font-sans text-xs">
                    Loading incidents from database...
                  </td>
                </tr>
              ) : incidents.length === 0 ? (
                <tr>
                  <td colSpan={8} className="py-8 text-center text-slate-500 font-sans text-xs">
                    No matching incidents found for the selected filter criteria.
                  </td>
                </tr>
              ) : (
                incidents.map((inc) => (
                  <tr key={inc.id} className="hover:bg-slate-900/40 transition-colors">
                    <td className="py-1.5 px-2.5 font-bold text-slate-100">
                      <div className="flex items-center gap-1.5">
                        <Link
                          href={`/incidents/${inc.incident_id}`}
                          className="text-cyan-400 hover:underline"
                        >
                          {inc.incident_id}
                        </Link>
                      </div>
                      <div className="mt-0.5">
                        <span className={`px-1 py-0.2 rounded text-[8px] font-bold border ${
                          inc.status_name === "Manually Cleared"
                            ? "bg-purple-950/80 text-purple-300 border-purple-800"
                            : inc.status_code === 2
                            ? "bg-slate-900 text-slate-400 border-slate-800"
                            : "bg-blue-950/80 text-blue-300 border-blue-800"
                        }`}>
                          {inc.status_name}
                        </span>
                      </div>
                    </td>
                    <td className="py-1.5 px-2.5 text-slate-300">
                      <div className="font-semibold text-slate-200 truncate max-w-[240px]" title={inc.rule_name || inc.title}>
                        {inc.rule_name || inc.title}
                      </div>
                      <div className="text-[10px] font-mono text-cyan-400 truncate max-w-[240px]" title={`Logical Rule ID: ${inc.logical_rule_id || inc.event_type}`}>
                        {inc.logical_rule_id || inc.event_type}
                      </div>
                      <div className="text-[9px] text-slate-500 truncate max-w-[240px]" title={`Rule UUID: ${inc.rule_uuid || inc.rule_id || "unlinked"} | Event: ${inc.event_type}`}>
                        UUID: {inc.rule_uuid ? inc.rule_uuid.slice(0, 8) : (inc.rule_id ? inc.rule_id.slice(0, 8) : "unlinked")} • Evt: {inc.event_type}
                      </div>
                    </td>
                    <td className="py-1.5 px-2.5">
                      <span
                        className={`px-1.5 py-0.2 rounded border text-[9px] font-bold ${getSeverityBadge(
                          inc.severity
                        )}`}
                      >
                        {inc.severity}
                      </span>
                    </td>
                    <td className="py-1.5 px-2.5 text-slate-400">
                      <div>{inc.source_ip || "Internal"}</div>
                      <div className="text-[10px] text-slate-500">{inc.reporting_device}</div>
                    </td>
                    <td className="py-1.5 px-2.5 text-slate-300 text-[10px]" suppressHydrationWarning>
                      <div className="font-medium text-slate-200" suppressHydrationWarning>
                        {formatIncidentOccurredTime(inc)}
                      </div>
                      {inc.last_seen_epoch && inc.first_seen_epoch && inc.last_seen_epoch !== inc.first_seen_epoch && (
                        <div className="text-[9px] text-slate-500" suppressHydrationWarning>
                          Last: {formatEpoch(inc.last_seen_epoch)}
                        </div>
                      )}
                    </td>
                    <td className="py-1.5 px-2.5 text-slate-300">
                      <span className="rounded bg-slate-900 px-1.5 py-0.2 text-[9px] border border-slate-800">
                        {inc.event_count} evts
                      </span>
                    </td>
                    <td className="py-1.5 px-2.5">
                      <div className="flex flex-col gap-1 items-start">
                        <span
                          className={`px-1.5 py-0.2 rounded border text-[9px] font-bold ${getVerdictBadge(
                            inc.historical_resolution
                          )}`}
                          title={`Historical SOC Analyst Closure Verdict${inc.cleared_user ? ` (Cleared by: ${inc.cleared_user})` : ""}${inc.cleared_reason ? ` | Reason: ${inc.cleared_reason}` : ""}`}
                        >
                          {inc.historical_resolution || "Unlabeled"}
                        </span>
                        {!blindReviewMode && (inc.cleared_user || inc.cleared_reason) && (
                          <div
                            className="text-[9px] text-slate-400 leading-tight max-w-[150px] truncate"
                            title={`Analyst: ${inc.cleared_user || "N/A"}${inc.cleared_reason ? ` | Reason: ${inc.cleared_reason}` : ""}`}
                          >
                            {inc.cleared_user && <span className="text-slate-300 font-mono">@{inc.cleared_user} </span>}
                            {inc.cleared_reason && <span className="text-slate-500 italic truncate">"{inc.cleared_reason}"</span>}
                          </div>
                        )}
                        {!inc.ai_verdict && (
                          <span
                            className="px-1.5 py-0.2 rounded border text-[9px] font-mono text-slate-400 italic bg-slate-900/60 border-slate-800 flex items-center gap-1"
                            title="AI Verdict is protected by server-enforced double-blind review until an independent determination is submitted."
                          >
                            <EyeOff className="h-2.5 w-2.5 text-amber-500/80" />
                            AI: [Hidden - Blind Review]
                          </span>
                        )}
                        {inc.ai_verdict && (
                          <span
                            className={`px-1.5 py-0.2 rounded border text-[9px] font-semibold flex items-center gap-1 ${
                              inc.ai_verdict.verdict === "TRUE_POSITIVE"
                                ? "bg-rose-950/80 text-rose-300 border-rose-800"
                                : inc.ai_verdict.verdict === "FALSE_POSITIVE"
                                ? "bg-emerald-950/80 text-emerald-300 border-emerald-800"
                                : "bg-amber-950/80 text-amber-300 border-amber-800"
                            }`}
                            title={`Stored AI Verdict: ${inc.ai_verdict.verdict} (${inc.ai_verdict.confidence}%) | Time: ${inc.ai_verdict.latency_ms}ms | Tokens: ${inc.ai_verdict.total_tokens || "N/A"}`}
                          >
                            <Sparkles className="h-2.5 w-2.5" />
                            AI: {inc.ai_verdict.verdict === "TRUE_POSITIVE" ? "TP" : inc.ai_verdict.verdict === "FALSE_POSITIVE" ? "FP" : "ATTN"}
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="py-1.5 px-2.5 text-right font-sans sticky right-0 bg-slate-950/95 group-hover:bg-slate-900/95 backdrop-blur-xs shadow-[-8px_0_12px_-4px_rgba(0,0,0,0.5)]">
                      <div className="flex items-center justify-end gap-1.5">
                        {inc.ai_verdict ? (
                          <button
                            onClick={() => {
                              setAiVerdict(inc.ai_verdict || null);
                              setVerdictError(null);
                            }}
                            className="inline-flex items-center gap-1 rounded bg-slate-800 hover:bg-slate-700 text-cyan-300 border border-cyan-800/60 px-2 py-0.5 text-[11px] font-medium transition-all shadow-sm"
                            title="View stored AI verdict cached in database"
                          >
                            <Database className="h-3 w-3 text-cyan-400" />
                            <span>Stored Verdict</span>
                          </button>
                        ) : (
                          <button
                            onClick={() => handleRequestAiVerdict(inc.incident_id)}
                            disabled={analyzingId === inc.incident_id}
                            className="inline-flex items-center gap-1 rounded bg-emerald-950/70 hover:bg-emerald-900 text-emerald-300 border border-emerald-700/60 px-2 py-0.5 text-[11px] font-medium transition-all shadow-sm disabled:opacity-50"
                            title="Send to Verdictum Cortex Local LLM for instant AI security verdict"
                          >
                            {analyzingId === inc.incident_id ? (
                              <>
                                <Loader2 className="h-3 w-3 animate-spin text-emerald-400" />
                                <span>Analyzing...</span>
                              </>
                            ) : (
                              <>
                                <Sparkles className="h-3 w-3 text-emerald-400" />
                                <span>AI Verdict</span>
                              </>
                            )}
                          </button>
                        )}
                        <Link
                          href={`/incidents/${inc.incident_id}`}
                          className="inline-flex items-center gap-1 rounded bg-slate-900 px-2 py-0.5 text-[11px] font-medium text-cyan-400 hover:bg-slate-800 hover:text-cyan-300 border border-slate-800"
                        >
                          Inspect
                          <ExternalLink className="h-3 w-3" />
                        </Link>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination Bar */}
        <div className="flex items-center justify-between border-t border-slate-800 px-3 py-1.5 text-xs text-slate-400">
          <div>
            Showing <strong className="text-slate-200">{incidents.length}</strong> of{" "}
            <strong className="text-slate-200">{total}</strong> incidents
          </div>

          <div className="flex items-center gap-1.5">
            <button
              onClick={() => setPage(Math.max(1, page - 1))}
              disabled={page <= 1}
              className="rounded p-0.5 border border-slate-800 bg-slate-900 text-slate-300 disabled:opacity-40 hover:bg-slate-800"
            >
              <ChevronLeft className="h-3.5 w-3.5" />
            </button>
            <span className="font-mono text-slate-300 text-xs">
              Page {page} of {totalPages}
            </span>
            <button
              onClick={() => setPage(Math.min(totalPages, page + 1))}
              disabled={page >= totalPages}
              className="rounded p-0.5 border border-slate-800 bg-slate-900 text-slate-300 disabled:opacity-40 hover:bg-slate-800"
            >
              <ChevronRight className="h-3.5 w-3.5" />
            </button>
          </div>
        </div>
      </div>

      {/* AI Verdict Modal */}
      {(aiVerdict || verdictError) && (
        <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="w-full max-w-xl rounded-xl border border-slate-800 bg-slate-950 p-5 shadow-2xl space-y-4 font-sans text-slate-200 animate-in fade-in zoom-in-95 duration-150">
            {/* Modal Header */}
            <div className="flex items-start justify-between border-b border-slate-800 pb-3">
              <div className="space-y-1">
                <div className="flex items-center gap-2">
                  <span className="flex items-center gap-1.5 text-xs font-bold text-emerald-400 bg-emerald-950/60 border border-emerald-800 px-2 py-0.5 rounded">
                    <Sparkles className="h-3.5 w-3.5" />
                    Verdictum Cortex AI Verdict
                  </span>
                  {aiVerdict && (
                    <span className="text-xs font-mono text-slate-400">
                      Incident #{aiVerdict.incident_id}
                    </span>
                  )}
                </div>
                <h3 className="text-sm font-semibold text-slate-100">
                  {aiVerdict?.rule_name || "Incident Security Analysis"}
                </h3>
              </div>
              <button
                onClick={() => {
                  setAiVerdict(null);
                  setVerdictError(null);
                }}
                className="rounded p-1 text-slate-400 hover:text-slate-200 hover:bg-slate-800 transition-colors"
              >
                <X className="h-4 w-4" />
              </button>
            </div>

            {/* Error state */}
            {verdictError ? (
              <div className="rounded-lg border border-rose-800/80 bg-rose-950/40 p-4 text-xs text-rose-300 space-y-2">
                <div className="font-semibold flex items-center gap-1.5 text-rose-200">
                  <AlertCircle className="h-4 w-4 text-rose-400" />
                  Failed to Receive AI Verdict
                </div>
                <p className="text-[11px] text-rose-300/90">{verdictError}</p>
              </div>
            ) : aiVerdict && (
              <div className="space-y-3.5">
                {/* Verdict Banner */}
                <div
                  className={`rounded-lg border p-3 flex items-center justify-between ${
                    aiVerdict.verdict === "TRUE_POSITIVE"
                      ? "bg-rose-950/50 border-rose-800 text-rose-200"
                      : aiVerdict.verdict === "FALSE_POSITIVE"
                      ? "bg-emerald-950/50 border-emerald-800 text-emerald-200"
                      : "bg-amber-950/50 border-amber-800 text-amber-200"
                  }`}
                >
                  <div className="flex items-center gap-2.5">
                    {aiVerdict.verdict === "TRUE_POSITIVE" ? (
                      <AlertTriangle className="h-5 w-5 text-rose-400" />
                    ) : aiVerdict.verdict === "FALSE_POSITIVE" ? (
                      <CheckCircle2 className="h-5 w-5 text-emerald-400" />
                    ) : (
                      <AlertCircle className="h-5 w-5 text-amber-400" />
                    )}
                    <div>
                      <div className="text-[10px] uppercase font-mono tracking-wider opacity-80">
                        Model Determination
                      </div>
                      <div className="text-sm font-bold tracking-tight">
                        {aiVerdict.verdict.replace(/_/g, " ")}
                      </div>
                    </div>
                  </div>

                  <div className="text-right">
                    <div className="text-[10px] uppercase font-mono tracking-wider opacity-80">
                      Confidence
                    </div>
                    <div className="text-base font-extrabold font-mono">
                      {Math.round(aiVerdict.confidence)}%
                    </div>
                  </div>
                </div>

                {/* AI Reasoning */}
                <div className="rounded-lg border border-slate-800 bg-slate-900/60 p-3 space-y-1">
                  <div className="text-[10px] font-mono uppercase text-slate-400 tracking-wider flex items-center gap-1.5">
                    <Bot className="h-3 w-3 text-cyan-400" />
                    Analytical Justification
                  </div>
                  <p className="text-xs text-slate-200 leading-relaxed font-sans">
                    {aiVerdict.reason}
                  </p>
                </div>

                {/* Evidence points if any */}
                {aiVerdict.supporting_evidence && aiVerdict.supporting_evidence.length > 0 && (
                  <div className="rounded-lg border border-slate-800/80 bg-slate-900/40 p-3 space-y-1.5">
                    <div className="text-[10px] font-mono uppercase text-slate-400 tracking-wider">
                      Supporting Evidence Attributes
                    </div>
                    <ul className="text-xs space-y-1 text-slate-300 list-disc list-inside">
                      {aiVerdict.supporting_evidence.map((ev, idx) => (
                        <li key={idx} className="text-[11px] font-mono leading-tight">
                          {ev}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                {/* Missing Evidence / Questions if any */}
                {aiVerdict.missing_evidence && aiVerdict.missing_evidence.length > 0 && (
                  <div className="rounded-lg border border-amber-900/40 bg-amber-950/20 p-3 space-y-1.5">
                    <div className="text-[10px] font-mono uppercase text-amber-400 tracking-wider">
                      Missing Evidence / Context Needed
                    </div>
                    <ul className="text-xs space-y-1 text-amber-300 list-disc list-inside">
                      {aiVerdict.missing_evidence.map((me, idx) => (
                        <li key={idx} className="text-[11px] leading-tight">
                          {me}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                {/* Model Metadata Footer */}
                <div className="flex flex-col gap-2 text-[10px] font-mono text-slate-400 pt-2 border-t border-slate-800/80">
                  <div className="flex items-center justify-between">
                    <div>
                      Engine: <span className="text-slate-300">{aiVerdict.model_identifier}</span>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className="inline-flex items-center gap-1 text-cyan-400 bg-cyan-950/60 border border-cyan-800/60 px-1.5 py-0.5 rounded text-[10px]">
                        <Database className="h-3 w-3" />
                        Stored in DB
                      </span>
                      {(() => {
                        const pb = formatExecutionProvenanceBadge({
                          executionProvenance: aiVerdict.execution_provenance,
                          isSimulated: aiVerdict.is_simulated,
                          validationStatus: aiVerdict.validation_status,
                          modelIdentifier: aiVerdict.model_identifier,
                          currentS2Health: llmOnline ? "ONLINE" : "OFFLINE",
                        });
                        const text =
                          aiVerdict.validation_status === "INVALID_MODEL_OUTPUT"
                            ? "• INVALID_MODEL_OUTPUT (Abstained)"
                            : pb.label === "SIMULATED"
                            ? "• SIMULATED (Non-Production)"
                            : ["POLICY_GUARD", "PREFLIGHT_GUARD", "TOKEN_BUDGET_GUARD", "VALIDATION_GUARD"].includes(pb.label)
                            ? `• Deterministic Guard (${aiVerdict.model_identifier || pb.label})`
                            : pb.label === "LIVE_PROVIDER"
                            ? llmOnline
                              ? `• LIVE_PROVIDER (${aiVerdict.model_identifier || "Verdictum Cortex"}) • Cortex Online`
                              : `• Historical Live Record (Cortex Offline Now) • LIVE_PROVIDER`
                            : `• ${pb.label} (${aiVerdict.model_identifier || "Model"}) • Cortex: ${llmOnline ? "ONLINE" : "OFFLINE"}`;
                        return (
                          <span
                            className={`px-1.5 py-0.5 rounded border font-semibold ${pb.className}`}
                            title={pb.sublabel}
                          >
                            {text}
                          </span>
                        );
                      })()}
                    </div>
                  </div>

                  <div className="flex flex-wrap items-center justify-between gap-2 bg-slate-900/90 border border-slate-800 px-2.5 py-1.5 rounded text-slate-300">
                    <div className="flex items-center gap-1.5">
                      <Clock className="h-3 w-3 text-cyan-400" />
                      <span>Time Consumed:</span>
                      <strong className="text-white">
                        {aiVerdict.latency_ms} ms {aiVerdict.latency_ms ? `(${(aiVerdict.latency_ms / 1000).toFixed(2)}s)` : ""}
                      </strong>
                    </div>
                    <div className="flex items-center gap-1.5">
                      <Cpu className="h-3 w-3 text-purple-400" />
                      <span>Tokens:</span>
                      <strong className="text-purple-300">
                        {aiVerdict.total_tokens || 0}
                      </strong>
                      {(aiVerdict.prompt_tokens !== undefined || aiVerdict.completion_tokens !== undefined) && (
                        <span className="text-slate-500 text-[9px]">
                          ({aiVerdict.prompt_tokens || 0} prompt / {aiVerdict.completion_tokens || 0} completion)
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Modal Actions */}
            <div className="flex items-center justify-between gap-2 pt-2 border-t border-slate-800">
              <div>
                {aiVerdict && (
                  <button
                    onClick={() => handleRequestAiVerdict(aiVerdict.incident_id)}
                    disabled={analyzingId === aiVerdict.incident_id}
                    className="inline-flex items-center gap-1.5 rounded-md border border-emerald-700/80 bg-emerald-950/80 hover:bg-emerald-900 px-2.5 py-1 text-xs font-semibold text-emerald-300 shadow-sm transition-all disabled:opacity-50"
                    title="Re-run inference on Verdictum Cortex GPU"
                  >
                    {analyzingId === aiVerdict.incident_id ? (
                      <>
                        <Loader2 className="h-3.5 w-3.5 animate-spin text-emerald-400" />
                        <span>Re-evaluating...</span>
                      </>
                    ) : (
                      <>
                        <RefreshCw className="h-3.5 w-3.5 text-emerald-400" />
                        <span>Re-evaluate AI Verdict</span>
                      </>
                    )}
                  </button>
                )}
              </div>
              <div className="flex items-center gap-2">
                {aiVerdict && (
                  <Link
                    href={`/incidents/${aiVerdict.incident_id}`}
                    className="rounded-md border border-slate-700 bg-slate-800 px-3 py-1 text-xs font-medium text-slate-200 hover:bg-slate-700 transition-colors"
                  >
                    View Full Incident Detail
                  </Link>
                )}
                <button
                  onClick={() => {
                    setAiVerdict(null);
                    setVerdictError(null);
                  }}
                  className="rounded-md bg-cyan-600 px-3 py-1 text-xs font-semibold text-white hover:bg-cyan-500 transition-colors"
                >
                  Close
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default function AITriageWorkbenchPage() {
  return (
    <Suspense
      fallback={
        <div className="flex h-64 items-center justify-center text-slate-400 text-xs font-mono">
          Loading AI Triage Workbench...
        </div>
      }
    >
      <AITriageWorkbenchContent />
    </Suspense>
  );
}

"use client";

import React, { useEffect, useState, use } from "react";
import Link from "next/link";
import {
  FileCode2,
  ArrowLeft,
  Copy,
  Check,
  AlertTriangle,
  Layers,
  Shield,
  Clock,
  ExternalLink,
} from "lucide-react";
import { api, RuleItem } from "@/lib/api";
import { copyToClipboard as copyTextToClipboard } from "@/lib/clipboard";

export default function DetectionIntelligenceDetailPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const resolvedParams = use(params);
  const ruleId = resolvedParams.id;

  const [rule, setRule] = useState<RuleItem | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function loadRule() {
      setIsLoading(true);
      try {
        const data = await api.getRuleDetail(ruleId);
        setRule(data);
      } catch (err: any) {
        setError(err.message || "Failed to load detection rule");
      } finally {
        setIsLoading(false);
      }
    }
    loadRule();
  }, [ruleId]);

  const copyToClipboard = async (text: string) => {
    if (!text) return;
    const success = await copyTextToClipboard(text);
    if (success) {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  if (isLoading) {
    return (
      <div className="flex h-96 items-center justify-center text-slate-400 text-xs">
        Loading detection intelligence details...
      </div>
    );
  }

  if (error || !rule) {
    return (
      <div className="space-y-4">
        <Link href="/detection-intelligence" className="inline-flex items-center gap-1.5 text-xs text-cyan-400 hover:underline">
          <ArrowLeft className="h-3.5 w-3.5" /> Back to Detection Intelligence
        </Link>
        <div className="rounded-xl border border-rose-800 bg-rose-950/40 p-6 text-rose-300 text-xs">
          {error || "Detection Rule not found"}
        </div>
      </div>
    );
  }

  const triggeredAttrs = rule.parsed_metadata?.triggered_attributes || [];

  return (
    <div className="space-y-3.5">
      {/* Top Header */}
      <div className="flex flex-col gap-2.5 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex items-center gap-2.5">
          <Link
            href="/detection-intelligence"
            className="flex h-7 w-7 items-center justify-center rounded-md border border-slate-800 bg-slate-900 text-slate-300 hover:bg-slate-800 hover:text-white"
            title="Back to Detection Intelligence"
          >
            <ArrowLeft className="h-3.5 w-3.5" />
          </Link>
          <div>
            <div className="flex items-center gap-1.5">
              <span className="font-mono text-[11px] text-slate-400">Detection Rule:</span>
              <span className="font-mono font-bold text-cyan-400 text-xs">{rule.event_type}</span>
              <span className="rounded bg-slate-800 border border-slate-700 px-1.5 py-0.2 text-[9px] font-bold text-slate-200">
                {rule.severity}
              </span>
              <span
                className={`rounded px-1.5 py-0.2 text-[9px] font-mono border ${
                  rule.status === "ACTIVE"
                    ? "bg-emerald-950 text-emerald-300 border-emerald-800"
                    : "bg-slate-900 text-slate-400 border-slate-800"
                }`}
              >
                {rule.status}
              </span>
            </div>
            <h1 className="text-sm sm:text-base font-bold text-slate-100 mt-0.5">{rule.name}</h1>
          </div>
        </div>

        <div>
          <Link
            href={`/ai-triage-workbench?rule_id=${encodeURIComponent(rule.event_type)}`}
            className="flex items-center gap-1.5 rounded-md bg-cyan-600 px-2.5 py-1 text-xs font-semibold text-white hover:bg-cyan-500 shadow-sm"
          >
            <AlertTriangle className="h-3.5 w-3.5" />
            View {rule.incident_count} Linked Incidents
          </Link>
        </div>
      </div>

      {/* Main Metadata Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-3">
        <div className="lg:col-span-2 space-y-3">
          {/* Rule Description & Remediation */}
          <div className="rounded-lg border border-slate-800 bg-slate-950 p-3 sm:p-3.5 space-y-2.5 text-xs">
            <h2 className="font-bold uppercase tracking-wider text-slate-300 text-xs">
              Rule Overview &amp; Context Description
            </h2>
            <div className="p-2.5 rounded-md bg-slate-900 border border-slate-800 leading-relaxed text-slate-200 text-xs">
              {rule.description || "No description provided."}
            </div>

            {rule.remediation && (
              <div className="space-y-1">
                <span className="text-[10px] uppercase font-mono text-cyan-400 block">
                  Remediation &amp; Triage Guidance:
                </span>
                <div className="p-2.5 rounded-md bg-cyan-950/20 border border-cyan-800/60 leading-relaxed text-cyan-200 font-mono text-[11px]">
                  {rule.remediation}
                </div>
              </div>
            )}
          </div>

          {/* Detection Logic & Pattern */}
          <div className="rounded-lg border border-slate-800 bg-slate-950 p-3 sm:p-3.5 space-y-2 text-xs">
            <div className="flex items-center justify-between">
              <h2 className="font-bold uppercase tracking-wider text-slate-300 text-xs">
                Detection Logic &amp; Correlation Pattern
              </h2>
              <button
                onClick={() => copyToClipboard(rule.pattern_logic)}
                className="flex items-center gap-1 rounded bg-slate-900 border border-slate-800 px-2 py-0.5 text-[11px] text-slate-300 hover:text-white"
              >
                {copied ? <Check className="h-3 w-3 text-emerald-400" /> : <Copy className="h-3 w-3" />}
                Copy Pattern
              </button>
            </div>
            <pre className="p-2.5 rounded-md bg-slate-900 border border-slate-800 font-mono text-[11px] text-slate-300 overflow-x-auto whitespace-pre-wrap leading-relaxed max-h-56">
              {rule.pattern_logic || "No pattern condition defined."}
            </pre>
          </div>

          {/* Raw Rule Definition Text */}
          <div className="rounded-lg border border-slate-800 bg-slate-950 p-3 sm:p-3.5 space-y-2 text-xs">
            <div className="flex items-center justify-between">
              <h2 className="font-bold uppercase tracking-wider text-slate-300 text-xs">
                Raw Rule Definition Specification
              </h2>
              <button
                onClick={() => copyToClipboard(rule.raw_rule_text)}
                className="flex items-center gap-1 rounded bg-slate-900 border border-slate-800 px-2 py-0.5 text-[11px] text-slate-300 hover:text-white"
              >
                {copied ? <Check className="h-3 w-3 text-emerald-400" /> : <Copy className="h-3 w-3" />}
                Copy Raw Spec
              </button>
            </div>
            <pre className="p-2.5 rounded-md bg-slate-900 border border-slate-800 font-mono text-[10px] text-slate-400 overflow-x-auto whitespace-pre-wrap leading-relaxed max-h-64">
              {rule.raw_rule_text || "No raw text available."}
            </pre>
          </div>
        </div>

        {/* Right Info Sidebar */}
        <div className="space-y-3 font-mono text-xs">
          <div className="rounded-lg border border-slate-800 bg-slate-950 p-3 space-y-2">
            <h2 className="font-bold uppercase tracking-wider text-slate-300 border-b border-slate-800 pb-1 font-sans">
              Rule Attributes
            </h2>
            <div className="space-y-1.5 text-[11px]">
              <div>
                <span className="text-slate-500 block">Rule ID</span>
                <span className="text-slate-200">{rule.rule_id}</span>
              </div>
              <div>
                <span className="text-slate-500 block">Data Source</span>
                <span className="text-slate-200">{rule.data_source || "SIEM Telemetry"}</span>
              </div>
              <div>
                <span className="text-slate-500 block">Detection Technology</span>
                <span className="text-slate-200">{rule.detection_tech || "Standard Correlation"}</span>
              </div>
              <div>
                <span className="text-slate-500 block">Evaluation Mode</span>
                <span className="text-slate-200">{rule.evaluation_mode || "Continuous"}</span>
              </div>
            </div>
          </div>

          {triggeredAttrs.length > 0 && (
            <div className="rounded-lg border border-slate-800 bg-slate-950 p-3 space-y-2">
              <h2 className="font-bold uppercase tracking-wider text-slate-300 border-b border-slate-800 pb-1 font-sans">
                Triggered Attributes ({triggeredAttrs.length})
              </h2>
              <div className="flex flex-wrap gap-1">
                {triggeredAttrs.map((attr: string) => (
                  <span
                    key={attr}
                    className="rounded bg-slate-900 px-1.5 py-0.2 text-[10px] text-cyan-300 border border-slate-800"
                  >
                    {attr}
                  </span>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

