          <span>Zero LLM dependencies active during Phase 1 foundation.</span>
          <span className="inline-flex items-center gap-1.5">
            <BrandLogo size={16} />
            Verdictum AI Protocol v1.0
          </span>
        </div>
      </div>
    </div>
  );
}

