              <strong className="text-emerald-300 text-xs">{historyData.stats.server_2.latency.avg} ms</strong>{" "}
              <span className="text-[10px] text-slate-500">(Min: {historyData.stats.server_2.latency.min} ms)</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

