"use client";

import React, { createContext, useContext, useState, useEffect } from "react";
import { User, api } from "@/lib/api";

export type AppTheme = "obsidian" | "classic";

interface AppContextType {
  user: User | null;
  isLoading: boolean;
  blindReviewMode: boolean;
  setBlindReviewMode: (enabled: boolean) => void;
  login: (username: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
  theme: AppTheme;
  toggleTheme: () => void;
  refreshUser: () => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

function applyThemeToDocument(nextTheme: AppTheme) {
  if (typeof document === "undefined") return;
  document.documentElement.setAttribute("data-theme", nextTheme);
  document.documentElement.classList.add("dark");
}

export function AppProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [blindReviewMode, setBlindReviewState] = useState<boolean>(true);
  const [theme, setTheme] = useState<AppTheme>("obsidian");

  useEffect(() => {
    // Load stored preferences (defaults to true for SOC double-blind integrity)
    const storedBlind = localStorage.getItem("ai_verdict_blind_review");
    if (storedBlind !== null) {
      setBlindReviewState(storedBlind === "true");
    } else {
      setBlindReviewState(true);
      localStorage.setItem("ai_verdict_blind_review", "true");
    }

    const rawStoredTheme = localStorage.getItem("ai_verdict_theme");
    const resolvedTheme: AppTheme =
      rawStoredTheme === "classic" ? "classic" : "obsidian";
    setTheme(resolvedTheme);
    applyThemeToDocument(resolvedTheme);

    // Check user session
    refreshUser();
  }, []);

  const refreshUser = async () => {
    if (
      typeof window !== "undefined" &&
      window.location.pathname === "/login" &&
      !localStorage.getItem("ai_verdict_token")
    ) {
      setUser(null);
      setIsLoading(false);
      return;
    }
    setIsLoading(true);
    try {
      const u = await api.getMe();
      setUser(u);
      localStorage.setItem("ai_verdict_user", JSON.stringify(u));
    } catch {
      setUser(null);
      if (typeof window !== "undefined") {
        localStorage.removeItem("ai_verdict_user");
        localStorage.removeItem("ai_verdict_token");
      }
    } finally {
      setIsLoading(false);
    }
  };

  const setBlindReviewMode = (enabled: boolean) => {
    setBlindReviewState(enabled);
    localStorage.setItem("ai_verdict_blind_review", enabled ? "true" : "false");
  };

  const toggleTheme = () => {
    const next: AppTheme = theme === "obsidian" ? "classic" : "obsidian";
    setTheme(next);
    localStorage.setItem("ai_verdict_theme", next);
    applyThemeToDocument(next);
  };

  const login = async (username: string, password: string) => {
    const res = await api.login(username, password);
    if (res.access_token) {
      localStorage.setItem("ai_verdict_token", res.access_token);
      localStorage.setItem("ai_verdict_user", JSON.stringify(res.user));
      setUser(res.user);
      setIsLoading(false);
    }
  };

  const logout = async () => {
    try {
      await api.logout();
    } finally {
      if (typeof window !== "undefined") {
        localStorage.removeItem("ai_verdict_token");
        localStorage.removeItem("ai_verdict_user");
      }
      setUser(null);
      window.location.href = "/login";
    }
  };

  return (
    <AppContext.Provider
      value={{
        user,
        isLoading,
        blindReviewMode,
        setBlindReviewMode,
        login,
        logout,
        theme,
        toggleTheme,
        refreshUser,
      }}
    >
      {children}
    </AppContext.Provider>
  );
}

export function useApp() {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error("useApp must be used within an AppProvider");
  }
  return context;
}

// API Client for Verdictum AI Frontend

const API_BASE = "/api";

export interface User {
  id: string;
  username: string;
  email: string;
  full_name: string;
  role: "Administrator" | "SOC Analyst" | "Read-Only Viewer";
  is_active: boolean;
  created_at: string;
}

export interface IncidentAiVerdictResponse {
  incident_id: string;
  verdict: "TRUE_POSITIVE" | "FALSE_POSITIVE" | "REQUIRES_ATTENTION";
  proposed_verdict?: "TRUE_POSITIVE" | "FALSE_POSITIVE" | "REQUIRES_ATTENTION";
  confidence: number;
  raw_model_confidence?: number;
  reason: string;
  supporting_evidence: string[];
  supporting_claims?: Array<{
    claim_type: string;
    field: string;
    asserted_value: any;
    is_grounded: boolean;
    grounding_status: string;
    reason?: string;
  }>;
  missing_evidence: string[];
  analyst_questions: string[];
  latency_ms: number;
  model_identifier: string;
  is_simulated: boolean;
  execution_provenance?: string;
  configured_provider?: string;
  test_environment?: string | null;
  rule_name?: string;
  severity?: string;
  prompt_tokens?: number;
  completion_tokens?: number;
  total_tokens?: number;
  evaluated_at?: string;
  evaluated_by_user?: string;
  validation_status?: string;
  validation_reason_codes?: string[];
  confidence_scale?: string | null;
  confidence_interpretation?: string | null;
  normalized_confidence_percent?: number | null;
  reasoning_integrity_status?: string | null;
  reasoning_contradictions?: string[];
  semantic_review_notes?: string[];
  is_decisive_accepted?: boolean;
  proposal_validation_outcome?: string;
  final_disposition?: string;
  abstention_reason?: string | null;
  trust_score?: number | null;
  historical_trust_score?: number | null;
  trust_cap_applied?: boolean;
  trust_cap_reason?: string | null;
  trust_status?: string;
  evidence_completeness?: number;
  grounding_ratio?: number;
  total_claims_count?: number;
  grounded_claims_count?: number;
  unsupported_claims_count?: number;
  unsupported_claims?: Array<Record<string, any>>;
  detected_contradictions?: string[];
  analyst_action_directive?: string;
  canonical_evidence_count?: number;
  contract_id?: string;
  contract_version?: number;
  validator_version?: string;
  replay_signature?: string;
  compiler_version?: string;
  compilation_digest?: string;
  policy_sections_count?: number;
  policy_version_number?: number;
  policy_status?: string;
  calibration_status?: string;
  is_calibrated?: boolean;
  rag_retrieval_status?: string;
  retrieved_precedents_count?: number;
  retrieved_precedents?: Array<{
    precedent_id: string;
    incident_id: string;
    incident_title: string;
    rule_id: string;
    verified_verdict: string;
    analyst_explanation: string;
    similarity_score: number;
    feedback_timestamp: string;
  }>;
  token_budget_breakdown?: Record<string, any>;
  field_validation_status?: Record<string, string>;
  unmapped_fields?: Array<string | UnmappedField>;
}

export type CanonicalEvaluationStatus =
  | "NOT_EVALUATED"
  | "EVALUATED_DECISIVE"
  | "ABSTAINED"
  | "VALIDATION_REJECTED"
  | "EVALUATION_FAILED"
  | "QUEUED"
  | "RUNNING";

export interface AisEvaluationItem {
  incident_id: string;
  db_id: string;
  rule_id: string;
  title: string;
  event_type: string;
  customer?: string;
  created_at?: string | null;
  status: CanonicalEvaluationStatus;
  status_display: string;
  badge_color: "neutral" | "green" | "amber" | "red" | "blue";
  policy_version_number?: number | null;
  policy_version_id?: string | null;
  is_real_inference: boolean;
  is_simulated: boolean;
  execution_id?: string | null;
  prompt_capture_id?: string | null;
  model_name?: string | null;
  latency_ms?: number | null;
  token_usage?: { prompt_tokens?: number; completion_tokens?: number; total_tokens?: number } | null;
  captured_at?: string | null;
  raw_model_verdict?: string | null;
  effective_verdict?: string | null;
  confidence?: number | null;
  reason?: string | null;
  validation_status?: string | null;
  validation_failure_reason?: string | null;
  can_inspect_details?: boolean;
  has_existing_prompt_capture?: boolean;
  evaluation_attempts_count?: number;
  analyst_review?: {
    review_id: string;
    reviewer_id: string;
    analyst_verdict: string;
    ground_truth_status: string;
    reviewed_at?: string | null;
    comparison_outcome?: string | null;
  } | null;
}

export interface AisEvaluationSummary {
  rule_uuid: string;
  policy_version_number?: number | null;
  policy_version_id?: string | null;
  policy_status: string;
  customer: string;
  total_incidents: number;
  not_evaluated: number;
  evaluated_decisive: number;
  abstained: number;
  validation_rejected: number;
  evaluation_failed: number;
  queued: number;
  running: number;
  mock_only_count: number;
  total_analyst_reviews: number;
  matched_verified_reviews: number;
  eligible_decisive_comparisons: number;
  missing_evaluations_among_reviewed: number;
  decision_coverage_percent: number;
  abstention_rate_percent: number;
