export function formatApiErrorMessage(errData: any, fallbackMessage: string = "Operation failed"): string {
  if (!errData) return fallbackMessage;
  if (typeof errData === "string") return errData;
  if (typeof errData.detail === "string") return errData.detail;
  if (Array.isArray(errData.detail)) {
    const lines = errData.detail.map((item: any) => {
      if (typeof item === "string") return item;
      const loc = Array.isArray(item.loc)
        ? item.loc.filter((p: any) => p !== "body" && p !== "query" && p !== "path").join(".") || item.loc.join(".")
        : (item.loc || "field");
      return `${loc}: ${item.msg || "Invalid value"}`;
    });
    return lines.join("; ") || fallbackMessage;
  }
  if (typeof errData.message === "string") return errData.message;
  return fallbackMessage;
}

export async function fetchWithAuth(url: string, options: RequestInit = {}) {
  const token = typeof window !== "undefined" ? localStorage.getItem("ai_verdict_token") : null;
  const headers = new Headers(options.headers || {});
  if (token) {
    headers.set("Authorization", `Bearer ${token}`);
  }
  if (options.body && typeof options.body === "string" && !headers.has("Content-Type")) {
    headers.set("Content-Type", "application/json");
  }
  options.credentials = "include"; // For HttpOnly cookie support
  options.headers = headers;

  const res = await fetch(url, options);
  if (res.status === 401 && typeof window !== "undefined" && !window.location.pathname.includes("/login")) {
    localStorage.removeItem("ai_verdict_token");
    localStorage.removeItem("ai_verdict_user");
    window.location.href = "/login";
  }
  return res;
}

async function parseChatHttpError(res: Response): Promise<string> {
  const text = await res.text().catch(() => "");
  let detail = `Chatbot request failed (HTTP ${res.status})`;
  try {
    const parsed = JSON.parse(text);
    if (parsed?.detail) return parsed.detail;
  } catch {
    if (res.status === 504) {
      return "Gateway Timeout (504): Reverse proxy or Verdictum Cortex timed out waiting for LLM response.";
    }
  }
  return detail;
}

